import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"П’ятичисленні молитви","e":"Prayers in Fives","secs":[{"ps":["§(Читаються за благословенням духівника)"]},{"h":"Твір святителя Димитрія Ростовського","ps":[]},{"h":"Початок цих молитов","ps":["Сла́ва Тебі́, Христу́ Бо́гу Моєму́, не погуби́вшему м'я грі́шнаго со беззако́ньми мої́ми, но да́же досе́лі гріхо́м мої́м потерпе́вшему. (поклін)","Сподо́би, Го́споди, в день сей без гріха́ сохрани́тися нам; да́руй мі, Го́споди, да ні сло́вом, ні ді́лом, ні помишле́нієм прогні́ваю Тя, Созда́теля моєго́, но вся діла́ моя́, сові́ти і помишле́нія да бу́дуть во сла́ву Пресвята́го і́мені Твоєго́. (поклін)","Бо́же, ми́лостив бу́ди мні, грі́шному, во всей жи́зні моє́й: во ісхо́ді моє́м і по кончи́ні моє́й не оста́ви мене́. (поклін)"]},{"h":"Це, впавши ниць на землю, промовляй","ps":["Го́споди Ісу́се Христе́, Си́не Бо́жий, прийми́ уме́ршаго м'я душе́ю і умо́м. Прийми́ м'я грі́шнаго, блудника́, скве́рнаго душе́ю і ті́лом. Отими́ неприя́знь безсту́дную і не отврати́ лиця́ Твоєго́ от мене́, не рци, Влади́ко: «Не вім, кто єси́», но во́ньми гла́су моле́нія моєго́; спаси́ м'я, я́ко імі́яй мно́жество щедро́т і не хо́щеши сме́рти грі́шника; не оста́влю же Тя, Созда́теля моєго́, і не отступлю́ от Тебе́, до́ндеже послу́шаєши м'я і да́си всім гріхо́м мої́м проще́ніє, моли́тв ра́ди Пречи́стия Ма́тері Твоєя́, предста́тельства Честни́х Небе́сних Сил безпло́тних, свята́го сла́внаго А́нгела храни́теля моєго́, Проро́ка же і Предте́чі і Крести́теля Іоа́нна, богоглаго́ливих Апо́стол, сві́тлих і добропобі́дних му́чеников, преподо́бних і богоно́сних оте́ць на́ших і всіх Твої́х святи́х, поми́луй і спаси́ м'я грі́шнаго. Амі́нь."]},{"h":"Молитва до Святого Духа","ps":["Царю́ Небе́сний, Уті́шителю, Ду́ше і́стини, І́же везді́ сий і вся ісполня́яй, Сокро́вище благи́х і жи́зні Пода́телю, прийди́ і всели́ся в ни, і очи́сти ни от вся́кия скве́рни, і спаси́, Бла́же, ду́ші на́ша."]},{"h":"Трисвяте","ps":["Святи́й Бо́же, Святи́й Крі́пкий, Святи́й Безсме́ртний, поми́луй нас. (читається тричі, з хресним знаменням і поясним поклоном.)","Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху, і ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва Господня","ps":["О́тче наш, І́же єси́ на небесі́х! Да святи́ться і́м'я Твоє́, да при́йдеть Ца́рствіє Твоє́, да бу́деть во́ля Твоя́, я́ко на небесі́ і на землі́. Хліб наш насу́щний даждь нам днесь; і оста́ви нам до́лги на́ша, я́коже і ми оставля́єм должнико́м на́шим; і не введи́ нас во іскуше́ніє, но ізба́ви нас от лука́ваго. Я́ко Твоє́ єсть Ца́рство і си́ла і сла́ва во ві́ки. Амі́нь."]},{"h":"Богородице Діво, радуйся","ps":["Богоро́дице Ді́во, ра́дуйся, благода́тная Марі́є, Госпо́дь с Тобо́ю, Благослове́нна Ти в жена́х і благослове́н Плод чре́ва Твоєго́, я́ко Спа́са родила́ єси́ душ на́ших."]},{"h":"Молитва 1-а","ps":["О, Ма́ти Милосе́рдая, Ді́во Марі́є, аз грі́шний і непотре́бний раб Твой, воспомина́ющи Твоя́ болі́зні, єгда́ Ти усли́шала от Симео́на Проро́ка о неми́лостивном убіє́нії Си́на Твоєго́, Го́спода на́шего Ісу́са Христа́, приношу́ сію́ Тебі́ моли́тву і Арха́нгельськоє обра́дованіє, прийми́ в честь і па́м'ять болі́зней Твої́х і умоли́ Си́на Твоєго́ — Го́спода на́шего Ісу́са Христа́, да да́руєть мі позна́ніє гріхо́в і жалі́ніє о них. (поклін)"]},{"h":"Молитва 2-а","ps":["О́тче наш, І́же єси́ на небесі́х! Да святи́ться і́м'я Твоє́, да при́йдеть Ца́рствіє Твоє́, да бу́деть во́ля Твоя́, я́ко на небесі́ і на землі́. Хліб наш насу́щний даждь нам днесь; і оста́ви нам до́лги на́ша, я́коже і ми оставля́єм должнико́м на́шим; і не введи́ нас во іскуше́ніє, но ізба́ви нас от лука́ваго. Я́ко Твоє́ єсть Ца́рство і си́ла і сла́ва во ві́ки. Амі́нь.","Богоро́дице Ді́во, ра́дуйся, благода́тная Марі́є, Госпо́дь с Тобо́ю, Благослове́нна Ти в жена́х і благослове́н Плод чре́ва Твоєго́, я́ко Спа́са родила́ єси́ душ на́ших.","О, Богоблаже́нная і Пренепоро́чная Отрокови́це, Ма́ти і Ді́во, прийми́ от мене́, грі́шнаго і непотре́бнаго раба́ Твоєго́, сію́ моли́тву і Арха́нгельськоє обра́дованіє в честь і па́м'ять болі́зні Твоєя́, єгда́ позаби́ла Си́на Твоєго́, Го́спода на́шего Ісу́са Христа́, в це́ркві і три дні Єго́ не ви́діла єси́; умоли́ Єго́ і іспроси́ у Него́ всіх гріхо́в мої́х проще́ніє і оставле́ніє, Єди́на Благослове́нная. (поклін)"]},{"h":"Молитва 3-а","ps":["О́тче наш, І́же єси́ на небесі́х! Да святи́ться і́м'я Твоє́, да при́йдеть Ца́рствіє Твоє́, да бу́деть во́ля Твоя́, я́ко на небесі́ і на землі́. Хліб наш насу́щний даждь нам днесь; і оста́ви нам до́лги на́ша, я́коже і ми оставля́єм должнико́м на́шим; і не введи́ нас во іскуше́ніє, но ізба́ви нас от лука́ваго. Я́ко Твоє́ єсть Ца́рство і си́ла і сла́ва во ві́ки. Амі́нь.","Богоро́дице Ді́во, ра́дуйся, благода́тная Марі́є, Госпо́дь с Тобо́ю, Благослове́нна Ти в жена́х і благослове́н Плод чре́ва Твоєго́, я́ко Спа́са родила́ єси́ душ на́ших.","О, Ма́ти Сві́та, Преблагослове́нная Ді́во Богоро́дице, прийми́ от мене́, грі́шнаго і непотре́бнаго раба́ Твоєго́ сію́ моли́тву і Арха́нгельськоє обра́дованіє в честь і па́м'ять болі́зні Твоєя́, єгда́ Си́на Твоєго́, Го́спода на́шего Ісу́са Христа́, по́ймана і свя́зана сли́шала єси́. Умоли́ Єго́, да возврати́ть мні доброді́телі, че́рез гріх ізги́бшия, да Тя, Пречи́стая, во ві́ки велича́ю. (поклін)"]},{"h":"Молитва 4-а","ps":["О́тче наш, І́же єси́ на небесі́х! Да святи́ться і́м'я Твоє́, да при́йдеть Ца́рствіє Твоє́, да бу́деть во́ля Твоя́, я́ко на небесі́ і на землі́. Хліб наш насу́щний даждь нам днесь; і оста́ви нам до́лги на́ша, я́коже і ми оставля́єм должнико́м на́шим; і не введи́ нас во іскуше́ніє, но ізба́ви нас от лука́ваго. Я́ко Твоє́ єсть Ца́рство і си́ла і сла́ва во ві́ки. Амі́нь.","Богоро́дице Ді́во, ра́дуйся, благода́тная Марі́є, Госпо́дь с Тобо́ю, Благослове́нна Ти в жена́х і благослове́н Плод чре́ва Твоєго́, я́ко Спа́са родила́ єси́ душ на́ших.","О, Милосе́рдія Істо́чниче, Ді́во Богоро́дице, прийми́ от мене́, грі́шнаго і непотре́бнаго раба́ Твоєго́, сію́ моли́тву і Арха́нгельськоє обра́дованіє в честь і па́м'ять болі́зні Твоєя́, єгда́ на Кресті́ ме́жду разбо́йники ви́діла єси́ Си́на Твоєго́, Го́спода на́шего Ісу́са Христа́, Єго́же умоли́, Влади́чице, да пода́сть мі дар милосе́рдія Своєго́ в час сме́рти моєя́ і да напита́єть м'я Ті́лом і Кро́вію Своє́ю Боже́ственною, да Тя, Засту́пницю, сла́влю во ві́ки. (поклін)"]},{"h":"Молитва 5-а","ps":["О́тче наш, І́же єси́ на небесі́х! Да святи́ться і́м'я Твоє́, да при́йдеть Ца́рствіє Твоє́, да бу́деть во́ля Твоя́, я́ко на небесі́ і на землі́. Хліб наш насу́щний даждь нам днесь; і оста́ви нам до́лги на́ша, я́коже і ми оставля́єм должнико́м на́шим; і не введи́ нас во іскуше́ніє, но ізба́ви нас от лука́ваго. Я́ко Твоє́ єсть Ца́рство і си́ла і сла́ва во ві́ки. Амі́нь.","Богоро́дице Ді́во, ра́дуйся, благода́тная Марі́є, Госпо́дь с Тобо́ю, Благослове́нна Ти в жена́х і благослове́н Плод чре́ва Твоєго́, я́ко Спа́са родила́ єси́ душ на́ших.","О, Наде́ждо моя́, Пречи́стая Ді́во Богоро́дице, прийми́ от мене́, грі́шнаго і непотре́бнаго раба́ Твоєго́, сію́ моли́тву і Арха́нгельськоє обра́дованіє в честь і па́м'ять болі́зні Твоєя́, єгда́ ви́діла єси́ Си́на Твоєго́, Го́спода на́шего Ісу́са Христа́, во гро́бі полага́єма. Єго́же умоли́, Влади́чице, да я́виться мні в час сме́рти моєя́ і да при́йметь ду́шу мою́ в живо́т ві́чний. Амі́нь. (поклін)","О, Преми́лостивая Ді́во, Госпоже́ Богоро́дице, чадолюби́вая Го́рлице, небесе́ і землі́ Самодержа́вная Цари́це, любе́зная Приє́мнице всіх простира́ющих к Тебі́ свої́ мольби́, печа́льних Уті́шительнице, прийми́ от мене́, грі́шнаго і непотре́бнаго раба́ Твоєго́, п'яточи́сленноє сіє́ моле́ніє, в нем же воспомина́ю земни́є і небе́сния Твоя́ ра́дости, уми́льно вопію́ща к Тебі́ си́це:","(Земні радості) Ра́дуйся, заче́ншая во чре́ві без сі́мене Христа́ Бо́га на́шего. Ра́дуйся, во чре́ві без болі́зні носи́вшая Того́. Ра́дуйся, поро́ждшая чу́дним смотре́нієм. Ра́дуйся, восприї́мшая от волхво́в‑царе́й дари́ і поклоне́ніє. Ра́дуйся, я́ко обріла́ єси́ посреди́ учи́телей Своєго́ Си́на і Бо́га. Ра́дуйся, я́ко Рождество́ Твоє́ пресла́вно із ме́ртвих воста́. Ра́дуйся, ви́дівшая вознося́щагося Своєго́ Созда́теля, к Нему́ же сама́ душе́ю і ті́лом возшла́ єси́.","(Небесні радості) Ра́дуйся, ді́вства ра́ди Своєго́, па́че А́нгел і всіх святи́х Пресла́вная. Ра́дуйся, близ Пресвяти́я Тро́йці просія́ющая. Ра́дуйся, Миротво́рице на́ша. Ра́дуйся, Власти́тельнице, облада́ющая всі́ми Небе́сними Си́лами. Ра́дуйся, па́че всіх дерзнове́ніє к Си́ну і Бо́гу Своєму́ іму́щая. Ра́дуйся, милосе́рдая Ма́ти всім, к Тебі́ прибега́ющим. Ра́дуйся, я́ко Твоє́ весе́ліє во ві́ки не сконча́ється!","І мні недосто́йному, по нело́жному обіща́нію Твоєму́, в день ісхо́да моєго́ ми́лостива предста́ни, да Твої́м руково́дством упра́влен бу́ду ко го́рнему Ієрусали́му, в нем же просла́вленно ца́рствуєши с Си́ном Твої́м і Бо́гом на́шим, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє со Отце́м і с Пресвяти́м Ду́хом безконе́чния ві́ки віко́в. Амі́нь.","От скве́рних усте́н мої́х, от ме́рзькаго се́рдця, от нечи́стаго язика́ і от душі́ оскверне́нной прийми́, Госпоже́ Цари́це, сіє́ похвале́ніє, Ра́досте моя́. Прийми́, я́коже вдо́вії прия́ла сії́ дві ле́пти, і да́руй мі принести́ Твоє́й бла́гості дар досто́їн. О, Влади́чице моя́ Пречи́стая Ді́во, Небе́сная Цари́це, я́коже хо́щеши і во́лиши, па́че же научи́ м'я, что мі подоба́єть Тебі́, Ма́тері Бо́жієй, глаго́лати к Тебі́ єди́ной грі́шних при́біжищу і утіше́нію. Ра́дуйся, Влади́чице, да і аз, многогрі́шний раб Твой, ра́достно зову́ Тебі́, всепі́той Ма́тері Христа́ Бо́га на́шего. Амі́нь.","На Твой Пресвяти́й о́браз взира́я, я́ко і́стинную са́мую Тя зрю Богоро́дицю, ві́рою серде́чною от душі́ припа́даю і поклоня́юся с Предві́чним на руку́ Твоє́ю держи́мим Младе́нцем, Го́сподом на́шим Ісу́сом Христо́м, боголі́пно почита́ю і молю́ Тя со слеза́ми: покри́й м'я покро́вом Твої́м, от враг ви́димих і неви́димих, Ти бо род челові́чеський ввела́ єси́ в Ца́рство Небе́сноє. Амі́нь.","§Потому:"]},{"h":"Достойно є","ps":["Досто́йно єсть я́ко воі́стину блажи́ти Тя, Богоро́дицю, Присноблаже́нную і Пренепоро́чную і Ма́тер Бо́га на́шего. Честні́йшую Херуви́м і сла́внійшую без сравне́нія Серафи́м, без істлі́нія Бо́га Сло́ва ро́ждшую, су́щую Богоро́дицю Тя велича́єм.","Сла́ва і благодаре́ніє Го́споду за все!"]}],"notes":[]},{"u":"Молитва перед навчанням отроків","e":"Prayer before the Teaching of Boys","secs":[{"ps":["Преблаги́й Го́споди, низпосли́ нам благода́ть Ду́ха Твоєго́ Свята́го, да́рствующаго і укріпля́ющаго душе́вния на́ша си́ли, даби́ внима́юще преподава́ємому нам уче́нію, возросли́ ми Тебі́, на́шему Созда́телю, во сла́ву, роди́телем же на́шим на утіше́ніє, Це́ркві і Оте́честву на по́льзу."]}],"notes":[]},{"u":"Молитва за згодою","e":"Prayer by Agreement","secs":[{"ps":["Го́споди, Ісу́се Христе́, Си́не Бо́жий, Ти бо рекл єси́ пречи́стими усти́ Твої́ми: \"Амі́нь глаго́лю вам, я́ко а́ще дво́є от вас совіща́ються на землі́ о вся́кой ве́щі, єє же а́ще просі́те, бу́дете імі́ть от Отця́ Моєго́, І́же на Небесі́х: гді же два іли́ тро́є собрались во і́м'я Моє́, ту єсьм Аз посреді́ їх\". Непрело́жни словеса́ Твоя́, Го́споди, милосе́рдіє Твоє́ безприкладно і человіколю́бію Твоєму́ ність конця́. Сего́ ра́ди мо́лим Тя: да́руй нам, раба́м Твої́м (імена), согласившимся просить Тя (прохання), ісполне́нія на́шего проше́нія. Но оба́че не я́коже ми хотим, но я́коже Ти. Да бу́деть во ві́ки во́ля Твоя́. Амі́нь."]}],"notes":[]},{"u":"Молитви про духовного отця","e":"Prayers for a Spiritual Father","secs":[{"h":"Молитва до Спасителя про духовного отця","ps":["О Сладча́йший Ісу́се! Ти безмі́рно свят, безмі́рно пра́веден, безмі́рно милосе́рд, освяти́ Твоє́ю святи́нею отця́ моєго́ духо́внаго, оправда́й єго́ своє́ю пра́ведностію, покри́й Твої́м милосе́рдієм, ісціли́ єго́ от болі́зней.","Го́споди, Ти соєдини́л нас на землі́, не разлучи́ нас і в Небе́сном Твоє́м Ца́рствії і святи́ми єго́ моли́твами прости́ вся моя́ согріше́нія, прости́ і всіх єго́ духо́вних чад, я́ко Благ і Человіколю́бець. Амі́нь."]},{"h":"Молитва до Господа про духовного отця","ps":["Спаси, Господи, і помилуй отця мого духовного (ім’я), даруй йому душевне спасіння й тілесне здоров’я, огородь молитвами святих ангелів, відожени всякого, хто бажає йому зла.","Го́споди, не осуди́, не істяжи́ в нем дарова́нія духо́вния, открой єму́, Го́споди, вся моя́ прегріше́нія, іспо́лни єго́ му́дростію, моли́твою і любо́вію. Ра́ди святи́х єго́ моли́тв, да́руй мої́м гріха́м проще́ніє, жи́зні ісправле́ніє, в доброді́телях преуспі́яніє; ниспосли́ єму́ ми́лості Твоя́ бога́тия.","Удостой його, Господи, у день цей (ніч цю) без гріха зберегтися, переможи його ворогів тілесних і безтілесних, і від видимих і невидимих ворогів визволи його, вирви його від людини лестивої й від мужа неправедного, збережи паству його до кончини його віддиху, щоб ми в покаянні прийшли до тихого й безтурботного життя.","Го́споди, пом'яни́, посіти́, укріпи́ і сохрани́ єго́ на мно́гіє лі́та."]},{"h":"Молитва до Пресвятої Богородиці про духовного отця","ps":["О, Пресвята Владичице моя, Діво Богородице, Цариця Неба й землі, вислухай волання душі моєї і прийми грішне благання моє, Пречиста Мати Божа, за отця мого духовного, скорботного раба Твого (ім’я).","Будь йому завжди супутницею і в кожен час супроводжуй та огороджуй його святими Ангелами. Зміцнюй його, коли він пильнує, оберігай його, коли спить, втішай його, коли плаче, підбадьорюй його, коли він занепадає духом, визволяй від скорбот, звільняй від наклепу, підіймай немічного, перемагай воюючих проти нього бісів і в смертній небезпеці допомагай йому. Щодня являй його страшним для видимих і невидимих ворогів, щоб вони знали, що він раб Твій, Богородице, що народила Бога і Царя, Якому належить честь і поклоніння на віки віків.","Мати Божа, пом’якши серця злих людей, що повстають на нього. Ти бачиш труди й скорботи отця мого, його скорботи Тобі єдиній відомі. Ти знаєш усі таємниці душі його, поглянь милостиво на нього з неба, полегши його страждання, покрий його покровом Своїм, відвідай його Своєю небесною милістю, пошли благословення на справи його і дай йому невидиму допомогу. І святими його молитвами дай мені смирення, самозвинувачення, терпіння, лагідність, цноту, мовчання і покрий мене від усіх напастей і ворогів видимих і невидимих. Амінь."]},{"h":"Молитва преподобного Симеона Нового Богослова про віднайдення духовного наставника","ps":["Го́споди, не хотя́й сме́рти грі́шника, но є́же обрати́тися і жи́ву би́ти єму́, соше́дий на сіє́ на зе́млю, да лежа́щия і умерщвле́нния гріхо́м воздви́гнеши і ви́діти Тебе́, світ і́стинний, я́коже челові́ку возмо́жно ви́діти, сподо́биши їх, посли́ мі челові́ка, ві́дущаго Тебі́, да, я́коже Тебі́, порабо́тав єму́ і все́ю си́лою моє́ю подчини́вся єму́, і Твою́ в того́ во́лі сотво́р во́лю, благоугожду́ Тебі́, єди́ному Бо́гу і сподо́блюся і аз, грі́шний, ца́рствія Твоєго́."]}],"notes":[]},{"u":"Молитва водія","e":"Prayer of a Driver","secs":[{"ps":["Бо́же, Всеблаги́й і Всеми́лостивий, всіх охраня́яй Своє́ю ми́лостію і человіколю́бієм, смире́нно молю́ Тя, предста́тельством Богоро́диці і всіх святи́х, сохрани́ от внеза́пной сме́рти і вся́кой напа́сти мене́, грі́шнаго, і вві́ренних мні челові́к і помози́ невреди́мих доставлять каждого по єго́ потре́бі.","Бо́же Ми́лостивий! Ізба́ви мене́ от зла́го ду́ха лихачества, нечистой си́ли піянства, визивающих несчастія і внеза́пную смерть без покая́нія.","Сподо́би мене́, Го́споди, с чи́стой со́вістію дожить до глубо́кой ста́рости без бремені убитих і іскалеченних по моєму́ нераді́нію люде́й, і да просла́виться і́м'я Твоє́ Свято́є, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитви матері за занапащені в утробі її душі (після абортів)","e":"Prayers of a Mother for the Souls Destroyed in Her Womb (after Abortion)","secs":[{"h":"Молитва 1","ps":["Го́споди, поми́луй м'я за убитих во чре́ві діте́й мої́х."]},{"h":"Молитва 2","ps":["Господи, помилуй дітей моїх, що померли в утробі моїй, за віру і сльози мої, заради милосердя Твого, Господи, не позбав їх Світла Твого Божественного."]},{"h":"Молитва 3","ps":["Спом’яни, Чоловіколюбче Господи, душі відійшлих рабів Твоїх немовлят, які в утробі православних матерів померли несподівано від невідомих причин, або від важких пологів, або через якусь необережність, або свідомо занапащені й тому не прийняли Святого Хрещення. Охрести їх, Господи, у морі щедрот Твоїх і спаси невимовною Твоєю благодаттю, а мене, грішну (ім’я), що вчинила вбивство немовляти в утробі моїй, прости і не позбав Твого милосердя. Амінь."]},{"h":"Молитва 4","ps":["О, Влади́ко, Го́споди Ісу́се Христе́, Си́не Бо́жий! Премно́гия бла́гости Твоєя́, нас ра́ди челові́к і на́шего ра́ди спасе́нія в плоть оболки́йся, і распни́йся, і погреби́йся, і Твоє́ю Кро́вію обнови́вий растлі́вшеє єстество́ на́ше, прийми́ моє́ покая́ніє во грехах і усли́ши глаго́ли моя́: согріши́ла, Го́споди, на Не́бо і пред Тобо́ю, сло́вом, ді́лом, душе́ю і ті́лом, і ми́слію ума́ моєго́. За́повіді Твоя́ преступи́ла, не послу́шала повелі́нія Твоєго́, прогневала бла́гость Твою́, Бо́же мой, но я́ко творе́ніє Твоє́ єсть, не отчаява́юся во спасе́нії, но к безмі́рному Твоєму́ Благоутро́бію дерза́я прихожду́ і молю́ся Тебі́: Го́споди! В покая́нії даждь мі сокруше́нноє се́рдце і прийми́ м'я, моля́щуюся і даждь мі мисль благу́ю, даждь мі сле́зи умиле́нія, Го́споди, даждь мі по благода́ті Твоє́й положи́ти нача́ло благо́є. Поми́луй м'я, Бо́же, поми́луй м'я па́дшую, і пом'яни́ м'я, грі́шную рабу́ Твою́ во Ца́рствії Твоє́м, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва 5","ps":["О, Бо́же, Премилосерднейший Христе́ Ісу́се, Іскупи́телю грі́шних, ра́ди спасе́нія ро́да челові́чеськаго Ти оста́вил єси́, Всеми́лостиве, пресла́вная Небеса́ і всели́лся єси́ во юдо́ль плаче́вную і многогрі́шную, Ти прия́л єси́ на Боже́ственная ра́мена Твоя́ на́ша не́мощі, і поне́сл єси́ на́ша болі́зні; Ти, о Страда́льче Святи́й, уя́звлен бил за гріхи́ на́ша і му́чим за беззако́нія на́ша, а посему́ і ми к Тебі́, Человіколю́бче, возноси́м на́ші смире́нния мольби́: прийми́ їх, о Преблаги́й Го́споди, і снизойди́ к немощам на́шим і гріхо́в на́ших не пом'яни́, і пра́ведний гнів Твой за беззако́нія на́ша на ни дви́жимий отврати́ от нас. Кро́вію Твоє́ю Всечестно́ю обнови́вий па́дшеє єстество́ на́ше, обнови́, Го́споди Ісу́се Христе́, Спаси́телю наш, і нас, во тлі гріхо́в су́щих, і уті́ши се́рдця на́ша ра́достію всепроще́нія Твоєго́. С во́плем і безмі́рними слеза́ми раска́янія припа́даєм к стопа́м Твоєго́ Божественного милосе́рдія, і мо́лим Тя: благода́тію Твоє́ю очи́сти нас от всіх непра́вд і беззако́ній житія́ на́шего. Да во святи́ні Твоєго́ Человіколю́бія восхва́лим Всесвято́є І́м'я Твоє́, со Отце́м і Преблаги́м і Животворя́щим Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Пресвятій Богородиці","ps":["Милосе́рдія две́рі отве́рзи нам, Благослове́нная Богоро́дице, наді́ющіїся на Тя, да не поги́бнем, но да ізба́вимся Тобо́ю от бід, Ти бо єси́ спасе́ніє ро́да христия́нськаго. Ра́дуйся, Єди́на Пречи́стая Ма́ти Єди́наго Созда́теля, Го́спода, Бо́га і Спа́са на́шего, Ісу́са Христа́! Бу́ди мі Хода́тайця в день стра́шнаго іспита́нія, єгда́ предста́ну Престо́лу Нелицемі́рнаго Судії́, я́ко да о́гненнаго преще́нія муки́ ізба́влюся моли́твами Твої́ми, Єди́на Благослове́нная. Пресвята́я Богоро́дице, спаси́ нас!"]}],"notes":[]},{"u":"Молитва від куріння","e":"Prayer against Smoking","secs":[{"h":"Молитва від пристрасті до куріння преподобному Амвросію Оптинському","ps":["Преподобний отче Амвросію, ти, маючи сміливість перед Господом, випроси в Великодарного Владики швидку допомогу мені в боротьбі з нечистою пристрастю. Господи! Молитвами угодника Твого, Преподобного Амвросія, очисти мої вуста, зроби цнотливим серце й насить його пахощами Духа Твого Святого, щоб відбігла від мене далеко зла тютюнова пристрасть, туди, звідки прийшла, у черево пекельне."]},{"h":"Порада преподобного Амвросія Оптинського","ps":["«Пишеш, що не можеш кинути курити тютюн. Неможливе для людей можливе за допомогою Божою; потрібно лише твердо вирішити кинути, усвідомлюючи шкоду від нього для душі й тіла, бо тютюн розслабляє душу, множить і посилює пристрасті, затьмарює розум і руйнує тілесне здоров’я повільною смертю. Дратівливість і туга — це наслідки хворобливості душі від куріння тютюну.","Раджу тобі вжити проти цієї пристрасті духовне лікування: докладно висповідайся у всіх гріхах, з семи років і за все життя, і причастися Святих Тайн, і читай щодня стоячи Євангеліє по главі або більше; а коли нападе туга, тоді читай знову, поки не мине туга; знову нападе — і знову читай Євангеліє. Або замість цього клади на самоті по 33 великі поклони — у пам’ять земного життя Спасителя і на честь Святої Тройці.»"]}],"notes":[]},{"u":"Молитви про визволення від пияцтва","e":"Prayers for Deliverance from Drunkenness","secs":[{"h":"Молитва святого праведного Івана Кронштадтського","ps":["Господи, поглянь милостиво на раба Твого (ім’я), спокушеного лестощами черева й тілесної втіхи. Даруй йому пізнати солодощі стриманості в пості та плодів Духа, що з неї випливають. Амінь."]},{"h":"Молитва до Господа нашого Ісуса Христа про дарування тверезості","ps":["Ісусе Найсолодший! Пияцтво здолало мене! Душа моя змарніла, виснажилась уся від нещасної слабкості моєї! Не впораюсь я із собою — ось невтішна скорбота й біда моя. Страх і жах нападають на мене — як би не померти від пияцтва без покаяння! Боюся, що ворог — диявол — геть погубить мене й доведе до пекла. Знаю, що своїми силами мені не впоратися із собою. «Я ж убогий і нужденний, але Господь піклується про мене. Ти поміч моя й визволитель мій, Боже мій! Не забарися» (Пс. 39:18). Господи, Ісусе Христе! Ти Сам сказав: «Без Мене не можете робити нічого» (Ін. 15:5), але «просіть, і дасться вам, шукайте, і знайдете, стукайте, і відчинять вам» (Мф. 7:7).","Ти, Господи Ісусе Христе, розслаблених зціляв, прокажених очищав, блудницю помилував, розбійникові сказав: «Нині ж будеш зі Мною в раю» (Лк. 23:43). Торкнися ж, Милосердний, і мого розслабленого та блудного серця Своєю всесильною благодаттю, влий у нього силу й бадьорість духу на боротьбу з пристрастю пияцтва, прожени диявола-спокусника і пошли мені Ангела Твого Хоронителя, і «якими знаєш путями» спаси мене, грішного й зневіреного, Господи! Ти Сам сказав: «Не хочу смерті грішника, але щоб грішник навернувся від путі своєї й жив» (Єз. 33:11) і тому «прийшов у світ спасти грішників» (1 Тим. 1:15). Ти Сам Своїми Божественними устами промовив: «Того, хто приходить до Мене, не вижену геть» (Ін. 6:37). І ось я прийшов до Тебе, надіє моя і прибіжище! Плачу біля Пречистих ніг Твоїх, Розп’ятий за мене. «Не відверни від мене лиця Твого, не відкинь мене і не залиш мене, Боже, Спасителю мій!» (Пс. 26:9), даруй мені силу й міцність волі, щоб я вигнав геть пристрасть, що гніздиться в мені, і щоб прожив у тверезості, благочесті й твердій вірі в Тебе, Єдиного Істинного Бога, Отця, і Сина, і Святого Духа. Амінь."]},{"h":"Святому мученику Боніфацію","ps":["О многостраждальний і всехвальний мучениче Боніфацію! До твого заступництва нині вдаємося. Молінь наших не відкинь, але милостиво почуй нас. Зціли братів і сестер наших (імена), тяжкою недугою пияцтва охоплених і через те від матері своєї Церкви Христової та вічного спасіння відпадаючих. О, святий мучениче Христів, торкнися їхніх сердець даною тобі від Бога благодаттю, скоро підніми з гріховних падінь і до спасительної стриманості приведи їх. Випроси в Господа Бога, Якого ради ти й страждав, щоб, простивши нам прогрішення наші, не відвернув милості Своєї від людей Своїх, але зміцнив нас у тверезості й цноті, щоб допоміг Своєю десницею тим, хто тверезіє, спасительну обітницю свою до кінця зберегти, щоб вдень і вночі про Нього пильнуючи, добру відповідь про Нього дати на Страшному суді. Прийми, угоднику Божий, молитви матерів, що проливають сльози про дітей своїх; жінок чесних, що ридають про чоловіків; дітей сиріт і убогих, пияками полишених; усіх нас, що припадаємо до ікони твоєї, щоб це волання молитвами твоїми дійшло до Престолу Всевишнього. Покрий і збережи нас від лукавого ловління і всіх підступів ворожих. У страшну годину відходу нашого допоможи пройти без перешкод повітряні митарства, молитвами твоїми визволи нас від вічного осуду, і нехай покриє нас милість Божа на безконечні віки віків. Амінь."]},{"h":"Святителю Боніфацію Милостивому","ps":["О всесвятий Боніфацію, милостивий рабе Милосердного Владики! Почуй тих, що вдаються до тебе, охоплених згубною пристрастю до винопиття, і як у своєму земному житті ти ніколи не відмовляв у допомозі тим, хто просив тебе, так і тепер визволи цих нещасних (імена). Амінь."]},{"h":"Преподобному Мойсею Мурину","ps":["О преподобний, ти від тяжких гріхів досяг чудових чеснот, допоможи рабам Божим (імена), які моляться тобі, але їх тягне в погибель те, що вони віддаються надмірному, шкідливому для душі й тіла вживанню вина. Схили на них свій милостивий погляд, не відхили й не знехтуй їх, але вислухай їх, що вдаються до тебе. Молися, святий Мойсею, до Владики Христа, щоб не відкинув їх Він, Милосердний, і щоб диявол не зрадів їхній погибелі, але щоб пощадив Господь цих безсилих і нещасних, якими заволоділа згубна пристрасть пияцтва, адже ми всі — створіння Боже й викуплені Пречистою Кров’ю Сина Його. Почуй же, преподобний Мойсею, їхню молитву, відожени від них диявола, випроси їм силу перемогти пристрасть, допоможи їм, простягни свою руку, виведи їх на шлях добра, звільни їх від рабства пристрастей і визволи їх від винопиття, щоб вони, оновлені, у тверезості й світлому розумі полюбили стриманість і благочестя та вічно прославляли Всеблагого Бога, що завжди спасає Свої створіння. Амінь."]},{"h":"Молитва перед іконою Матері Божої «Неупиваєма Чаша»","ps":["О, премилосердна Владичице! До Твого заступництва нині вдаємося, молінь наших не знехтуй, але милостиво почуй нас — жінок, дітей, матерів і тих, що тяжкою недугою пияцтва охоплені і через те від матері своєї — Церкви Христової та спасіння відпадають, братів і сестер та родичів наших зціли. О, милостива Мати Божа, торкнися їхніх сердець і скоро підніми з гріховних падінь, до спасительної стриманості приведи їх. Випроси в Сина Свого, Христа Бога нашого, щоб простив нам прогрішення наші й не відвернув милості Своєї від людей Своїх, але зміцнив нас у тверезості й цноті. Прийми, Пресвята Богородице, молитви матерів, що проливають сльози про дітей своїх; жінок, що ридають про чоловіків своїх; дітей, сиріт і убогих, заблудлими полишених, і всіх нас, що припадаємо до ікони Твоєї. І нехай це волання наше, молитвами Твоїми, дійде до престолу Всевишнього. Покрий і збережи нас від лукавого ловління і всіх підступів ворожих, а в страшну годину відходу нашого допоможи пройти без перешкод повітряні митарства, молитвами Твоїми визволи нас від вічного осуду, нехай покриє нас милість Божа на безконечні віки віків. Амінь."]}],"notes":[]},{"u":"Молитви перед сповіддю","e":"Prayers before Confession","secs":[{"h":"Молитва перша перед сповіддю","ps":["Господи, допоможи мені щиросердно покаятися."]},{"h":"Молитва друга перед сповіддю (преподобного Симеона Нового Богослова)","ps":["Бо́же і Го́споди всіх! Вся́каго диха́нія і душі́ іми́й власть, Єди́н ісціли́ти м'я моги́й, усли́ши моле́ніє м'я, окая́ннаго, і гніздя́щагося во мні змі́я на́йтієм Всесвята́го і Животворя́щаго Ду́ха умертви́в потреби́: і мене́ ни́ща і на́га вся́кия доброді́телі су́ща, к нога́м свята́го моєго́ отця́ (духо́внаго) со слеза́ми припа́сти сподо́би, і святу́ю єго́ ду́шу к милосе́рдію, є́же ми́ловати м'я, привлеци́. І даждь, Го́споди, в се́рдці моє́м смире́ніє і по́мисли бла́гі, подобающия грі́шнику, согласившемуся Тебі́ ка́ятися, і да не вконе́ць оста́виши ду́шу єди́ну, сочетавшуюся Тебі́ і ісповедавшую Тя, і вмі́сто всего́ ми́ра ізбравшую і предпочетшую Тя: ві́си бо, Го́споди, я́ко хощу́ спасти́ся, а́ще і лука́вий мой оби́чай преп'я́тствієм бива́єть: но возмо́жна Тебі́, Влади́ко, суть вся, єли́ка невозмо́жно суть от челові́ка. Амі́нь."]}],"notes":[]},{"u":"Молитва про прощення забутих гріхів","e":"Prayer for the Forgiveness of Forgotten Sins","secs":[{"ps":["Влади́ко Го́споди, поско́льку і заби́ть свої́ прегріше́нія єсть гріх, то я во всем согріши́л Тебі́, Єди́ному Сердцеве́ду; Ти і прости́ мні все по Твоєму́ человіколю́бію; те́мто і проявля́ється великолі́піє сла́ви Твоє́й, когда́ Ти не воздає́ш гре́шникам по діла́м їх, і́бо Ти препросла́влен во ві́ки. Амі́нь."]}],"notes":[]},{"u":"Молитва після сповіді гріхів","e":"Prayer after the Confession of Sins","secs":[{"ps":["Як слабкий і зовсім безсилий сам по собі до добрих діл, смиренно зі сльозами благаю Тебе, Господи, Спасителю мій, допоможи мені утвердитися в моєму наміренні: жити решту часу життя для Тебе, улюбленого Бога мого, богоугодно, а минулі прогрішення мої прости милосердям Своїм і розв’яжи від усіх моїх, сказаних перед Тобою, гріхів, як благий Чоловіколюбець. Так само смиренно благаю Тебе, Пресвята Богородице, і вас, небесні сили й усі угодники Божі, допоможіть мені виправити моє життя."]}],"notes":[]},{"u":"Молитви під час вагітності","e":"Prayers during Pregnancy","secs":[{"h":"Молитовні зідхання християнської дружини під час вагітності до Господа Ісуса Христа. Молитва перша.","ps":["Всемогутній, чудотворний, милостивий Боже! Створителю й Охоронцю неба й землі та всіх створінь, Ти Сам проголосив над усіма християнськими подружжями благословення: плодіться і множтеся! І ще: ось спадок від Господа: діти, плід утроби, нагорода від Нього. Дякую Тобі, що Ти вчинив мене учасницею цього благословення і дару Твого в подружньому стані моєму, і благаю Тебе, благоволи благословити даний мені Тобою плід утроби, обдаруй його благодаттю й облагодатни Святим Духом Твоїм, прийми його в число улюблених дітей Твоїх і вчини учасником святих таїнств церкви улюбленого Сина Твого, Господа мого Ісуса Христа, щоб він через те освятився й очистився від отруйної зарази спадкового гріха, в якому він зачатий. Господи Боже! Я й плід утроби моєї — діти гніву за природою, але Ти, улюблений Отче, змилосердься над нами і окропи плід утроби моєї гісопом, і буде чистий, обмий його — і біліший за сніг буде. Зміцни й збережи його в утробі до тієї години, коли належить йому народитися на світ. Від Тебе не був схований цей плід утроби моєї, коли він утворювався в утробі, Твої руки створили його, Ти дарував йому життя й дихання, і Твоє опікування нехай збереже їх. Збережи мене від страху й переляку і від злих духів, що хотіли б пошкодити й зруйнувати діло рук Твоїх. Даруй йому розумну душу і зроби, щоб виросло тіло його здорове й неосквернене, з цілими, здоровими членами, і коли настане час і година, звільни мене за милістю Твоєю. Даруй мені міць і силу до народження, сприяй йому Своєю всемогутньою допомогою й полегши мої страждання, бо це є Твоє діло, чудотворна сила Твоєї всемогутності, діло милості й милосердя Твого. Згадай слово, Тобою промовлене: Ти витяг мене з утроби; до Тебе прихилений я від народження; від утроби матері моєї Ти Бог мій; Ти заспокоїв мене на грудях матері моєї. Ти Бог, що знаєш і бачиш потребу всіх людей; Ти сказав: жінка, коли народжує, терпить скорботу, бо настала її година.","Господи! Заради цього серцевого співчуття Твого і заради сповненого жалості серця Твого благаю Тебе, благоволи полегшити скорботу мою, яку Ти передбачив, і виведи на світ плід утроби моєї зі здоровим, живим тілом і неушкодженими, добре сформованими членами. Тобі доручаю його в Твої всемогутні, отцівські руки, у Твою милість і милосердя, і покладаю його, Господи Ісусе Христе, у святі Твої обійми, щоб Ти благословив і цей плід утроби моєї, як благословляв Ти дітей, яких приносили до Тебе, коли говорив: «Пустіть дітей і не заважайте їм приходити до Мене, бо таких є Царство Небесне».","Спасителю! Ось приношу я до Тебе й цей плід утроби моєї; поклади на нього благодатну руку Твою. Благослови його перстом Духа Твого Святого й облагодатни його, коли він прийде в цей світ, святим, блаженним хрещенням; освяти й онови його до життя вічного через відродження, зроби, щоб він став членом святого тіла Твого і святої Твоєї християнської церкви, щоб і з його вуст звучала хвала Тобі, і він був і навіки перебував дитям і спадкоємцем життя вічного, через святі, гіркі страждання Твої і смерть Твою і святе ім’я Твоє, Ісусе Христе. Амінь."]},{"h":"Молитва друга.","ps":["Го́споди Ісу́се Христе́ Бо́же наш, от преві́чнаго Отця́ рожде́нний Си́не пре́жде вік, і в послі́днія дні, благоволе́нієм і соді́йствієм Свята́го Ду́ха, ізво́ливий рожде́ну би́ти от Пресвяти́я Ді́ви я́ко младе́нцю, повіє́ну і положе́ну во я́сли, сам Го́споди, в нача́лі сотвори́вий челові́ка і жену́ спряги́й єму́, за́повідь дав їм: расті́теся і мно́жітеся і напо́лніте зе́млю, поми́луй м'я по вели́цій ми́лості Твоє́й рабу́ Твою́ (ім’я) гото́в'ящуюся роди́ти по за́повіді Твоє́й. Прості́ мні во́льния і нево́льния гріхи́, благода́тію Твоє́ю да́руй мні си́лу благополу́чно разріши́тися от бре́мене своєго́, сохрани́ м'я і младе́нця во здра́вії і благомо́щії, огради́ я а́нгели Твої́ма і сохрани́ от неприя́зненнаго ді́йствія лука́вих духо́в, і от вся́кия ве́щі зли́я. Амі́нь."]},{"h":"Молитва третя.","ps":["Всемогутній Боже, Творче всього видимого й невидимого! До Тебе, улюбленого Отця, вдаємося ми, наділені розумом створіння, бо Ти за власною радою створив рід наш, з невимовною мудрістю створивши наше тіло із землі й вдихнувши в нього душу від Свого Духа, щоб ми були Твоєю подобою. І хоч у Твоїй волі було створити нас одразу, як і ангелів, аби тільки Ти захотів, але Твоїй Премудрості було угодно, щоб через чоловіка й жінку, у Тобою встановленому порядку шлюбу, примножувався рід людський; Ти захотів благословити людей, щоб вони росли й множилися та наповнювали не тільки землю, але й ангельські сонми. О Боже й Отче, нехай повіки славиться й прославляється ім’я Твоє за все, що Ти для нас зробив! Дякую Тобі також за Твоє милосердя, що не тільки я, за Твоєю волею від Твого дивного творіння походжу й поповнюю число обраних, але що Ти вчинив мені честь благословити мене в подружжі та зіслав мені плід утроби. Це Твій дар, Твоя Божественна милість, о Господи й Отче духа й тіла! Тому звертаюся до Тебе одного й благаю Тебе зі смиренним серцем про милість і допомогу, щоб те, що Ти твориш у мені Твоєю силою, було збережене й доведене до щасливого народження. Бо я знаю, о Боже, що не в силах і не у владі людській вибирати свій шлях; ми занадто слабкі й схильні до падіння, щоб минути всі ті тенета, які розставляє нам за Твоїм допущенням злий дух, і уникнути тих лих, у які вводить нас наша легковажність. Твоя ж мудрість безмежна. Кого Ти побажаєш, того Ти неушкодженим через Ангела Твого збережеш від усякої напасті. Тому і я, Милосердний Отче, віддаю себе у скорботі моїй у Твої руки й благаю, щоб Ти поглянув на мене оком милосердя й зберіг від усякого страждання. Пошли мені й милому чоловікові моєму розраду, о Боже, Владико всякої радості! Щоб ми, бачачи Твоє благословення, від усього серця вклонялися Тобі й служили радісним духом. Я не хочу бути виключеною з того, що Ти поклав на весь рід наш, повелівши в болях родити дітей. Але смиренно прошу Тебе, щоб Ти допоміг мені перенести страждання й послав щасливий наслідок.","Почуй, Милосердний Боже, молитву останньої рабині Твоєї, виконай благання серця нашого, заради Ісуса Христа, нашого Спасителя, Який задля нас воплотився, нині ж перебуває з Тобою й Святим Духом і владарює у вічності. Амінь."]},{"h":"Молитва жінки перед пологами до Господа Ісуса Христа","ps":["Го́споди Ісу́се Христе́ Бо́же наш, от преві́чнаго Отця́ рожде́нний Си́не пре́жде вік, і в послі́днія дні, благоволе́нієм і соді́йствієм Свята́го Ду́ха, ізво́ливий рожде́ну би́ти от Пресвяти́я Ді́ви я́ко младе́нцю, повіє́ну і положе́ну во я́сли, сам Го́споди, в нача́лі сотвори́вий челові́ка і жену́ спряги́й єму́, за́повідь дав їм: расті́теся і мно́жітеся і напо́лніте зе́млю, поми́луй по вели́цій ми́лості Твоє́й рабу́ Твою́ (ім’я) гото́в'ящуюся роди́ти по за́повіді Твоє́й. Прості́ єй во́льния і нево́льния гріхи́, благода́тію Твоє́ю да́руй єй си́лу благополу́чно разріши́тися от бре́мене своєго́, сохрани́ сію́ і младе́нця во здра́вії і благомо́щії, огради́ я а́нгели Твої́ма і сохрани́ от неприя́зненнаго ді́йствія лука́вих духо́в, і от вся́кия ве́щі зли́я. Амі́нь."]},{"h":"Молитва до Матері Божої","ps":["О, Преславна Мати Божа, помилуй мене, рабу Твою, прийди мені на допомогу під час моїх хвороб і небезпек, з якими народжують дітей усі бідні дочки Єви. Згадай, о Благословенна між жінками, з якою радістю й любов’ю Ти поспішно йшла в гірську країну відвідати родичку Твою Єлисавету під час її вагітності, і яку чудесну дію справило благодатне відвідини Твоє в матері й у немовляти. І за невичерпною добротою Твоєю даруй і мені, найприниженішій рабині Твоїй, благополучно розрішитися від тягаря; даруй мені цю благодать, щоб дитя, що спочиває тепер під моїм серцем, прийшовши до тями, з радісним підскоком, подібно до святого немовляти Івана, поклонялося Божественному Господу Спасителю, Який з любові до нас, грішних, не погордував і Сам стати немовлям. Невимовна радість, якою сповнилося дівоче Твоє серце при погляді на новонародженого Твого Сина й Господа, нехай полегшить скорботу, що чекає мене серед болів народження. Життя світу, мій Спаситель, народжений Тобою, нехай спасе мене від смерті, що обриває життя багатьох матерів у годину розрішення, і нехай зарахує плід утроби моєї до числа обраних Божих. Почуй, Пресвята Цариця Небесна, смиренне благання моє й поглянь на мене, бідну грішницю, оком Твоєї благодаті; не засоромлюй моєї надії на Твоє велике милосердя й осіни мене, Помічнице християн, Цілителько хвороб, щоб удостоїлася й я випробувати на собі, що Ти — Мати милосердя, і щоб я завжди прославляла Твою благодать, що ніколи не відкидає молитви бідних і визволяє всіх, хто призиває Тебе під час скорботи й хвороби. Амінь."]},{"h":"Молитва перед іконою Матері Божої «Феодорівська»","ps":["Ко кому́ воззову́, Влади́чице, ко кому́ прибі́гну в печа́лі моє́й; ко кому́ принесу́ сле́зи і воздиха́нія моя́, а́ще не к Тебі́, Цари́це Небесе́ і землі́: кто істо́ргнеть м'я от ти́ни гріхо́в і беззако́ній, а́ще не Ти, о Ма́ти Живота́, Засту́пнице і Прибі́жище ро́да челові́чеськаго. Усли́ши стена́ніє моє́, уті́ши м'я і поми́луй в го́ресті моє́й, защити́ в біда́х і напастях, ізба́ви от озлобле́ній і скорбе́й і вся́ких неду́гов і болі́зней, от враг ви́димих і неви́димих, умири́ вражду́ стужа́ющих мні, да ізба́влен бу́ду от клевети́ і зло́би челові́чеськія; та́кожде от своєя́ мі пло́ті гну́сних оби́чаєв свободи́ м'я. Укри́й м'я под сі́нію ми́лости Твоєя́, да обря́щу поко́й і ра́дость і от гріхо́в очище́ніє. Твоєму́ Ма́тернему заступле́нію себі́ вруча́ю; бу́ди мні Ма́ти і наде́жде, покро́в і по́мощ і заступле́ніє, ра́дость і утіше́ніє і ско́рая во всем Помо́щнице. О чу́дная Влади́чице! Всяк, притека́ющий к Тебі́, без Твоєя́ всеси́льния по́мощі не отхо́дить: сего́ ра́ди і аз недосто́йний к Тебі́ прибіга́ю, да ізба́влен бу́ду от внеза́пния і лю́тия сме́рті, скре́жета зубна́го і ві́чнаго муче́нія. Небе́сноє же Ца́рствіє получи́ти сподо́блюся і Тебі́ во умиле́нії се́рдця реку́: Ра́дуйся, Ма́ти Бо́жия, Предста́тельниця і Засту́пниця на́ша усе́рдная, во ві́ки віко́в. Амі́нь."]},{"h":"Молитовні зідхання жінки під час вагітності до Пресвятої Богородиці","ps":["О, Преславна Мати Божа, помилуй мене, рабу Твою, і прийди мені на допомогу під час моїх хвороб і небезпек, з якими народжують дітей усі бідні дочки Єви. Згадай, о Благословенна між жінками, з якою радістю й любов’ю Ти поспішно йшла в гірську країну відвідати родичку Твою Єлисавету під час її вагітності, і яку чудесну дію справило благодатне відвідини Твоє і в матері, і в немовляти. І за невичерпною добротою Твоєю даруй і мені, найприниженішій рабині Твоїй, благополучно розрішитися від тягаря; даруй мені цю благодать, щоб дитя, що спочиває тепер під моїм серцем, прийшовши до тями, з радісним підскоком, подібно до святого немовляти Івана, поклонялося Божественному Господу Спасителю, Який з любові до нас, грішних, не погордував і Сам стати немовлям. Невимовна радість, якою сповнилося дівоче Твоє серце при погляді на новонародженого Твого Сина й Господа, нехай полегшить скорботу, що чекає мене серед болів народження. Життя світу, мій Спаситель, народжений Тобою, нехай спасе мене від смерті, що обриває життя багатьох матерів у годину розрішення, і нехай зарахує плід утроби моєї до числа обраних Божих. Почуй, Пресвята Цариця Небесна, смиренне благання моє й поглянь на мене, бідну грішницю, оком Твоєї благодаті; не засоромлюй моєї надії на Твоє велике милосердя й осіни мене, Помічнице християн, Цілителько хвороб, щоб удостоїлася й я випробувати на собі, що Ти — Мати милосердя, і щоб я завжди прославляла Твою благодать, що ніколи не відкидала молитви бідних і визволяє всіх, хто призиває Тебе під час скорботи й хвороби. Амінь."]},{"h":"Молитва жінки перед пологами до Пресвятої Богородиці","ps":["Пресвята́я Ді́во, Ма́ти Го́спода на́шего Ісу́са Христа́, я́же ві́си рожде́ніє і єстество́ ма́тере і ча́да, поми́луй рабу́ Твою́ (ім’я) і помози́ в час сей да разріши́ться бре́мене своєго́ благополу́чно. О всеми́лостивая Влади́чице Богоро́дице, я́же не потре́бовала єси́ по́мощі в рожде́нії Си́на Бо́жия, пода́ждь по́мощ сей рабі́ твоє́й по́мощі тре́бующей, найпа́че же от Тебе́. Да́руй єй благомо́щіє в час сей, і младе́нця і́же і́мать роди́тися і вни́ти в світ ми́ра сего́ сподо́би в благопотре́бноє вре́м'я і у́мнаго сві́та во святі́м креще́нії водо́ю і ду́хом. Тебі́ припа́даєм, Ма́ти Бо́га ви́шняго, моля́щеся: Бу́ди ми́лостива ма́ти сей, є́йже при́йде вре́м'я би́ти ма́ти, і умоли́ воплоти́вшагося із Тебе́, Христа́ Бо́га на́шего, да укріпи́ть ю си́лою своє́ю сви́ше. Амі́нь."]}],"notes":[]},{"u":"Молитва ієросхимонаха Парфенія Київського","e":"Prayer of Hieroschemamonk Parthenius of Kyiv","secs":[{"ps":["Господи Ісусе Христе, Сину Божий, не допусти, щоб марнота, самолюбство, чуттєвість, нерадіння, гнів панували наді мною і відривали мене від любові Твоєї. О, мій Господи, Створителю мій, уся надіє моя! Не залиш мене без уділу в блаженній вічності; зроби, щоб і я наслідував святий приклад Твій, був покірний владам, наді мною поставленим; даруй мені ту чистоту духа, ту простоту серця, які роблять нас гідними любові Твоєї. До Тебе, о Боже мій, підношу душу й серце моє: не допусти загинути створінню Твоєму, але визволи мене від єдиного й найбільшого зла: гріха. Зроби, Господи, щоб я переносив з таким самим терпінням неспокої й душевні скорботи, з якою радістю приймаю втіхи серця. Якщо Ти хочеш, Господи, — можеш очистити й освятити мене. Ось, віддаю себе Твоїй благості, прошу викорінити з мене все, що противне Тобі, й приєднати до сонму обраних Твоїх. Господи! Відійми від мене лінощі духа, що марнують час; марноту думок, що заважає Твоїй присутності й розсіює увагу мою в молитві; якщо ж, молячись, я відхиляюся від Тебе моїми помислами, то допоможи мені, щоб це розсіювання було не добровільним, і, відвертаючи розум, не відвернув би від Тебе серце. Сповідую Тобі, Господу Богу моєму, усі гріхи беззаконня мого, нині й раніше вчинені перед Тобою: відпусти мені їх заради імені Твого святого і спаси душу мою, яку Ти викупив дорогоцінною Кров’ю Твоєю. Віддаю себе милосердю Твоєму, віддаюся в волю Твою, чини зі мною за благістю Твоєю, а не за злобою і беззаконням моїм. Навчи мене, Господи, розпоряджатися справами своїми так, щоб вони сприяли прославленню імені Твого святого. Змилосердься, Господи, над усіма християнами; почуй бажання всіх, що волають до Тебе, визволи від усякого зла, спаси рабів Твоїх (імена), пошли їм розраду, утіху в скорботах і милість Твою святу. Господи, молю Тебе особливо за тих, які мене чимось скривдили й засмутили або якесь зло вчинили: не карай їх заради мене, грішного, але пролий на них благість Твою. Господи, молю Тебе за всіх тих, кого я, грішний, засмутив, скривдив або спокусив словом, ділом, помислом, відомо чи несвідомо. Господи Боже! Відпусти нам гріхи наші й взаємні образи; вижени, Господи, з сердець наших усякий осуд, підозру, гнів, злопам’ятність, сварки і все те, що може заважати любові й применшувати братолюбство. Помилуй, Господи, тих, хто доручив мені, грішному, недостойному, молитися за них! Помилуй, Господи, кожного, хто просить Твоєї допомоги. Господи! Зроби цей день днем милосердя Твого, подай кожному за проханням його; будь пастирем заблудлих, провідником і світлом тих, що не знають, наставником неумудрених, отцем сиріт, помічником пригноблених, лікарем хворих, утішителем тих, що вмирають, і приведи нас усіх до бажаного кінця — до Тебе, пристані нашої і блаженного упокоєння. Амінь."]}],"notes":[]},{"u":"Молитва в день народження","e":"Prayer on One’s Birthday","secs":[{"ps":["Господи Боже, Владико всього світу видимого й невидимого. Від Твоєї святої волі залежать усі дні й літа мого життя. Дякую Тобі, премилосердний Отче, що Ти дозволив мені прожити ще один рік; знаю, що за гріхами моїми я недостойний цієї милості, але Ти виявляєш її мені за невимовним чоловіколюбством Твоїм. Продовж ще й милості Твої мені, грішному; продовж життя моє в доброчесності, спокої, у здоров’ї, у мирі з усіма родичами і в злагоді з усіма ближніми. Подай мені достаток плодів земних і все, що потрібне для задоволення моїх потреб. Найбільше ж очисти совість мою, зміцни мене на шляху спасіння, щоб я, ідучи по ньому, після багатолітнього в цьому світі життя, перейшовши в життя вічне, удостоївся стати спадкоємцем Царства Твого Небесного. Сам, Господи, благослови початий мною рік і всі дні життя мого. Амінь."]}],"notes":[]},{"u":"Молитви про невіруючих і навернення заблудлих","e":"Prayers for Unbelievers and the Conversion of the Lost","secs":[{"h":"Молитва з чину молебного співу «Про навернення заблудлих»","ps":["Всеви́шній Бо́же, Влади́ко і Соді́телю всея́ тва́рі, наполняй вся вели́чеством Твої́м і содержа́й си́лою Твоє́ю! Тебі́ вседарови́тому Го́споду на́шему ми недосто́йнії благодаре́ніє прино́сим, я́ко не отвраща́єшися нас беззако́ній на́ших ра́ди, но па́че предваря́єши Ти щедро́тами Твої́ми. Ти ко ізбавле́нію на́шему посла́л єси́ єдиноро́днаго Твоєго́ Си́на, і благовісти́л безмі́рноє Твоє́ к ро́ду челові́чеському снисхожде́ніє: я́ко хоті́нієм хо́щеши, і ожидавши, є́же обрати́тися нам к Тебі́ і спасе́нним би́ти: Ти, снизходя́ к не́мощі на́шего єстества́, укреплявши нас всеси́льною Свята́го Твоєго́ Ду́ха благода́тію, утешавши спаси́тельною ві́рою і соверше́нною наде́ждою ві́чних благ, і руково́дствуя ізбра́нних Твої́х в го́рній Сіо́н, соблюдавши я́ко зі́ницю о́ка. Іспові́дуєм, Го́споди, вели́коє Твоє́ і безприкла́дноє человіколю́біє і милосе́рдіє. Но ви́дяще мно́гих поползнове́нія, прилі́жно Тя, всеблаги́й Го́споди, мо́лим: при́зри на Це́рков Твою́, і виждь, я́ко Твоє́ спаси́тельноє благові́стіє а́ще і ра́достно прия́хом, но те́рніє суєти́ і страсте́й твори́ть о́ноє в ні́киїх малопло́дно, в ні́киїх же і безпло́дно, і по умноже́нію беззако́ній о́вії єресьми́, о́вії раско́лом проти́в'ящеся єва́нгельськой Твоє́й і́стині, отступа́ють от достоя́нія Твоєго́, отріва́ють Твою́ благода́ть і поверга́ють себі́ суду́ Твоєго́ Пресвята́го Сло́ва. Премилосе́рдий і Всеси́льний, не до конця́ гні́вайся Го́споди! Бу́ди ми́лостив, мо́лить Тя Твоя́ Це́рков, представля́ющи Тебі́ Нача́льника і Соверши́теля спасе́нія на́шего Ісу́са Христа́, бу́ди ми́лостив нам, укріпи́ нас в правові́рії си́лою Твоє́ю, заблуждающим же просвіти́ разу́мния о́чі сві́том Твої́м Боже́ственним, да уразумі́ють Твою́ і́стину, ум'ягчи́ їх ожесточе́ніє і отве́рзи слу́хи, да позна́ють глас Твой і обратя́ться к Тебі́ Спаси́телю на́шему. Іспра́ви, Го́споди, іни́х развраще́ніє і жизнь несогла́сную христия́нському благоче́стію: сотвори́, да всі свя́то і непоро́чно поживе́м, і та́ко спаси́тельная ві́ра укорени́ться і плодоно́сна в сердця́х на́ших пребу́деть. Не отврати́ лиця́ Твоєго́ от нас, Го́споди, возда́ждь нам ра́дость спасе́нія Твоєго́; пода́ждь, Го́споди, і па́стирем Це́ркві Твоєя́ святу́ю ре́вность, і попече́ніє їх о спасе́нії і обраще́нії заблужда́ющих ду́хом єва́нгельським раствори́: да та́ко всі руководи́ми дости́гнем, іді́же соверше́ніє ві́ри, ісполне́ніє наде́жди і і́стинная любо́в: і та́мо с ли́ки чисті́йших небе́сних сил просла́вим Тебе́ Го́спода на́шего, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва про навернення відлучених від Церкви","ps":["Спаси́ нас, Го́споди Бо́же наш, і собери́ нас от наро́дов славить свято́є і́м'я Твоє́, хвалиться Твоє́ю сла́вою. Славте Го́спода, і́бо Он благ, і́бо во вік ми́лость Єго́ (Псал. 105). Сла́ва Отцю́ і Си́ну і Свято́му Ду́ху і ни́ні і при́сно і во ві́ки віко́в. Амі́нь.","Боже, що виправляєш людські блуди, збираєш розсіяних і охороняєш зібраних, благаємо Тебе, зішли на християнський народ благодать єдності, щоб, залишивши розколи, в єдності з істинним пастирем Церкви Твоєї гідно служив Тобі. Заради Христа Господа нашого. Амінь.","Бо́же, доверши єдине́нія умо́во в і́стині і єдине́нія серде́ць в любві́. Амі́нь."]},{"h":"Про навернення заблудлого. Молитва до Матері Божої (святителя Гавриїла Новгородського)","ps":["О, Всемилостива Пані, Діво, Владичице Богородице, Цариця Небесна! Ти Різдвом Своїм спасла рід людський від вічного мучительства диявола: бо від Тебе народився Христос, Спаситель наш. Поглянь Своїм милосердям і на цього (ім’я), позбавленого милості Божої та благодаті, випроси Своєю Материнською сміливістю і Твоїми молитвами в Сина Твого, Христа Бога нашого, щоб зіслав благодать Свою згори на цього, що гине. О, Преблагословенна! Ти надія безнадійних, Ти спасіння відчайдушних, нехай не зрадіє ворог про душу його!"]}],"notes":[]},{"u":"Молитва перед виходом із дому","e":"Prayer before Leaving Home","secs":[{"h":"Молитва святителя Іоанна Золотоустого перед виходом із дому","ps":["Отриця́юся тебі́, сатана́, горди́ні твоє́й і служе́нію тебі́, і сочетаюся Тебі́, Христе́, во і́м'я Отця́ і Си́на і Свята́го Ду́ха. Амі́нь.","§(І осінити себе хресним знаменням.)"]},{"h":"Інша молитва","ps":["Огради́ м'я, Го́споди, си́лою Честна́го і Животворя́щаго Твоєго́ Креста́ і сохрани́ м'я от вся́каго зла.","Го́споди, напра́ви ко бла́гу путь мой.","Го́споди, благослови́ все мої́ вхожде́нія і ісхожде́нія.","§(І осінити себе хресним знаменням.)"]}],"notes":[]},{"u":"Молитви для вишивання ікон","e":"Prayers for Embroidering Icons","secs":[{"h":"Молитва перед початком роботи над іконою","ps":["Господи Ісусе Христе, Сину Божий, Ти, Що за природою Божества неописуваний і заради спасіння людини в останні дні від Діви Богородиці Марії невимовно воплотився й благоволив у плоті бути описуваним; Ти святий образ пречистого лика Твого на святому убрусі відбив і ним недугу князя Авгаря вилікував, душу ж його просвітив, щоб пізнав істинного Бога нашого; Ти Святим Духом вразумив божественного апостола Твого й євангелиста Луку написати образ Пречистої Матері Твоєї, що тримала Тебе, мов дитятко, на обіймах Своїх і промовила: «Благодать від Мене Народженого, Мене ради, нехай буде з цим образом». Сам, Владико, Боже всього, просвіти й вразуми душу, серце й розум рабині Твоєї (ім’я), і руки її направ, щоб безгрішно й гарно зображати життя Твоє, Пречистої Матері Твоєї та всіх Святих на славу Твою, заради прикраси й благолепності святої церкви Твоєї, і на відпущення гріхів усім, хто духовно поклоняється святим іконам і благоговійно цілує їх, і честь віддає Першообразові. Визволи ж її від усякого диявольського наваждення, коли вона успіває в заповідях Твоїх, молитвами Пречистої Матері Твоєї, святого славного апостола й євангелиста Луки та всіх Святих. Амінь."]},{"h":"Молитва перед початком вишивання (щоразу)","ps":["Царю́ Небе́сний, Уті́шителю, Душе́ і́стини, І́же везді́ сий і вся ісполня́яй, Сокро́вище благи́х і жи́зні Пода́телю, прийди́ і всели́ся в ни, і очи́сти ни от вся́ких скве́рни, і спаси́, Бла́же, душі́ на́ша.","Благослови, Господи, допоможи мені, грішному, звершити розпочату мною справу на славу Твою.","Го́споди, Ісу́се Христе́, Си́не Єдиноро́дний Безначального Твоєго́ Отця́, Ти бо рекл єси́ пречи́стими усти́ Твої́ми: я́ко без Мене́ не мо́жете твори́ти нічесо́же. Го́споди мой, ві́рою об'єм в душі́ моє́й і се́рдце Тобо́ю рече́нная, припа́даю бла́гости Твоє́й: помози́ мі, грі́шному, сіє́ ді́ло, мно́ю начина́ємоє, о Тебі́ Само́м соверши́ти, во і́м'я Отця́ і Си́на і Святого Ду́ха, моли́твами Богоро́диці і всіх Твої́х святи́х. Амі́нь."]},{"h":"Молитва після закінчення вишивання","ps":["Ми, недостойні раби Твої, Господи, сповнені вдячності за Твої великі до нас (звершені) милості, прославляючи Тебе, хвалимо, дякуємо, піснями прославляємо Твою щедрість і смиренно з любов’ю взиваємо до Тебе: слава Тобі, Благодійнику і Спасителю наш! Отримавши незаслужено, як раби недостойні, від Тебе, Владико, милості й дари, приносимо, з ревністю вдаючись до Тебе, (нашу) посильну подяку і, Тебе, як Благодійника й Творця, прославляючи, взиваємо: слава Тобі, Всемилостивий Боже!"]}],"notes":[]},{"u":"Молитва переслідуваного людьми (свт. Ігнатія Брянчанінова)","e":"Prayer of One Persecuted by Men (St Ignatius Brianchaninov)","secs":[{"ps":["Дякую Тобі, Господи і Боже мій, за все звершене наді мною! Дякую Тобі за всі скорботи й спокуси, які Ти посилав мені для очищення осквернених гріхами, для зцілення вражених гріхами моїх душі й тіла! — Помилуй і спаси ті знаряддя, які Ти вживав для мого лікування: тих людей, які завдавали мені образ. Благослови їх у цьому й майбутньому віці! Зарахуй їм у чесноти те, що вони робили для мене! Призначь їм із вічних скарбів Твоїх і щедрі нагороди. — Що ж я приносив Тобі? Які богоугодні жертви? — Я приносив одні гріхи, одні порушення Твоїх Божественнійших заповідей. Прости мене, Господи, прости винного перед Тобою і перед людьми! Прости безвідповідного! Даруй мені переконатися й щиро визнати, що я грішник! Даруй мені відкинути лукаві виправдання! Даруй мені покаяння! Даруй мені скруху серця! Даруй мені лагідність і смирення! Даруй любов до ближніх, любов непорочну, однакову до всіх, і до тих, що втішають, і до тих, що ображають мене! Даруй мені терпіння в усіх скорботах моїх! Умертви мене для світу! Відніми від мене мою гріховну волю й насади в серці моєму Твою святу волю, щоб я творив її єдину і ділами, і словами, і помислами, і почуттями моїми. — Тобі за все належить слава! Тобі єдиному належить слава! Моє єдине надбання — соромлення лиця й мовчання вуст. Постаючи перед страшним судом Твоїм у вбогій молитві моїй, не знаходжу в собі жодної гідності й стою, лише оповитий звідусіль безліччю гріхів моїх, мов густою хмарою й імлою, з єдиною втіхою в душі моїй: з надією на безмежну милість і благість Твою. Амінь."]}],"notes":[]},{"u":"Молитва про дарування розуміння","e":"Prayer for the Gift of Understanding","secs":[{"h":"Молитва перша","ps":["Господи, я людина грішна і не розумію, як належить, але Ти, Милостивий, вразуми мене, як потрібно вчинити."]},{"h":"Молитва друга, святителя Іоанна Золотоустого","ps":["Дай, Господи, нині моїй недостойності також благодать розуміння, щоб розпізнавати приємне для Тебе, а для мене корисне, і не лише розпізнавати, але й звершувати, щоб не захоплюватися й не прилипати до марного, щоб співстраждати страждущим і поблажливо ставитися до грішників."]}],"notes":[]},{"u":"Молитва собору славних і всехвальних 12 апостолів","e":"Prayer to the Synaxis of the Twelve Glorious and All-praised Apostles","secs":[{"h":"Тропар, глас 4","ps":["Апо́столов первопресто́льници / і вселе́нния учи́теліє, / Влади́ку всіх молі́те / мир вселе́нній дарова́ти / і душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 2","ps":["Ка́мень Христо́с ка́меня ві́ри прославля́єть сві́тло, / ученико́в преізря́дна, / і с Па́влом весь дванадесяточи́сленний собо́р днесь, / ї́хже па́м'ять соверша́юще ві́рно, // сих Просла́вльшаго прославля́єм."]},{"h":"Молитва","ps":["Святі́ї сла́внії і всехва́льнії Апо́столи, нача́льнійшаго Архієре́я іспові́данія на́шего, Ісу́са Христа́, ізбра́ннії ученици́ і строї́теліє та́їн Єго́: Пе́тре і Па́вле, Іа́кове і Іоа́нне, Андре́є і Матфе́є, Фили́ппе і Варфоломе́є, Фомо́ і Іа́кове, Іу́до і Си́моне, молі́те Христа́ Бо́га, да от шу́їяго ми́ра сего́ пребива́нія десна́го во ца́рствії Своє́м сподо́бит предстоя́нія, із си́на противле́нія сотвори́ть м'я си́на спасе́нія, да і аз совлекуся ве́тхаго челові́ка і облеку́ся в но́ваго, созда́ннаго по Бо́зі в пра́вді, преподо́бії і і́стині, і м'я, в пра́вду гріх ра́ди ненави́дима, возлю́бить і оби́тель во мні, недосто́йнім ра́бе Своє́м, досто́йну Себі́ сотвори́ть, да в правоті́ ві́ри путе́м тім ходя́, доіду́ ко Отцю́ небе́сному в наслі́діє ві́чнаго досто́їнства і та́мо, ю́же зді ві́рою созерца́ю, ясні́є во сла́ві узрю́ і просла́влю Святу́ю Тро́йцю в безконе́чния ві́ки. Амі́нь."]}],"notes":[]},{"u":"Молитва на сон","e":"Prayer at Bedtime","secs":[{"ps":["І даждь нам, Влади́ко, на сон гряду́щим, поко́й ті́ла і душі́, і сохрани́ нас от мра́чнаго сна гріхо́внаго, і вся́каго те́мнаго і нощна́го сладостра́стія. Утиши́ стремле́ніє страсте́й, і угаси́ разжже́нния стрі́ли лука́ваго, я́же на ни льстиво дви́жимия. Пло́ті на́шея воста́нія утоли́, і вся́ко земно́є і веще́ственноє на́ше мудрова́ніє успи́. І да́руй нам, Бо́же, бодр ум, цілому́др по́мисл, се́рдце трезвя́щеєся, сон лего́к, і вся́каго сатанина́ мечта́нія ізміне́н. Возста́ви же нас во вре́м'я моли́тви, утвержде́ни в за́повідіх Твої́х, і па́м'ять суде́б Твої́х в себі́ тве́рду іму́ща. Всенощноє славосло́віє нам да́руй, во є́же пі́ти і благослови́ти і сла́вити пречестно́є і великолі́пноє і́м'я Твоє́, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитви про ближніх св. Івана Кронштадтського","e":"Prayers for Our Neighbours by St John of Kronstadt","secs":[{"h":"Про гордого й норовливого","ps":["Господи, навчи раба Твого, що впав у диявольську гординю, лагідності й смирення і віджени від серця його мороку й тягар сатанинської пихи!"]},{"h":"Про злобливого","ps":["Го́споди, бла́га сотвори́ раба́ Твоєго́ сего́ благода́тію Твоє́й."]},{"h":"Про сріблолюбного і жадібного","ps":["Сокро́вище на́ше нетлі́нноє і бога́тство неістощи́моє: да́руй рабу́ Твоєму́ сему́, сотворенному по о́бразу і подо́бію Твоєму́, познать лесть бога́тства, і я́ко вся земна́я — суєта́, сінь і со́ніє. Я́ко трава́ дні вся́каго челові́ка, іли́ я́ко паучи́на, і я́ко Ти єси́ єди́н бога́тство, поко́й і ра́дость на́ша."]},{"h":"Про заздрісного","ps":["Го́споди, просвіти́ ум і се́рдце раба́ Твоєго́ сего́ к позна́нію вели́ких, безчи́сленних неізследимих даро́в Твої́х, ї́хже прия́т от неісче́тних щедро́т Твої́х, в осліпле́нії бо стра́сті своєя́ заби́ Тя і да́ри Твої́ богатиє, і ни́ща себ'я́ би́ти вміни́, бога́т сий благами Твої́ми, і сего́ ра́ди зрить преле́стні на блага́я рабо́в Твої́х, ї́миже, о, пренеізглаголанная Благости́ня, ущедря́єши всіх, коєго́ждо проти́ву си́ли єго́ і по намі́ренію во́лі Твоєя́. Отими́, всеблаги́й Влади́ко, покрива́ло дия́вола от о́чію се́рдця раба́ Твоєго́ і да́руй єму́ серде́чноє сокруше́ніє і сле́зи покая́нія і благодаре́нія, да не возра́дується враг о нем, заживо уловленном от него́ в свою́ во́лю, і да не отто́ргнеть єго́ от руки́ Твоєя́."]},{"h":"Про п’яницю","ps":["Го́споди, при́зри ми́лостивно на раба́ Твоєго́, прельще́ннаго ле́стію чре́ва і плотська́го весе́лія, да́руй єму́ познать сла́дость воздержа́нія і поста́ і проістека́ющих от него́ плодо́в Ду́ха."]},{"h":"Про ненажеру","ps":["Го́споди, сладча́йшеє Бра́шно на́ше, нікогда́же ги́блющеє, но пребива́ющеє в живо́т ві́чний: очи́сти раба́ Твоєго́ от скве́рни чревооб'яденія, всего́ плоть сотворившегося і чужда́го Ду́ху Твоєму́, і да́руй єму́ познать сла́дость Твоєго́ животворя́щаго духо́внаго бра́шна, є́же єсть плоть і кров Твоя́ і свято́є, живо́є і действенноє сло́во Твоє́."]}],"notes":[]},{"u":"Молитва того, хто подає милостиню","e":"Prayer of One Giving Alms","secs":[{"ps":["§Св. прав. Івана Кронштадтського","Господи! Навчи мене подавати милостиню охоче, з ласкою, з радістю, і вірити, що, подаючи її, я не втрачаю, а набуваю безконечно більше, ніж подаю. Відверни очі мої від людей із жорстоким серцем, які не співчувають бідним, байдуже зустрічаються з убогістю, осуджують, докоряють, таврують її ганебними іменами й розслабляють моє серце, щоб не чинити добра, щоб і мене ожорстокити проти убогості. О, Господи мій! Як багато зустрічається таких людей! Господи, виправ діло милостині! Господи, нехай кожна милостиня моя йде на користь, а не на шкоду!"]}],"notes":[]},{"u":"Молитва, що читається при запалюванні лампади","e":"Prayer at the Lighting of an Icon Lamp","secs":[{"ps":["Возжги́, Го́споди, уга́сший світи́льник душі́ моєя́ сві́том доброді́телі і просвіти́ м'я, Твоє́ созда́ніє, Тво́рче і Благоді́телю, Ти бо єси́ невеще́ственний Світ ми́ра, прийми́ сіє́ веще́ственноє приноше́ніє: світ і огонь, і возда́ждь мі вну́тренній світ уму́ і огонь се́рдцю. Амі́нь."]}],"notes":[]},{"u":"Молитва в скорботі або недузі святителя Димитрія Ростовського","e":"Prayer in Sorrow or Illness by St Dimitry of Rostov","secs":[{"ps":["Спаси́ м'я, Спа́се мой, по Твоє́й бла́гості, а не по мої́м ді́лом! Ти хо́щеши м'я спасти́, Ти ві́си, ко́їм о́бразом м'я спасти́: спаси́ у́бо мене́, я́ко хо́щеши, я́ко мо́жеши, я́ко ві́си: і́миже ві́си судьба́ми спаси́ м'я! Аз на Тя, Го́спода моєго́, наді́юся, і Твоє́й во́лі Свято́й себі́ вруча́ю: твори́ со мно́ю є́же хо́щеши! А́ще хо́щеши м'я імі́ти во сві́ті: бу́ди благослове́н. А́ще м'я хо́щеши імі́ти во тьмі: бу́ди па́ки благослове́н. А́ще отве́рзеши мі две́рі милосе́рдія Твоєго́: добро́ у́бо і бла́го, А́ще затвори́ши мі две́рі милосе́рдія Твоєго́: благослове́н єси́, затвори́вий мі в пра́вду. А́ще не погуби́ши м'я со беззако́ніями мої́ми, сла́ва безмі́рному милосе́рдію Твоєму́. А́ще погуби́ши м'я со беззако́ніями мої́ми, сла́ва пра́ведному суду́ Твоєму́: я́коже хо́щеши, устро́й о мні вещ!"]}],"notes":[]},{"u":"Молитви про дарування терпіння","e":"Prayers for the Gift of Patience","secs":[{"h":"Молитва 1, до Господа","ps":["Хвала Тобі, Отче милосердя й Боже всякої втіхи, що Ти ніколи не залишаєш страждальців Твоїх без відвідин і втіхи. Карати — караєш Ти їх, але смерті не віддаєш їх; хоч Ти часто бував для них Богом прихованим, але Ти — їх усіх Спаситель. Цю втіху вкарбуй, о Господи, в серці моєму й яви її істинною наді мною, коли лихо близько, а помічника немає. Будь світлом моїм, коли я сиджу в темряві; зроби, щоб пізнання гріхів моїх і того, чого вони заслуговують, породжувало в мені істинне смирення й терпіння. Зміцни, коли настане біда, віру в мені, як в Якова, щоб я боровся й не відпускав Тебе, доки Ти не поблагословиш мене. Зроби, щоб я у стражданні не втікав від Тебе, о Пастирю мій, але щоб бадьорість моя збільшувалась і щоб я ставав ревнішим до молитви й хвали Твоєї. Відкрий мені розум, щоб я розумів Писання, навчився з нього путей Твоїх і в істинному мовчанні серця цілком і досконало віддавався Тобі, через Ісуса Христа, Сина Твого, Господа нашого! Амінь."]},{"h":"Молитва 2, до Господа","ps":["Отче милосердя й Боже всякої втіхи! До Тебе взиваю я в ім’я Ісуса Христа про дарування мені істинного християнського терпіння. Озброй мене ним проти всякої скорботи, щоб я був у ній терплячий, бо це вельми дорогоцінно. Зроби мене готовим до взяття на себе хреста Христового, терплячого носіння його й твердого перебування під ним до кінця. Віджени від мене всяке ремствування і всяку досаду плоті на тяжкість хреста й тривалість часу його. Стань, о улюблений Ісусе, зі Своїм терпінням під хрестом і на хресті, стань перед очима моїми і серцем моїм, щоб споглядаючи Тебе я підбадьорювався й зміцнювався до постійного перенесення всього. Зроби, о терпеливий Спасителю, щоб не знемагав я духом моїм, але в терпінні увійшов через страждання й скорботу в Царство Боже. Мені потрібно мати терпіння, щоб, виконавши волю Божу, отримати обіцяне. Я прошу його в Тебе, благоволи виконати прохання моє!"]},{"h":"Молитва 3, до Пресвятої Богородиці","ps":["Утоли́ болі́зні многовоздиха́ющия душі́ моєя́, утоли́вшая вся́кую сле́зу от лиця́ землі́: Ти бо челові́ков болі́зні отгоня́єши і грі́шних ско́рби разріша́єши, Тебі́ бо всі стяжа́хом наде́жду і утвержде́ніє, Пресвята́я Ма́ти Ді́во! Всім предста́тельствуєши, Блага́я, прибегающим с ві́рою в держа́вний Твой покро́в: іна́го бо не і́мами грі́шнії к Бо́гу в біда́х і ско́рбіх при́сно ізбавле́нія, обремене́ні гріхи́ мно́гими, Ма́ти Бо́га Ви́шняго! Ті́мже Ті припа́даєм: ізба́ви от вся́каго обстоя́нія раби́ Твоя́! Нікто́же притека́яй к Тебі́ посра́млен от Тебе́ ісхо́дить, пречи́стая Богоро́дице Ді́во: но про́сить благода́ті і приє́млеть дарова́ніє к поле́зному проше́нію. Іспо́лни, Чи́стая, весе́лія се́рдце моє́, Твою́ нетлі́нную даю́щи ра́дость, весе́лія Ро́ждшая Вино́внаго! Ра́дости моє́ се́рдце іспо́лни, Ді́во, і́же ра́дости приє́мшая ісполне́ніє, гріхо́вную печа́ль потребля́ющи!"]},{"h":"Псалом 142","ps":["Го́споди, усли́ши моли́тву мою́, внуши́ моле́ніє моє́ во і́стині Твоє́й, усли́ши м'я в пра́вді Твоє́й і не вни́ди в суд с рабо́м Твої́м, я́ко не оправди́ться пред Тобо́ю всяк живи́й. Я́ко погна́ враг ду́шу мою́, смири́л єсть в зе́млю живо́т мой, посади́л м'я єсть в те́мних, я́ко ме́ртвия ві́ка. І уни́ во мні дух мой, во мні см'яте́ся се́рдце моє́. Пом'яну́х дні дре́внія, поучи́хся во всіх ді́ліх Твої́х, в творе́ніїх ру́ку Твоє́ю поуча́хся. Возді́х к Тебі́ ру́ці мої́, душа́ моя́, я́ко земля́ безво́дная Тебі́. Ско́ро усли́ши м'я, Го́споди, ісчезе́ дух мой; не отврати́ лиця́ Твоєго́ от мене́, і уподо́блюся низходящим в ров. Сли́шану сотвори́ мні зау́тра ми́лость Твою́, я́ко на Тя упова́х. Скажи́ мні, Го́споди, путь во́ньже пойду́, я́ко к Тебі́ взях ду́шу мою́. Ізми́ м'я от враг мої́х, Го́споди, к Тебі́ прибіго́х. Научи́ м'я твори́ти во́лю Твою́, я́ко Ти єси́ Бог мой. Дух Твой Благи́й наста́вить м'я на зе́млю пра́ву. І́мене Твоєго́ ра́ди, Го́споди, живи́ши м'я, пра́вдою Твоє́ю ізведе́ши от печа́лі ду́шу мою́. І ми́лостію Твоє́ю потреби́ши враги́ моя́ і погуби́ши вся стужа́ющия душі́ моє́й, я́ко аз раб Твой єсьм."]}],"notes":[]},{"u":"Молитва Оптинських старців про дарування молитви Ісусової","e":"Prayer of the Optina Elders for the Gift of the Jesus Prayer","secs":[{"ps":["Го́споди Ісу́се Христе́, Си́не Бо́жий! І́мені Твоєму́ покланя́ються а́нгели і челові́ци, Твоєго́ і́мені трепе́щуть а́дськия си́ли, Твоє́ і́м'я ві́рноє ору́жіє на прогна́ніє супоста́та, Твоє́ і́м'я попаля́єть гріхи́ і стра́сті, Твоє́ і́м'я подає́ть си́лу в по́двигах, собира́єть воєди́но разсі́янний ум і, во ісполне́нії за́повідей Твої́х, обогаща́єть доброді́телями, Твоє́ і́м'я твори́ть чудеса́ і соєдиня́єть нас с Тобо́ю, да́руєть мир і ра́дость о Ду́хі Свято́м, а в жи́зні бу́дущей — Ца́рство Небе́сноє.","Сего́ ра́ди я, недосто́йний раб Твой, молю́ся Тебі́: прожени́ от нас неві́дініє духо́вноє, просвіти́ позна́нієм Боже́ственной і́стини і научи́ нас незаблу́дно, во смире́нії, внима́тельно, с чу́вством покая́ннаго сокруше́нія, уста́ми, умо́м і се́рдцем твори́ти непреста́нно моли́тву сію́: «Го́споди Ісу́се Христе́, Си́не Бо́жий, поми́луй м'я, грі́шнаго».","Ти бо рекл єси́, Го́споди, пречи́стими уста́ми Твої́ми: «А́ще что про́сите во і́м'я Моє́, Аз сотворю́». Се, моли́твами Пречи́стия Ма́тері Твоєя́, святи́теля Іоаса́фа Білогра́дськаго, святи́теля Никола́я Мирлікі́йськаго, преподо́бнаго Серафи́ма Саро́вськаго і всіх преподо́бних оте́ць на́ших о дарова́нії прошу́ моли́тви Ісу́совой, моли́тви Пресвята́го і Всемогу́щаго І́мені Твоєго́.","Усли́ши м'я, обіща́вий усли́шати всіх призива́ющих Тя во і́стині. Твоє́ бо єсть є́же ми́ловати і спаса́ти, і дарова́ти проси́моє моля́щемуся во сла́ву Твою́ со Отце́м і Святи́м Ду́хом. Амі́нь."]}],"notes":[]},{"u":"Молитва на входження в дім святителя Миколая Сербського","e":"Prayer on Entering a House by St Nikolaj of Žiča","secs":[{"ps":["Боже, благослови того, хто входить у цей дім, захисти й збережи того, хто виходить із нього, і даруй мир тому, хто в ньому перебуває."]}],"notes":[]},{"u":"Молитва перед Всенічним бдінням","e":"Prayer before the All-Night Vigil","secs":[{"ps":["Го́споди, Ісу́се Христе́, сладча́йший О́тче, Бо́же і Го́споди ми́лості і всея́ тва́рі Соді́телю, при́зри на смире́ніє моє́ і вся гріхи́ моя́ прості́, я́же во все житія́ моєго́ вре́м'я соді́ях да́же до сего́ дне і часа́, і посли́ Пресвята́го і Утешительного Твоєго́ Ду́ха, я́ко да Той м'я научи́ть, просвіти́ть, покри́єть, є́же не согріша́ти, но с чи́стою душе́ю і се́рдцем чти́ти і покланя́тися, славосло́вити, благодари́ти і возлюби́ти от всея́ душі́ і се́рдця Тебі́, сладчайшего моєго́ Спа́са і Благоді́теля Бо́га, досто́йнаго вся́кия любве́ і поклоне́нія. Єй, Благи́й О́тче Безнача́льний, Си́не Собезнача́льний і Пресвяти́й Душе́, сподо́би м'я просвіще́нія боже́ственнаго і духо́внаго ві́дінія, да созерца́я сла́дкую Твою́ благода́ть, є́ю понесу́ тяготу́ сего́ моєго́ нощна́го бді́нія і чи́стия возда́м я́же к Тебі́ моли́тви моя́ і благодаре́нія, моли́твами Пресвяти́я Богоро́диці і всіх святи́х.","Амі́нь."]}],"notes":[]},{"u":"Молитва перед початком Богослужіння","e":"Prayer before the Beginning of the Divine Service","secs":[{"ps":["Го́споди Ісу́се Христе́, ще́дрий і ми́лостивий всім і́стинно призива́ющим Тя, Тебі́ молю́ся: сподо́би м'я со тща́нієм, любо́вію, стра́хом і вся́ким внима́нієм, да́же до конця́ Боже́ственния слу́жби сея́ преби́ти, і сокруше́нним се́рдцем і чи́стою со́вістію моли́тися Тебі́, Милосе́рдному Бо́гу. Єй, Го́споди Царю́! Усли́ши м'я, начина́юща призива́ти Тя, і да́руй мі оставле́ніє всіх гріхо́в мої́х: Ти бо Єди́н благослове́н єси́, со Отце́м і со Святи́м Ду́хом, во ві́ки. Амі́нь."]}],"notes":[]},{"u":"Молитва після Божественної Літургії","e":"Prayer after the Divine Liturgy","secs":[{"ps":["Благодарю́ Тя, пренебе́сний Царю́, і всім ті́лом і душе́ю молю́, хвалю́, сла́влю, почита́ю і превозношу́ Тя, я́ко сподо́бил єси́ мене́, грі́шнаго, в день сей в Боже́ственном сем Хра́мі Боже́ственную твою́ і благоприя́тную, бескровную і слове́сную, Твої́ми священнослужительми о на́ших согріше́ніях Тебі́ принесе́нную і пожертую ви́діти же́ртву, во воспомина́ніє пречи́стих Страсте́й, преславного Воскресе́нія, на небеса́ Восше́ствія і страшного па́ки Прише́ствія Го́спода на́шего Ісу́са Христа́ ї́хже ра́ди молю́ Тя: вся моя́ согріше́нія оми́й, очи́сти і прости́, і даждь мі во вся дні живота́ моєго́ помина́ти Твоя́ благодія́нія і в чи́стой со́вісти благодаре́нія і мольби́ Тебі́ приноси́ти, безнача́льному Отцю́ со Єдиноро́дним Твої́м Сино́м і Всесвяти́м Благи́м і Животворя́щим Твої́м Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва покаянна, що читається в дні смути","e":"Penitential Prayer for Days of Turmoil","secs":[{"ps":["Го́споди, Бо́же, Вседержи́телю, при́зри на нас, грі́шних і недосто́йних чад Твої́х, согріши́вших пред Тобо́ю, прогні́вавших бла́гость Твою́, навлекших гнів Твой пра́ведний на ни, па́дших во глубину́ гріхо́вную. Ти зри́ши, Го́споди, не́мощ на́шу і скорб душе́вную, ві́си растлі́ніє умо́в і серде́ць на́ших, оскуді́ніє ві́ри, отступле́ніє от за́повідей Твої́х, умноже́ніє нестроє́ній семе́йних, раз'єдиненія і раздо́ри церко́вния, Ти зри́ши печа́лі і ско́рби на́ша, от болі́зней, гла́дов, потопле́нія, запале́нія і междоусо́бния бра́ні проісходя́щия. Но, Преми́лостивий і Человіколюби́вий Го́споди, вразуми́, наста́ви і поми́луй нас, недосто́йних. Іспра́ви жизнь на́шу гріхо́вную, утоли́ раздо́ри і нестроє́нія, собери́ расточе́нния, соєдини́ разсі́янния, пода́ждь мир страні́ на́шей і благоде́нствіє, ізба́ви ю от тя́жких бід і несча́стій. Всесвяти́й Влади́ко, просвіти́ ра́зум наш сві́том уче́нія Єва́нгельськаго, возгрі́й се́рдця на́ша теплото́ю благода́ті Твоєя́ і напра́ви я к ді́ланію за́повідей Твої́х, да просла́виться в нас всесвято́є і пресла́вноє і́м'я Твоє́, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва в день Нового року","e":"Prayer on New Year’s Day","secs":[{"ps":["Господи Боже, Творче й Зиждителю всіх видимих і невидимих створінь, що створив часи й літа, Сам благослови Новий Рік, який починається цього дня, і який ми лічимо від втілення Твого для нашого спасіння. Дозволь нам провести цей рік і багато наступних за ним у мирі й злагоді з ближніми нашими; зміцни й поширюй Святу Вселенську Церкву, яку Ти Сам заснував і спасительною жертвою святого Тіла та пречистої Крові освятив. Вітчизну нашу возвеличи, збережи й прослав; довголіття, здоров’я, достаток плодів земних і добру погоду дай нам; мене, грішного раба Твого, всіх родичів і ближніх моїх та всіх благочестивих християн, як істинний наш верховний Пастир, охорони, огородь і на шляху спасіння утверди, щоб ми, ідучи по ньому після довгого й щасливого життя в світі цьому, досягли Царства Твого Небесного й удостоїлися вічного блаженства з Твоїми святими. Амінь."]}],"notes":[]},{"u":"Молитва преподобного Феодора Студита","e":"Prayer of St Theodore the Studite","secs":[{"ps":["Рассеянний мой ум собери́, Го́споди, і олядиневшеє (поросшеє дурной травой) моє́ се́рдце очи́сти. Я́ко Петру́, да́руй мні покая́ніє, я́ко митарю́ – воздиха́ніє, я́ко блудни́ці – сле́зи, да зову́ к Тебі́: помози́ мі і от скве́рних по́мисл ізба́ви м'я! І́бо, я́ко во́лни морскиє, восстають на м'я беззако́нія мої́, і я́ко кора́бль в пучи́ні погружа́юся помишле́ніями мої́ми; но в ти́хоє приста́нище наста́ви м'я, Го́споди, покая́нієм і спаси́ м'я! Зіло́ бо скорблю́ за не́мощ ума́ моєго́, я́ко не хотя́ стражду́ воі́стину нево́льноє ізміне́ніє – колеба́ніє, обурева́ніє, крушеніє. Сего́ ра́ди вопію́ ті: Безнача́льная Тро́йце Свята́я, помози́ мні, і в стоя́нії м'я до́брих помисло́в і чувствованій учини́!"]}],"notes":[]},{"u":"Дві ранішні маловідомі молитви","e":"Two Little-Known Morning Prayers","secs":[{"h":"Молитва перша","ps":["Тебе́, Бо́гу і Творцю́ моєму́, в Тро́йці Святі́й сла́вимому Отцю́ і Си́ну і Свято́му Ду́ху, поклоня́юся і вруча́ю ду́шу і ті́ло моє́, і молю́ся: Ти м'я благослови́, Ти м'я поми́луй, і от вся́каго мирська́го, дия́вольськаго і тіле́снаго зла ізба́ви. І даждь в ми́рі без гріха́ прейти́ день сей, в сла́ву Твою́, і во спасе́ніє душі́ моєя́. Амі́нь."]},{"h":"Молитва друга","ps":["Сла́ва Тебі́, Царю́, Бо́же Вседержи́телю, І́же Боже́ственним Твої́м і человіколю́бним про́мислом, сподо́бил м'я єси́, грі́шнаго і недосто́йнаго, от сна вста́ти і получи́ти вход свята́го до́му Твоєго́: прими́, Го́споди, і глас моле́нія моєго́, я́коже святи́х і у́мних Твої́х сил, і благоволи́ се́рдцем чи́стим, і ду́хом смире́нним приноси́ти Тебі́ хвалу́ от скве́рних усте́н мої́х, я́ко да і аз о́бщник бу́ду му́дрим ді́вам, со сві́тлою свіще́ю душі́ моєя́, і сла́влю Тя во Отці́ і Ду́хі сла́вимаго Бо́га Сло́ва. Амі́нь."]}],"notes":[]},{"u":"Молитва про отрока, що погано вчиться","e":"Prayer for a Boy Who Does Poorly in His Studies","secs":[{"ps":["Го́споди Ісу́се Христе́ Бо́же наш, всели́вийся в се́рдця двунадесятих апо́столов нелицемі́рно, благода́тію Всесвята́го Ду́ха, соше́дшаго во ви́ді о́гненних язи́к, і сих устні́ отве́рзий, і нача́ша глаго́лати іни́ми язи́ки: Сам Го́споди Ісу́се Христе́ Бо́же наш, ниспосли́ Того́ Ду́ха Твоєго́ Свята́го на отроча́ сіє́ (ім’я): і насади́ во ушеса́ се́рдця єго́ Свяще́нния Писа́нія, я́же рука́ Твоя́ пречи́стая на скрижа́ліх начерта́ законополо́жнику Мойсе́ю, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва ув’язненого до Матері Божої","e":"Prayer of a Prisoner to the Mother of God","secs":[{"ps":["О, Пресвята́я Ді́во, Ма́ти Го́спода і Спаси́теля моєго́! Всі челові́ци притека́ють к Тебі́ і нікто́ притека́яй отхо́дить от Тебе́ всу́є, а́ще о до́брі про́сить. Мо́лять Тя архієре́є і свяще́нници, я́ко Ма́тер єси́ Архієре́я Вели́каго, проше́дшаго небеса́. Мо́лять Тя і́ноки і і́нокини, я́ко Сама́ єси́ Пречи́стая Ді́ва. Мо́лять Тя отці́ і ма́тері, і́же соболезнують о свої́х ді́тях, в не́мощіх лежа́щих іли́ дале́че живу́щих, я́ко Ти Сама́ болі́знующи іска́ла Си́на своєго́, єгда́ Он, дванадесятилетній о́трок, оста́ во Ієрусали́мі. Мо́лять Тя обидимії, я́ко претерпі́ла єси́ гоне́ніє от І́рода с Боже́ственним Младе́нцем. Возно́сять к Тебі́ послі́днюю свою́ моли́тву умира́ющії, я́ко Ти предстоя́ла єси́ у Креста́ умира́ющаго Си́на Твоєго́. Мо́лять Тя пра́веднії і всі хотя́щії благоче́стно жи́ти: і нікто́же от них дости́же пра́ведности, не імі́яй Тебі́ моли́твенницю. Та́ко всі і́муть Тя засту́пницю усе́рдну і всім подає́ши ско́ру по́мощ.","Єди́н ли аз, грі́шник, в темни́ці сідя́й, забве́н бу́ду от Тебе́? Мене́ ли єди́наго моли́тву не усли́шиши? Мене́ ли, прибіга́ющаго к Тебі́, не приї́меши под кров Твой? О, ніка́коже помишля́ю сему́ би́ти. Поне́же Ма́тер єси́ Спаси́теля погиба́ющих грі́шников. Поне́же я́ко ність іно́го Бо́га ра́зві Ісу́са Христа́, Си́на Твоєго́, со Отце́м і Святи́м Ду́хом во Єди́ном Божестві́ покланя́ємаго. Та́ко ність іна́го у Престо́ла Бо́жия ближайшаго хода́тая, я́коже Ти, Ма́ти Бо́жия! Ма́тернєє моле́ніє мно́го мо́жеть ко благосе́рдію Влади́ки. Пред Ним Тебі́ вся возмо́жна суть. Сего́ ра́ди на Тя по Бо́зі все упова́ніє моє́ возлага́ю. Сего́ ра́ди храню аз пречи́стий о́браз Твой во узи́лищі моє́м, пам'ятуяй близость Твою́ ко всім скорб'я́щим і заключе́нним.","Оба́че Ти, Ма́тер Бо́жия, і явля́ла єси́ дони́ні ко мні мно́гая ми́лости по мої́м проше́нієм к Тебі́! Чимже аз яви́хся пред Тобо́ю? Уви́ мні злонравному! Аз же непа́м'ятлив бих Твої́х благодія́ній. Но, о милосе́рдая Цари́це Богоро́дице, прости́ моя́ ізмі́ни і неразу́міє, не отве́ргни мене́, па́ки возвраща́ющагося к Тебі́, яви́ ко мні дре́вняя Твоя́ ми́лості і прийми́ м'я на Свої́ мощниї руки́, а́ки боля́ща, а́ки є́ле жива́ су́ща от язв гріхо́вних. Приведи́ мою́ ду́шу грі́шную к покая́нію. Беззако́нія бо моя́ превзидо́ша главу́ мою́. Коли́ко досе́лі прогні́вах аз Бо́га моєго́ лжа́ми, хищеніями, пія́нством, крамолами, жестокосе́рдієм, безсовестієм. Безпреста́ні согріша́ю і в сей темни́ці лі́ностію, мечта́ніями, обманами, непоко́рством, досажденіями соузникам мої́м і развраще́нієм їх, татьбами і роптанієм на мою́ участь. Ктому́ не бисть у мене́ дони́ні ні слез, ні умиле́нія, іли́ же аз пла́ках то́кмо от доса́ди моєя́.","Примири́ у́бо мене́, Благода́тная, с Бо́гом, Сино́м Твої́м. Сподо́би м'я получи́ти разріше́ніє во всіх грісі́х мої́х в та́йні покая́нія, і а́біє причасти́тися Свята́го Ті́ла і Кро́ве Си́на Твоєго́. Помози́ мі отнині возненави́діти зли́я мої́ стра́сті і крі́пко воїнствовати проти́ву гріха́; зане́ а́ще в чесо́м і пока́юся, по ма́лом часі́ та́яжде творю́, і си́це лжив пред Бо́гом обріта́юся. Іспроси́ мі, Влади́чице Богоро́дице, благода́ть про́чеє вре́м'я живота́ моєго́ в тве́рдом покая́нії сконча́ти. Ми́лующая грі́шники, не пре́зри мене́ пе́рваго із них. Зри́ши моя́ біди́, зри́ши мою́ го́рку жизнь в сей темни́ці. Помози́ мі претерпі́ти до конця́ позо́р мой, тісноту́ і про́чія темни́чния лише́нія, да не впаду́ в отча́яніє, да не дерзну́ возноси́ти хули́ на Про́мисл Бо́жий, но то́кмо скорблю́ і пла́чу о грісі́х мої́х, то́кмо от печа́лі моєя́ о ча́дах мої́х і сро́дниках, от ни́хже разлуче́н єсьм, обраща́юся ко утіше́нію в моли́тві. Ність у мене́ терпі́нія і ки́йждо день мню, я́ко наста́ коне́ць моєму́ терпі́нію. О, печалних недові́домоє утіше́ніє! Уті́ши моєго́ отця́ і ма́тер со сро́дники, і́же скорб'я́ть о мні, для ни́хже аз содеяхся я́ко мертв. Найпа́че же, о чадолюби́вая Ма́ти! Не лиши́ Твоєго́ покровительства жену́ і ча́да моя́, ї́хже оста́вих аз, я́ко престу́пний оте́ць, зане́ они́ непови́нни суть во грісі́х мої́х. Препита́й їх і сохрани́ Твоє́ю моли́твою здра́ви і богобоязненни. Да́руй мі, напослі́док, ви́діти свобо́ду і со слеза́ми ра́дости облобиза́ти мої́х дома́шніх. Із глубини́ душі́ моєя́ вопію́ к Тебі́, Цари́це Небе́сная, от одного́ о́браза Твоєго́ с предві́чним Младе́нцем на ру́ку Твоє́ю держи́мим чувствуяй в се́рдці моє́м отра́ду: не отри́ни мене́, бу́ди мі покрови́тельниця во вся́ких мої́х ну́ждах, во вся́ком моє́м стра́хі і уни́нії, днем і но́щію, во здра́вії і болі́зні. Облегчи́ моя́ душе́вния і тіле́сния ско́рби, я́ко Ти єси́ всіх скорб'я́щих ра́дость. Ми́лостива бу́ди мі не зді то́кмо, но і та́мо, в страні́ ві́чній. Не оста́ви мене́ без Твоєго́ заступле́нія в день Стра́шнаго Втора́го Прише́ствія Го́спода моєго́. Єй, Пресвята́я Богоро́дице! Не забу́ди тогда́ моєя́ ві́ри, я́же к Тебі́, і недосто́йних мої́х моли́тв пред Тобо́ю. Да та́ко, бив на ві́чния времена́ поми́лован Тобо́ю, в безконе́чния же ві́ки бу́ду благодари́ти Тебі́ і славосло́вити Отця́ і Си́на і Свята́го Ду́ха, амі́нь."]}],"notes":[]},{"u":"Молитва ув’язненого до Ангела Хоронителя","e":"Prayer of a Prisoner to the Guardian Angel","secs":[{"ps":["А́нгеле Бо́жий, предстоя́й мі от купі́лі свята́го креще́нія! Коли́ко аз, преогорчева́х тебі́ зли́ми по́мисли, скве́рними словеси́ і пости́дними дія́ньми в житії́ моє́м! Ктому́ же, не па́м'ятовах, я́ко і́мам тя да́ннаго мі от Бо́га храни́теля. Єгда́ аз упива́хся вино́м, іли́ безсту́дно пляса́х, іли́ в блуді́, хище́ніях і злоприобрете́ніїх іждива́х житіє́ моє́: і в сі́ї дні ти не отлуча́лся єси́ от мене́, но то́кмо, я́ко чи́стий дух, печа́лен бил єси́ о мні, непотре́бнім ра́бе. Коль мно́жицею аз бих близ са́мия сме́рті, творя́й престу́пния діла́ і отню́дь не помишля́яй предста́ти внеза́пу Бо́гу Судії́! Смерть же не пости́же мене́ тогда́: і вім, я́ко ти отврати́л єси́ ю от мене́. Та́ко ви́ну охраня́єши м'я, і не єди́н аз єсьм, внегда́ єди́н жи́тельствую во узи́лищі сем, но с тобо́ю, храни́телю мой. А́ще і не ви́жду тебі́ тіле́сними очи́ма, ти єси́ при́сно спребива́яй окая́нной моє́й душе́ і ті́лу. Я́коже со́лнце, преходя́ скве́рния мі́ста, не оскверня́ється, си́це і ти, світоно́сний А́нгеле Бо́жий, не возгнуша́йся моєя́ смра́дности, но ніколи́же отлуча́йся от мене́ і в сей темни́ці. Сохрани́ м'я здра́ва но́щію і непристу́пна во сні дия́вольському іскуше́нію. Отжени́ от мене́ безсо́ніє. Сопу́тствуй мі, во дні, на ки́йждо час, во всіх вхо́діх і ісхо́діх мої́х. Да́руй мі крі́пость тіле́сних сил, є́же понести́ го́ркия рабо́ти, в наказа́ніє мні налага́ємия, го́ркия же па́че по вині́ їх. Заступи́ м'я от зло́би бісо́в, лю́ті напа́дающих на мою́ ду́шу: і́бо от єди́наго манове́нія десни́ці твоєя́ біжа́ть бі́си. Па́че же всего́ отжени́ от мене́ см'яте́ніє душе́вноє і ро́пот вре́дний: сий бо смуще́н се́рдцем, не хощу́ ні на кого́ і ні на что благоприя́тно взира́ти і при́сно зді огорчева́юся. Да́руй оча́м мої́м сле́зи о грісі́х, усто́м же ти́хоє глаго́ланіє. Не отступи́ от мене́, святи́й А́нгеле, і єгда́ душа́ моя́ начне́ть разлуча́тися от ті́ла, но предста́ни мі у сме́ртнаго моєго́ одра́ тих і ра́достен; і́бо і́мам тогда́ ви́діти тебе́ близ су́ща. Не оста́ви і по́сліжде мою́ ду́шу, я́же ті от Бо́га предана́ бисть непоро́чні, но я́же по сме́рті моєя́ і́мать суди́тися, я́ко оскверне́нная мно́гими гріхми́. О, храни́телю мой! Призови́ тогда́ помоли́тися о мні і про́чія безпло́тния си́ли, да твої́м заступле́нієм поми́лован бу́ду, грі́шний раб (і́м'я), во ві́ки віко́в, амі́нь!"]}],"notes":[]},{"u":"Молитва в’язня, ув’язненого в темниці","e":"Prayer of a Prisoner in Confinement","secs":[{"ps":["§(Твір святителя Філарета Московського)","Го́споди Бо́же, Созда́телю і Спаси́телю мой! Благослове́нно да бу́деть і́м'я Твоє́ Свято́є. Благодаре́ніє і сла́ва Тебі́, Го́споди, о всіх благи́х, я́же прия́т от Тебе́ в житії́ сем. Ни́ні же скорб і болі́знь обріто́х, і І́м'я Твоє́ призива́ю. Поноше́нія нападо́ша на м'я. Положи́ша м'я в ро́ві преіспо́днім, в те́мних і сі́ні сме́ртній. Скорблю́ о сем; і по сей ско́рби разуміва́ю, я́ко согріши́х пред Тобо́ю, і по гріхо́м мої́м прийдо́ша на м'я біди́; і́бо пра́ведники Твої́ не унива́юще і в темни́цях поя́ху Тебі́, і во страда́ніїх ра́довахуся. І а́ще беззако́нія на́зриши, Го́споди, Го́споди, кто постої́ть? Я́ко ність челові́к, і́же не согріши́. Но Ти, Го́споди, гріхи́ всего́ ми́ра но́сиши, і покая́нієм очища́єши. Ві́рую, я́ко і мене́ грі́шнаго не отве́ржеши от лиця́ Твоєго́. За весь мир Єдиноро́дний Син Твой ізлія́ Свою́ Боже́ственную Кров. Ві́рую, я́ко і мене́ от гріхо́в мої́х оми́ти мо́жеть і хо́щеть. Сего́ ра́ди с Дави́дом глаго́лю: іспові́м на м'я беззако́ніє моє́. Ти же, я́ко Благ, оста́ви нече́стіє се́рдця моєго́. Страшу́ся суда́ і осужде́нія человечеського: но найпа́че да бу́деть мні в се́рдці страх Твой неуми́тний суд і ві́чноє осужде́ніє. А́ще непра́вда возста́неть на м'я, дерза́ю сло́вом Дави́довим моли́тися Тебі́, усли́ши, Го́споди, пра́вду мою́ і воньми́ суду́ моєму́, і пра́вдою Твоє́ю ізба́ви м'я. А́ще же непра́вду сотвори́х: милосе́рдієм Твої́м непра́вду мою́ уврачу́й. Не попусти́ уклони́тися се́рдцю моєму́ во словеса́ лука́вствія, к сокритію і́стини, і к ло́жному оправда́нію. Помози́ мні і уразумі́ти, і возненави́діти непра́вду мою́: возлюби́ти же пра́вду, і во і́стині обрісти́ облегче́ніє душі́ моє́й. Облегчи́ бре́м'я бі́дствія моєго́. А є́же понести́ мні су́ждено, да понесу́ с терпі́нієм, ра́ди очище́нія гріхо́в мої́х, і ра́ди умилостивле́нія Твоєго́ правосу́дія. А́ще і стид покри́єть мене́ пред ні́кими челові́ками: да потерплю́ со смире́нієм, да уми́лостивлю Тебі́, Го́споди, да не постижен бу́ду пред лице́м сего́ ми́ра на Стра́шном Суді́ Твоє́м.","Прихожду́ к Тебі́ ско́рбний і печа́льний: не лиши́ мене́ духовного утіше́нія.","Прихожду́ к Тебі́ омраче́нний: яви́ світ упова́нія спасе́нія.","Припа́даю к Тебі́ ізнемо́гший: возста́ви і утверди́ мене́ благода́тію Твоє́ю.","Па́че всего́ да́руй мні жела́ніє, і помози́ мні, Го́споди, твори́ти во всем Твою́ во́лю, да в ми́рі со́вісти просла́влю І́м'я Твоє́ Свято́є, Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]}],"notes":[]},{"u":"Молитва ув’язненого до святого Іоанна Предтечі","e":"Prayer of a Prisoner to St John the Forerunner","secs":[{"ps":["Предте́че і Крести́телю Христо́в Іоа́нне, пропові́дниче покая́нія! Ти неповинне всажде́н бил єси́ в темни́цю: аз же, вверженний в злоключе́ніє сіє́, досто́йноє по ді́лом мої́м приє́млю, я́ко престу́пник пра́вди і зако́на. Всели́ в моє́ се́рдце чу́вство покая́нія о грісі́х мої́х! Ність бо ні єди́ния зло́би ні беззако́нія, ї́хже аз, окая́нний, не соді́ях; престрашни гріси́ мої́. Учи́телю пра́вди! Научи́ м'я пра́во глаго́лати о мні само́м пред судія́ми. Не преставаяй і в темни́ці облича́ти беззако́ннаго І́рода, да́руй мі, да найпа́че зді облича́єть мене́ со́вість моя́, да от обличе́нії єя́ не возмогу́ на до́лзі вре́мені утаї́ти моє́ преступле́ніє. А́ще же осужде́н бу́ду понести́ наказа́ніє, да́руй мі би́ти терпеливу, я́коже ти сам терпіли́вно несл єси́ усікнове́ніє глави́ твоєя́, жела́нноє от Іродія́ди. Єй, Крести́телю Христо́в! Простри́ мі, рабу́ твоєму́, ру́ку, крестившую Христа́ Спаси́теля моєго́, да м'я ізвлече́ши із глубини́ поги́белі. Ти єси́ бо́льшій всіх в рожде́нних жена́ми, ти єси́ пе́рвий по Богоро́дице, пра́ведник между́ челові́ки. Сего́ ра́ди прибіга́ю к тебі́ аз, імі́яй потре́бу во вели́цім хода́тає, я́ко вели́к єсьм грі́шник. У́бо і да осіни́ть мене́, недосто́йнаго, благода́ть твоя́, Предте́че Госпо́день."]}],"notes":[]},{"u":"Молитва преподобного Антонія Оптинського на початок усякої справи","e":"Prayer of St Anthony of Optina at the Beginning of Any Work","secs":[{"ps":["Бо́же, в по́мощ мою́ воньми́, Го́споди, по́мощі мі потщи́ся. Упра́ви, Го́споди, все, є́же ді́ю, читаю і пишу́, все, є́же мислю, глаго́лю і разумі́ю, во сла́ву І́мене Твоєго́ Свята́го, да от Тебе́ на нача́ло приє́млеть і в Тебі́ вся́ко ді́ло моє́ кончиться. Да́руй мі, Бо́же, да ні сло́вом, ні ді́лом, ні помишле́нієм прогні́ваю Тя, Созда́теля моєго́, но вся діла́ моя́, сові́ти і помишле́нія да бу́дуть во сла́ву Пресвята́го І́мене Твоєго́. Бо́же, в по́мощ мою́ воньми́, Го́споди, по́мощі мі потщи́ся."]}],"notes":[]},{"u":"Молитва преподобного Антонія Оптинського за ворогів","e":"Prayer of St Anthony of Optina for Enemies","secs":[{"ps":["Ненави́дящих і оби́дящих нас, рабо́в Твої́х (імена), прости́, Го́споди, Человіколю́бче: не ві́дять бо, что творя́ть, і согрі́й їх се́рдце на любо́в к нам, недосто́йним."]}],"notes":[]},{"u":"Молитва преподобного Макарія Оптинського при плотській боротьбі","e":"Prayer of St Macarius of Optina in the Struggle with the Flesh","secs":[{"ps":["О, Ма́ти Го́спода моєго́ Творця́, Ти єси́ ко́рень ді́вства і неув'яда́ємий цвіт чистоти́. О, Богороди́тельнице! Ти мі помози́, немощно́му плотсько́ю стра́стію і болі́зненну су́щу, єди́но бо Твоє́ і с Тобо́ю Твоєго́ Си́на і Бо́га і́мам заступле́ніє. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобного Йосифа Оптинського при нашесті помислів","e":"Prayer of St Joseph of Optina When Thoughts Assail","secs":[{"ps":["Го́споди Ісу́се Христе́, отжени́ от мене́ вся́кия неподо́бния по́мисли! Поми́луй м'я, Го́споди, я́ко не́мощен єсьм… Ти бо єси́ Бог мой, содержа́й ум мой, да не преодолі́ють єго́ по́мисли нечи́стия, но в Тебі́, Творці́ моє́м, (он) да услажда́ється, я́ко вели́ко єсть І́м'я Твоє́ лю́б'ящим Тя."]}],"notes":[]},{"u":"Молитва преподобного Никона Оптинського, сповідника, у скорботі","e":"Prayer of St Nikon of Optina, Confessor, in Sorrow","secs":[{"ps":["Сла́ва Тебі́, Бо́же мой, за посланную мні скорб, досто́йноє по ді́лом мої́м ни́ні приє́млю. Пом'яни́ м'я, єгда́ при́йдеши во Ца́рствії Твоє́м, і да бу́деть на вся во́ля Твоя́ єди́на, блага́я і соверше́нная."]}],"notes":[]},{"u":"Молитва преподобного Анатолія Оптинського (Потапова) від антихриста","e":"Prayer of St Anatoly of Optina (Potapov) against the Antichrist","secs":[{"ps":["Ізба́ви м'я, Го́споди, от обольще́нія богоме́рзькаго злохитраго антихриста близгрядущаго, і укри́й м'я от сіте́й єго́ в сокрове́нній пусти́не спасе́нія Твоєго́. Даждь мі, Го́споди, крі́пость і му́жество тве́рдаго іспові́данія І́мені Твоєго́ Свята́го, да не отступлю стра́ха ра́ди дия́вольськаго, да не отрекуся от Тебе́, Спаси́теля і Іскупи́теля моєго́, от святи́я Твоєя́ Це́ркве. Но даждь мі, Го́споди, день і ноч плач і сле́зи о грісі́х мої́х і пощади́ м'я, Го́споди, в час Стра́шнаго Суда́ Твоєго́. Амі́нь."]}],"notes":[]},{"u":"Молитва преподобного Нектарія Оптинського від антихриста","e":"Prayer of St Nectarius of Optina against the Antichrist","secs":[{"ps":["Го́споди, Ісу́се Христе́, Си́не Бо́жий, гряди́й суди́ти живи́м і ме́ртвим, поми́луй нас, грі́шних, прості́ гріхопаде́нія всей на́шей жи́зні і і́ми же ві́си судьба́ми сокри́й нас от лиця́ антихриста в сокрове́нной пусти́не спасе́нія Твоєго́. Амі́нь."]}],"notes":[]},{"u":"Молитви при ослабленні духу й безчутті до гріха","e":"Prayers in Weakness of Spirit and Insensibility to Sin","secs":[{"h":"Молитва про дарування покаянного почуття, свт. Ігнатія Брянчанінова","ps":["Господи, даруй нам бачити прогрішення наші, щоб розум наш, цілком звернений на власні похибки наші, перестав бачити похибки ближніх і таким чином побачив би всіх ближніх добрими. Даруй серцю нашому залишити згубне піклування про недоліки ближнього, усі піклування свої з’єднати в одне піклування про здобуття заповіданої і приготованої нам Тобою чистоти й святині. Даруй нам, що осквернили душевні ризи, знову убілити їх: вони вже були омиті водами хрещення, потребують тепер, після осквернення, омовіння слізними водами. Даруй нам побачити, при світлі благодаті Твоєї, багатоманітні недуги, що живуть у нас, які знищують у серці духовні рухи, вводять у нього рухи кровні й плотські, ворожі Царству Божому. Даруй нам великий дар покаяння, якому передує і яке народжується великим даром бачення гріхів своїх. Збережи нас цими великими дарами від прірв самообману, який відкривається в душі від непомітної й незбагненної гріховності її; народжується від дії непомітних і незбагненних нею хтивості й марнославства. Збережи нас цими великими дарами на шляху нашому до Тебе і даруй нам досягти Тебе, Що закликаєш тих, хто усвідомлює себе грішником, і відкидаєш тих, хто визнає себе праведником, щоб ми славословили вічно у вічному блаженстві Тебе, Єдиного Істинного Бога, Викупителя полонених, Спасителя загиблих. Амінь."]},{"h":"Псалом 56","ps":["Поми́луй м'я, Бо́же, поми́луй м'я, я́ко на Тя упова́ душа́ моя́, і на сінь крилу́ Твоє́ю наді́юся, до́ндеже пре́йдеть беззако́ніє. Воззову́ к Бо́гу Ви́шнему, Бо́гу благоді́явшему мні. Посла́ с Небесе́ і спа́се м'я, даде́ в поноше́ніє попирающия м'я, посла́ Бог ми́лость Свою́ і і́стину Свою́, і ізба́ви ду́шу мою́ от среди́ ски́мнов. Посла́х смуще́н, си́нове челові́честії, зу́би їх ору́жія і стрі́ли, і язи́к їх меч остр. Вознеси́ся на Небеса́, Бо́же, і по всей землі́ сла́ва Твоя́. Сіть угото́ваша нога́м мої́м і сляко́ша ду́шу мою́, іскопа́ша пред лице́м мої́м я́му і впадо́ша в ню. Гото́во се́рдце моє́, Бо́же, гото́во се́рдце моє́, воспою́ і пою́ во сла́ві моє́й. Воста́ни сла́ва моя́, воста́ни псалти́рю і гу́слі, воста́ну ра́но. Іспові́мся Тебі́ в лю́діх, Го́споди, воспою́ Тебі́ во язи́ціх, я́ко возвели́чися до Небе́с ми́лость Твоя́, і да́же до о́блак і́стина Твоя́. Вознеси́ся на Небеса́, Бо́же, і по всей землі́ сла́ва Твоя́."]}],"notes":[]},{"u":"Молитви при охолодженні любові до ближніх","e":"Prayers When Love for Neighbours Grows Cold","secs":[{"h":"Молитва","ps":["Господи, що скрізь усім даєш життя й дихання і невпинно через служіння створінь доводиш любов Свою до всіх людей. Зроби і мене в цьому подібним до образу Твого, щоб і я невтомно, Тебе ради і за Твоїм прикладом, любив найблагородніше створіння Твоє — ближнього мого, і чинив із ним так, як того вимагає любов, через Ісуса Христа, Господа нашого. Амінь."]},{"h":"Молитва святому апостолу і євангелисту Іоанну Богослову","ps":["О вели́кий апо́столе, євангели́сте громогла́сний, Богосло́ве ізя́щнійший, тайнови́дче неізрече́нних открове́ній, ді́вственниче і возлю́бленний напе́рсниче Христо́в Іоа́нне! Прийми́ нас, грі́шних, под твоє́ си́льноє заступле́ніє прибіга́ющих. Іспроси́ у Всеще́драго Человіколю́бця Христа́ Бо́га на́шего, І́же пред очеси́ твої́ми Кров Свою́ за ни, непотре́бния раби́ Своя́, ізлія́л єсть, да не пом'яне́ть беззако́ній на́ших, но да поми́луєть нас і сотвори́ть с на́ми по ми́лості Своє́й: да да́руєть нам здра́віє душе́вноє і тіле́сноє, вся́коє благоде́нствіє і ізоби́ліє, наставля́я нас обраща́ти о́ная во сла́ву Єго́, Творця́, Спаси́теля і Бо́га на́шего, по кончи́ні же вре́менния жи́зні на́шея от немилосердних істяза́телей на возду́шних мита́рствах да ізба́вить нас, і та́ко да дости́гнем, тобо́ю води́мії і покрива́ємії, Го́рняго о́наго Ієрусали́ма, єго́же сла́ву ти во открове́нії зрел єси́, ни́ні же несконча́ємия ра́дости наслажда́єшися. О вели́кий Іоа́нне! Сохрани́ вся гра́ди і страни́ христия́нськия, храм сей, служа́щих і моля́щихся в нем, от гла́да, губи́тельства, тру́са і пото́па, огня́ і меча́, наше́ствія іноплеме́нних і междоусо́бния бра́ні; ізба́ви нас от вся́кия біди́ і напа́сти і моли́твами твої́ми отврати́ от нас пра́ведний гнів Бо́жий, і Єго́ милосе́рдіє нам іспроси́, да вку́пі с тобо́ю сподо́бимся прославля́ти в невече́рнім дні пресвято́є і́м'я Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]},{"h":"Преподобному Серафиму Саровському","ps":["О, пречу́дний о́тче Серафи́ме, вели́кий Саро́вський чудотво́рче, всім прибегающим к тебі́ скоропослу́шний помо́щниче! Во дні земна́го житія́ твоєго́ нікто́же от тебе́ тощ і неуті́шен оти́де, но всім в сла́дость бисть виді́ніє ли́ка твоєго́ і благоуві́тливий глас слове́с твої́х. К сим же і дар ісціле́ній, дар прозрі́нія, дар немощни́х душ врачева́нія оби́лен в тебі́ яви́ся. Єгда́ же призва́ тя Бог от земни́х трудо́в к небе́сному упокоє́нію, ніколи́же люби́ твоя́ преста́ от нас, і невозмо́жно єсть ісчи́слити чудеса́ твоя́, умно́жившаяся, я́ко зві́зди небе́сния; се бо по всім конце́м землі́ на́шея лю́дем Бо́жиїм явля́єшися і да́руєши їм ісціле́нія. Ті́мже і ми вопіє́м ті: о, прети́хий і кро́ткий уго́дниче Бо́жий, дерзнове́нний к Нему́ моли́твенниче, ніколи́же призивающия тя отріва́яй! Вознеси́ о нас благомо́щную твою́ моли́тву ко Го́споду сил, да да́руєть нам вся благопотре́бная в жи́зні сей і вся к душе́вному спасе́нію поле́зная, да огради́ть нас от паде́ній гріхо́вних і і́стинному покая́нію да научи́ть нас, во є́же безпреткнове́нно вни́ти нам во ві́чноє Небе́сноє Ца́рство, іді́же ти ни́ні в незаходи́мій сія́єши сла́ві, і та́мо воспіва́ти со всі́ми святи́ми Живонача́льную Тро́йцю во ві́ки віко́в. Амі́нь."]},{"h":"Преподобному Силуану Афонському","ps":["О преди́вний уго́дниче Бо́жий, о́тче Силуа́не! По благода́ті, тебі́ от Бо́га да́нной, сле́зно моли́тися о всей вселе́нній – ме́ртвих, живи́х і гряду́щих – не премолчи́ за нас ко Го́споду, к тебі́ усе́рдно припа́дающих і твоєго́ предста́тельства уми́льно прося́щих (імена). Подви́гни, о всеблаже́нне, на моли́тву Усе́рдную Засту́пницю ро́да християнського, Преблагослове́нную Богоро́дицю і Присноді́ву Марі́ю, чу́дно призвавшую тя би́ти ві́рним ді́лателем в Єя́ земно́м вертогра́ді, іді́же ізбра́нници Бо́жії о грісі́х на́ших ми́лостива і долготерпіли́ва би́ти Бо́га умоля́ють, во є́же не пом'янута непра́вд і беззако́ній на́ших, но по неізрече́нной бла́гости Го́спода на́шего Ісу́са Христа́ уще́дрити і спасти́ нас по вели́цій Єго́ ми́лості. Єй, уго́дниче Бо́жий, с Преблагослове́нною Влади́чицею ми́ра – Святейшею Ігуменією Афо́на і святи́ми подвижниками Єя́ земна́го жре́бія іспроси́ у святи́х святейшего Сло́ва святі́й горі́ Афо́нськой і боголюби́вим пустинножителем єя́ от всіх бід і наві́тов вра́жиїх в ми́рі сохрани́тися. Да А́нгели святи́ми от зол ізбавля́ємі і Ду́хом Святи́м во ві́рі і братолю́бії укріпля́ємі, до сконча́нія ві́ка о Єди́ній, Святі́й, Собо́рній і Апо́стольстій Це́ркві моли́тви творя́ть і всім спаси́тельний путь указу́ють, да Це́рков Земна́я і Небе́сная непреста́нно славосло́вить Творця́ і Отця́ Сві́тов, просвіща́ющи і освіща́ющи мир во ві́чной пра́вді і бла́гости Бо́жієй. Наро́дом землі́ всей іспроси́ благоде́нственноє і ми́рноє житіє́, дух смиренному́дрія і братолю́бія, добронра́вія і спасе́нія, дух стра́ха Бо́жия. Да не зло́ба і беззако́ніє ожесточають се́рдця людські́я, могу́щиє істреби́ти любо́в Бо́жию в челові́ціх і низвергнуть їх в богопротивную вражду́ і братоубийство, но в си́лі Боже́ственния любве́ і пра́вди, я́коже на небесі́ і на землі́ да святи́ться і́м'я Бо́жиє, да бу́деть во́ля Єго́ свята́я в челові́ціх, і да воцари́ться мир і Ца́рствіє Бо́жиє на землі́. Та́кожде і земно́му Оте́честву твоєму́ – землі́ Українській іспроси́, уго́дниче Бо́жий, вожделі́нний мир і небе́сноє благослове́ніє, во є́же всемо́щним омофо́ром Ма́тере Бо́жия покрива́єму, ізба́витися єму́ от гла́да, губи́тельства, тру́са, огня́, меча́, наше́ствія іноплеме́нников і междоусо́бния бра́ні і от всіх враг ви́димих і неви́димих, і та́ко святі́йшим домо́м Преблагослове́нния Богоро́диці до сконча́нія ві́ка єму́ преби́ти, Креста́ Животворя́щаго си́лою, і в любві́ Бо́жієй неоскудіва́єму утверди́тися. Нам же всім, во тьму гріхо́в погружа́ємим і покая́нія тепла́, ніже́ стра́ха Бо́жия не іму́щим і си́це безмі́рно лю́б'ящаго нас Го́спода непреста́нно оскорбляющим, іспроси́, о всеблаже́нне, у Всеще́драго Бо́га на́шего, да Своє́ю Всеси́льною благода́тію боже́ственне посіти́ть і оживотвори́ть душі́ на́ша, і вся́ку зло́бу і го́рдость жите́йськую, уни́ніє і нераді́ніє в сердця́х на́ших да упраздни́ть. Єще́ мо́лимся, о є́же і нам, благода́тію Всесвята́го Ду́ха укріпля́ємим і любо́вію Бо́жию согреваємим, в человіколю́бії і братолю́бії, смиренномудренном сраспинанії друг за дру́га і за всіх, в пра́вді Бо́жієй утверди́тися і в благодатной любві́ Бо́жієй благонра́вно укріпи́тися, і синолюбне Тому́ прибли́житися. Да та́ко, творя́ще Єго́ всясвятую во́лю, во вся́ком благоче́стії і чистоті́ вре́меннаго житія́ путь непости́дно пре́йдем і со всі́ми святи́ми Небе́снаго Ца́рствія і Єго́ Агнчаго бра́ка сподо́бимся. Єму́ же от всіх земни́х і небе́сних да бу́деть сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м, Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь"]},{"h":"Молитва перед іконою Матері Божої «Розчулення»","ps":["Прийми́, всеблагомо́щная, Пречи́стая Госпоже́ Влади́чице Богороди́тельнице, сія́ честниє да́ри, Тебі́ єди́ній прикла́дния, от нас, недосто́йних рабо́в Твої́х: от всіх родо́в ізбра́нная, всіх тва́рей небе́сних і земни́х ви́сшая я́вльшаяся, поне́же бо Тебе́ ра́ди бисть Госпо́дь Сил с на́ми, і Тобо́ю Си́на Бо́жия позна́хом і сподо́бихомся свята́го Ті́ла Єго́ і пречи́стия Кро́ве Єго́; ті́мже блаже́нна єси́ в ро́діх родо́в, Богоблаже́нная, Херуви́мов світлі́йши і Серафи́мов честні́йши су́щая. І ни́ні, всепі́тая Пресвята́я Богоро́дице, не преста́й моля́щися о нас, недосто́йних рабі́х Твої́х, є́же ізба́витися нам от вся́каго сові́та лука́ваго і вся́каго обстоя́нія і сохрани́тися нам неврежде́нним от вся́каго ядови́таго прило́га дия́вольськаго; но да́же до конця́ моли́твами Твої́ми неосужде́нних нас соблюди́, я́ко да Твої́м заступле́нієм і по́мощію спаса́ємі, сла́ву, хвалу́, благодаре́ніє і поклоне́ніє за вся в Тро́йці Єди́ному Бо́гу і всіх Созда́телю возсила́єм, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитви про допомогу Божу у виправленні життя","e":"Prayers for God’s Help in Amending One’s Life","secs":[{"h":"Молитва з творів св. Єфрема Сиріна","ps":["Господи, Боже Вседержителю, згрішив я на небо і перед Тобою і вже не гідний зватися сином Твоїм, ані назвати славне ім’я Твоє грішними устами моїми, бо я вчинив себе недостойним неба й землі, розгнівавши Тебе, благого Владику! Недостойний я просити для себе прощення, Господи, бо багато разів давав обіцянку покаятися — і ставав брехуном, що не виконав обіцянки, багато разів уже підіймав Ти мене, але я знову падав добровільно. Сам над собою виношу вирок і признаюся, що гідний я всякої кари й муки.","Благаю Тебе, Господи, не відкинь мене від лиця Твого й не відступи від мене, щоб не загинув я. Нині припадаю до Тебе, благаючи: допоможи мені, що збочив зі шляху правди. Вилий на мене щедроти Твої, як на блудного сина, бо я осоромив життя своє, розтринькавши багатство благості Твоєї. Помилуй мене і не знехтуй мене через непотрібне життя моє. Помилуй мене, як митаря, як розбійника: він на землі був відкинутий усіма, але Ти прийняв його й зробив мешканцем раю солодощів.","Милостиво прийми молитву мою про примирення з Тобою і, за благістю Твоєю, даруй мені життя в пришестя Твоє; і нехай посоромиться лукавий, коли побачить, що помилувала мене правда Твоя. Даруючи прощення, Господи, пошли й силу; наверни мене так, щоб і жити мені за святою волею Твоєю.","Скільки разів відвідував Ти затьмарений розум мій, але я знову повертаюся до гіршого! Весь здригаюся, роздумуючи про це, і знову перемагає мене солодощ гріховна. Як перелічу всі дари благодаті Твоєї, Господи, які отримав я, жалюгідний, але обернув і обертаю в ніщо своїм нерадінням! Тисячами дарів сповнював Ти мене, а я, бідний, віддячую Тобі тим, що противне Тобі.","Але Ти, Господи, оскільки в Тобі море довготерпіння і безодня милосердя в Тебе, не дозволь зрубати мене, як безплідну смоківницю. Не вихопи мене, неготового, не візьми того, хто ще не запалив світильника, не бери звідси того, хто не має на собі шлюбного одягу, але, як благий Чоловіколюбець, помилуй мене, дай мені час на покаяння і перед страшним, непідкупним престолом Твоїм не постав душу мою оголеною, мов жалюгідне видовисько безслав’я.","Ти, Господи, Спасителю мій, Сину Бога істинного, як Сам знаєш і як Сам хочеш, з єдиної благості Твоєї, безкоштовно наверни мене від гріха, що пробуває в мені, і спаси від погибелі.","Скільки разів, о Владико Господи Ісусе, оновлював Ти легковажно розтлінну гріхами моїми природу мою! Немає тому ні числа, ні міри! Скільки разів Ти виймав мене з печі, що горить у мене всередині, з печі пристрастей різноманітних, з пропасті зневіри й відчаю! Скільки разів одним ім’ям Твоїм, з вірою мною призиваним, оновлював Ти моє розтління серцеве! Скільки разів звершив Ти це через животворящі Тайни. О, Владико! Милостям Твоїм до мене, грішного, воістину, немає ні числа, ні міри. Що ж я принесу Тобі, або що віддам Тобі за безмірні Твої до мене благодіяння, Ісусе, Життя моє і полегшення моє! Нехай буду я обачним на путях моїх за благодаттю Твоєю, бо Тобі приємні всі обачні в дорозі, як Ти Духом Своїм устами отця нашого, Давида, промовив; постараюся бути вірним Тобі, смиренним, лагідним, нерозлютованим, незлобивим, довготерпеливим, працьовитим, милостивим, щедрим, нехтуючим грошима, слухняним. Господи, Сило всемогутня! Утверди немічну душу мою в усякій доброчесності! На непорушному камені заповідей Твоїх утверди слабке до всякого добра серце моє! Господи! І я щодня досвідно пізнаю, що без Тебе я ніщо; що без Тебе не можу чинити жодного добра; без Тебе одне зло в мені в різних його видах; без Тебе я син погибелі. О, преневимовна Благостине! Наповни благістю Твоєю серце моє! Паче ж усього благаю: даруй мені любити Тебе всім серцем моїм і ближнього мого, як себе. Нехай не буду я злобний, гордий, зарозумілий, неспокійний, але нехай буду незлобивий, смиренний, шанобливий з ніжністю й слухняний."]},{"h":"Псалом 30","ps":["На Тя, Го́споди, упова́х, да не постижу́ся во вік: пра́вдою Твоє́ю ізба́ви м'я і ізми́ м'я. Приклони́ ко мні у́хо Твоє́, ускори́ із'яти м'я, бу́ди мі в Бо́га Защи́тителя, і в дом прибі́жища, є́же спасти́ м'я. Я́ко держа́ва моя́ і прибі́жище моє́ єси́ Ти, і і́мене Твоєго́ ра́ди наста́виши м'я, і препита́єши м'я. Ізведе́ши м'я от сі́ті сея́, ю́же скри́ша мі, я́ко Ти єси́ Защи́титель мой, Го́споди. В ру́ці Твої́ предложу́ дух мой: ізба́вил м'я єси́, Го́споди Бо́же і́стини. Возненави́діл єси́ храня́щия суєти́ вотще́: аз же на Го́спода упова́х. Возра́дуюся і возвеселю́ся о ми́лості Твоє́й, я́ко призрі́л єси́ на смире́ніє моє́, спасл єси́ от нужд ду́шу мою́, і ні́си мене́ затвори́л в рука́х вра́жиїх, поста́вил єси́ на простра́нні но́зі мої́. Поми́луй м'я, Го́споди, я́ко скорблю́: см'яте́ся я́ростію о́ко моє́, душа́ моя́ і утро́ба моя́. Я́ко ісчезе́ в болі́зні живо́т мой і лі́та моя́ во воздиха́ніїх, ізнемо́же нището́ю крі́пость моя́ і ко́сті моя́ см'ято́шася. От всіх враг мої́х бих поноше́ніє, і сосі́дом мої́м зіло́, і страх зна́ємим мої́м: ви́дящий м'я вон біжа́ша от мене́. Забве́н бих я́ко мертв от се́рдця, бих я́ко сосу́д погубле́н, Я́ко сли́шах гажде́ніє мно́гих, живу́щих о́крест, внегда́ собра́тися їм вку́пі на м'я, прия́ти ду́шу мою́ совіща́ша. Аз же на Тя, Го́споди, упова́х, ріх: Ти єси́ Бог мой. В ру́ку Твоє́ю жре́бії мої́: ізба́ви м'я із руки́ враг мої́х і от гоня́щих м'я. Просвіти́ лице́ Твоє́ на раба́ Твоєго́, спаси́ м'я ми́лостію Твоє́ю. Го́споди, да не постижу́ся, я́ко призва́х Тя: да постидя́ться нечести́вії і сни́дуть во ад. Ні́ми да бу́дуть устни́ льсти́вия, глаго́лющия на пра́веднаго беззако́ніє, горди́нею і уничиже́нієм. Коль мно́гоє мно́жество бла́гости Твоєя́, Го́споди, ю́же скрил єси́ боящимся Тебі́, соді́лал єси́ уповающим на Тя пред си́ни челові́чеськими. Скри́вши їх в та́йні лиця́ Твоєго́ от м'яте́жа челові́чеська, покри́єши їх в кро́ві от преріка́нія язи́к. Благослове́н Госпо́дь, я́ко удиви́ ми́лость Свою́ во гра́ді огражде́нія. Аз же ріх во ізступле́нії моє́м: отве́ржен єсьм от лиця́ о́чію Твоє́ю: сего́ ра́ди усли́шал єси́ глас моли́тви моєя́, внегда́ воззва́х к Тебі́. Возлюбі́те Го́спода, всі преподо́бнії Єго́, я́ко і́стини взиска́єть Госпо́дь, і воздає́ть ізли́ше творя́щим горди́ню. Мужа́йтеся, і да кріпи́ться се́рдце ва́ше, всі упова́ющії на Го́спода."]},{"h":"Псалом 37","ps":["Го́споди, да не я́ростію Твоє́ю обличи́ши мене́, ніже́ гні́вом Твої́м нака́жеши мене́. Я́ко стрі́ли Твоя́ унзо́ша во мні, і утверди́л єси́ на мні ру́ку Твою́. Ність ісціле́нія в пло́ті моє́й от лиця́ гні́ва Твоєго́, ність ми́ра в костеіх мої́х от лиця́ гріх мої́х. Я́ко беззако́нія моя́ превзидо́ша главу́ мою́, я́ко бре́м'я тя́жкоє отяготі́ша на мні. Возсмерді́ша і согни́ша ра́ни моя́ от лиця́ безу́мія моєго́. Пострада́х і сляко́хся до конця́, весь день сі́туя хожда́х. Я́ко ля́двія моя́ напо́лнишася поруга́ній, і ність ісціле́нія в пло́ті моє́й. Озло́блен бих і смири́хся до зіла́, рика́х от воздиха́нія се́рдця моєго́. Го́споди, пред Тобо́ю все жела́ніє моє́ і воздиха́ніє моє́ от Тебе́ не утаї́ся. Се́рдце моє́ см'яте́ся, оста́ви м'я си́ла моя́, і світ о́чію моє́ю, і той ність со мно́ю. Дру́зі мої́ і і́скреннії мої́ пря́мо мні прибли́жишася і ста́ша. І бли́жнії мої́ отдале́че мене́ ста́ша; і нужда́хуся і́щущії ду́шу мою́, і і́щущії зла́я мні, глаго́лаху су́єтная, і льсти́вним весь день поуча́хуся. Аз же, я́ко глух, не сли́шах, і я́ко нем, не отверза́яй уст свої́х. І бих, я́ко челові́к не сли́шан, і не іми́й во усті́х свої́х обличе́нія. Я́ко на Тя, Го́споди, упова́х, Ти усли́шиши, Го́споди, Бо́же мой! Я́ко ріх, да не когда́ пора́дуютмися вразі́ мої́, і внегда́ подвижа́тися нога́м мої́м, на м'я велері́чеваша. Я́ко аз на ра́ни гото́в, і болі́знь моя́ предо мно́ю єсть ви́ну. Я́ко беззако́ніє моє́ аз возвіщу́, і попеку́ся о грісі́ моє́м. Вразі́ же мої́ живу́ть, і укріпи́шася па́че мене́, і умно́жишася ненави́дящії м'я без пра́вди. Воздаю́щії мі зла́я возблагая, оболга́ху м'я, зане́ гоня́х благости́ню. Не оста́ви мене́, Го́споди Бо́же мой, не отступи́ от мене́. Воньми́ в по́мощ мою́, Го́споди спасе́нія моєго́!"]}],"notes":[]},{"u":"Молитва від гніву","e":"Prayer against Anger","secs":[{"h":"Молитва авви Дорофея","ps":["Боже милосердний і чоловіколюбний! За невимовною Твоєю благістю створивши нас із нічого для насолоди Твоїми благами і кров’ю Єдинородного Сина Твого, Спасителя нашого, закликавши нас, що відступили від Твоїх заповідей! Прийди й нині, допоможи немочі нашій, і як Ти колись заборонив бурхливому морю, так і нині заборони хвилювання сердець наших, щоб Ти не втратив за одну годину обох нас, дітей Своїх, умертвлених гріхом, і щоб не сказав нам: «яка користь у Крові Моїй, коли сходжу Я в тління», і: «амінь кажу вам, не знаю вас», бо світильники наші погасли через брак оливи. Амінь."]}],"notes":[]},{"u":"Молитви в бісівських нападах і спокусах","e":"Prayers in Demonic Assaults and Temptations","secs":[{"h":"Молитва Чесному Хресту","ps":["Да воскре́снеть Бог, і расточа́ться вразі́ Єго́, і да біжа́ть от лиця́ Єго́ ненави́дящії Єго́. Я́ко ісчеза́єть дим, да ісче́знуть; я́ко та́єть воск от лиця́ огня́, та́ко да поги́бнуть бі́си от лиця́ лю́б'ящих Бо́га і зна́менующихся крестним зна́менієм, і во весе́лії глаго́лющих: ра́дуйся, Пречестни́й і Животворя́щий Кре́сте Госпо́день, прогоня́яй бі́си си́лою на тебі́ проп'я́таго Го́спода на́шего Ісу́са Христа́, во ад сше́дшаго і попра́вшаго си́лу дия́волю, і дарова́вшаго нам тебе́ Крест Свой Честни́й на прогна́ніє вся́каго супоста́та. О, Пречестни́й і Животворя́щий Кре́сте Госпо́день! Помога́й мі со Свято́ю Госпоже́ю Ді́вою Богоро́дицею і со всі́ми святи́ми во ві́ки. Амі́нь."]},{"h":"Або коротко","ps":["Огради́ м'я, Го́споди, си́лою Честна́го і Животворя́щаго Твоєго́ Креста́, і сохрани́ м'я от вся́каго зла."]},{"h":"Псалом 90","ps":["Живи́й в по́мощі Ви́шняго, в кро́ві Бо́га Небе́снаго водвори́ться. Рече́ть Го́сподеві: Засту́пник мой єси́ і Прибі́жище моє́, Бог мой, і упова́ю на Него́. Я́ко Той ізба́вить тя от сі́ті ло́вчі, і от словесе́ м'яте́жна, плещма́ Свої́ма осіни́ть тя, і под крилі́ Єго́ наді́єшися: ору́жієм оби́деть тя і́стина Єго́. Не убої́шися от стра́ха нощна́го, от стрі́ли летя́щия во дні, от ве́щі во тьмі преходя́щия, от сря́ща, і бі́са полу́деннаго. Паде́ть от страни́ твоєя́ ти́сяща, і тьма одесну́ю тебе́, к тебі́ же не прибли́житься; оба́че очи́ма твої́ма смо́триши, і воздая́ніє грі́шников у́зриши. Я́ко Ти, Го́споди, упова́ніє моє́, Ви́шняго положи́л єси́ прибі́жище твоє́. Не при́йдеть к тебі́ зло, і ра́на не прибли́житься тілесі́ твоєму́, я́ко А́нгелом Свої́м запові́сть о тебі́, сохрани́ти тя во всіх путеіх твої́х. На рука́х во́зьмуть тя, да не когда́ преткне́ши о ка́мень но́гу твою́; на а́спида і васили́ска насту́пиши, і попере́ши льва і змі́я. Я́ко на М'я упова́, і ізба́влю і: покри́ю і, я́ко позна́ і́м'я Моє́. Воззове́ть ко Мні, і усли́шу єго́: с ним єсьм в ско́рбі, ізму́ єго́ і просла́влю єго́, долгото́ю дній іспо́лню єго́, і явлю́ єму́ спасе́ніє Моє́."]},{"h":"Молитва Святому і Животворящому Хресту Господньому","ps":["Пред дивною чудоді́йственною си́лою, Четвероконе́чний і Трисоста́вний Кре́сте Христо́в, у подно́жія твоєго́ во прах распростертий, покланя́юся ті, Честно́є Дре́во, отгоня́ющеє от мене́ вся́коє де́монськоє стріля́ніє і освобождающеє от всіх бід, скорбе́й і напа́стей. Ти бо єси́ Дре́во Жи́зні. Ти єси́ очище́ніє возду́ха, освіще́ніє свята́го хра́ма, огражде́ніє моєго́ жили́ща, охране́ніє одра́ моєго́, просвіще́ніє ума́ моєго́, се́рдця і всіх мої́х чувств. Твоє́ свято́є зна́меніє огражда́єть м'я со дня моєго́ рожде́нія, просвіща́єть со дня моєго́ креще́нія; о́но со мно́ю і на мні во вся дні живота́ моєго́: і на су́ші, і на вода́х. О́но же сопровождать м'я бу́деть до могили, осіни́ть і прах мой. О́но же, свято́є зна́меніє чудодейственнаго Креста́ Госпо́дня, возвісти́ть всей вселе́нній о часі́ всео́бщаго воскресе́нія ме́ртвих і послі́дняго Стра́шнаго і Пра́веднаго Суда́ Бо́жия. О Кресті́ Всечестни́й! Осіне́нієм твої́м вразуми́, научи́ і благослови́ м'я, недосто́йнаго, всегда́ несомні́нно верующего в непобіди́мую Си́лу Твою́, огради́ м'я от вся́каго супоста́та і ісціли́ вся неду́ги моя́ душе́вния і тіле́сния. Го́споди, Ісу́се Христе́, Си́не Бо́жий, си́лою Честна́го і Животворя́щаго Креста́ Твоєго́ поми́луй і спаси́ м'я, грі́шнаго, от ни́ні і во ві́ки віко́в. Амі́нь."]},{"h":"Псалом 45","ps":["Бог нам Прибі́жище і Си́ла, Помо́щник в ско́рбіх, обрі́тших ни зіло́. Сего́ ра́ди не убої́мся, внегда́ смуща́ється земля́ і прелага́ються гори́ в се́рдця морська́я. Возшумі́ша і см'ято́шася води́ їх, см'ято́шася гори́ крі́постію Єго́. Річна́я устремле́нія веселя́ть град Бо́жий: освяти́л єсть селе́ніє Своє́ Ви́шній. Бог посреді́ єго́, і не подви́житься: помо́жеть єму́ Бог у́тро зау́тра. См'ято́шася язи́ци, уклонишся ца́рствія: даде́ глас Свой Ви́шній, подви́жеся земля́. Госпо́дь сил с на́ми, Засту́пник наш Бог Іа́ковль. Прийді́те і ви́діте діла́ Бо́жия, я́же положи́ чудеса́ на землі́: отьемля бра́ні до коне́ць землі́, лук сокруши́ть і сло́мить ору́жіє, і щити́ сожже́ть огне́м. Упраздні́теся і разумі́йте, я́ко Аз єсьм Бог: вознесу́ся во язи́ціх, вознесу́ся на землі́. Госпо́дь сил с на́ми, Засту́пник наш Бог Іа́ковль."]}],"notes":[]},{"u":"Молитва, коли не прощаються образи й пам’ятається зле","e":"Prayer When Offences Are Not Forgiven and Evil Is Remembered","secs":[{"ps":["Спасителю мій, навчи мене простити від усієї душі всіх, хто чимось мене скривдив. Я знаю, що не можу постати перед Тобою з почуттями ворожнечі, які таяться в моїй душі. Очерствіло моє серце! Немає в мені любові! Допоможи мені, Господи! Благаю Тебе, навчи мене простити тих, хто кривдить мене, як Сам Ти, Бог мій, на Хресті простив ворогів Твоїх!"]}],"notes":[]},{"u":"Молитви в зневірі","e":"Prayers in Despondency","secs":[{"h":"Молитва з творів свт. Димитрія Ростовського","ps":["Боже, Отче Господа нашого Ісуса Христа, Отче щедрот і Боже всякої втіхи, що втішаєш нас у всякій скорботі нашій! Утіш кожного скорботного, засмученого, відчайдушного, збентеженого духом зневіри. Адже кожна людина створена руками Твоїми, умудрена премудрістю, звеличена десницею Твоєю, прославлена благістю Твоєю… Та ось відвідані ми нині Отцівською Твоєю карою, короткочасними скорботами! — Ти співчутливо караєш тих, кого любиш, і щедро милуєш та поглядаєш на їхні сльози! Отож, покаравши, помилуй і вгамуй печаль нашу; оберни скорботу на веселощі й радістю розведи печаль нашу; яви на нас дивну милість Твою, дивний у радах Владико, Незбагненний у долях Господи, і благословенний у ділах Твоїх повіки, амінь."]},{"h":"Молитва про визволення від зневіри, св. Івана Кронштадтського","ps":["Господь — знищення зневіри моєї й оживлення сміливості моєї. Усе для мене Господь. О, воістину Сущий Владико, слава Тобі! Слава Тобі, Життя Отче, Життя Сину, Життя Душе Святий — Просте Єство — Боже, що завжди визволяєш нас від душевної смерті, пристрастями душі нашій заподіюваної. Слава Тобі, Триіпостасний Владико, бо від самого призивання імені Твого просвітлюєш похмуре лице душі й тіла нашого і обдаровуєш миром Твоїм, що перевершує всяке земне й чуттєве благо і всякий розум."]},{"h":"Псалом 101","ps":["Го́споди, усли́ши моли́тву мою́, і вопль мой к Тебі́ да при́йдеть. Не отврати́ лиця́ Твоєго́ от мене́: во́ньже а́ще день скорблю́, приклони́ ко мні у́хо Твоє́: во́ньже а́ще день призову́ Тя, ско́ро усли́ши м'я. Я́ко ісчезо́ша я́ко дим дні́є мої́, і ко́сті моя́ я́ко суши́ло сосхо́шася. Уя́звен бих я́ко трава́, і і́зсше се́рдце моє́, я́ко заби́х сні́сти хліб мой. От гла́са воздиха́нія моєго́ прильпе́ кость моя́ пло́ті моє́й. Уподо́бихся нея́сити пусти́нній, бих я́ко нощни́й вран на ни́рищі. Бдіх і бих я́ко пти́ця осо́б'ящаяся на зді. Весь день поноша́ху мі вразі́ мої́, і хва́лящії м'я мно́ю кленя́хуся. Зане́ пе́пел я́ко хліб ядя́х, і питіє́ моє́ с пла́чем растворя́х. От лиця́ гні́ва Твоєго́ і я́рости Твоєя́: я́ко возне́с низве́ргл м'я єси́. Дні́є мої́ я́ко сінь уклони́шася, і аз я́ко сі́но ізсхо́х. Ти же, Го́споди, во вік пребива́єши, і па́м'ять Твоя́ в род і род. Ти воскре́с уще́дриши Сіо́на, я́ко вре́м'я уще́дрити єго́, я́ко при́йде вре́м'я. Я́ко благоволи́ша раби́ Твої́ ка́меніє єго́, і персть єго́ уще́дрять. І убоя́ться язи́ци і́мене Госпо́дня, і всі ца́ріє зе́мстії сла́ви Твоєя́. Я́ко сози́ждеть Госпо́дь Сіо́на, і яви́ться во сла́ві Своє́й. Призрі́ на моли́тву смире́нних, і не уничижи́ моле́нія їх. Да напи́шеться сіє́ в род ін, і лю́діє зи́ждемії восхва́лять Го́спода. Я́ко прини́че с висоти́ святи́я Своєя́, Госпо́дь с Небесе́ на зе́млю призрі́, усли́шати воздиха́ніє окова́нних, разріши́ти си́ни умерщвле́нних, возвісти́ти в Сіо́ні і́м'я Госпо́днє, і хвалу́ Єго́ во Ієрусали́мі. Внегда́ собра́тися лю́дем вку́пі і царе́м, є́же рабо́тати Го́сподеві. Отвіща́ єму́ на путі́ крі́пости єго́, умале́ніє дній мої́х возвісти́ мі. Не возведи́ мене́ во преполове́ніє дній мої́х: в ро́ді родо́в лі́та Твоя́. В нача́ліх Ти, Го́споди, зе́млю основа́л єси́, і діла́ ру́ку Твоє́ю суть небеса́. Та поги́бнуть, Ти же пребива́єши, і вся я́ко ри́за обетша́ють, і я́ко оде́жду свіє́ши я, і ізміня́ться. Ти же то́йжде єси́, і лі́та Твоя́ не оскуді́ють. Си́нове раб Твої́х вселя́ться, і сі́м'я їх во вік іспра́виться."]},{"h":"Святителю Тихону Задонському","ps":["О всехва́льний святи́телю і уго́дниче Христо́в, о́тче наш Ти́хоне! А́нгельськи на землі́ пожи́в, ти я́ко а́нгел благи́й яви́лся єси́ і в давнем твоє́м прославле́нії: ві́руєм от всея́ душі́ і помишле́нія, я́ко ти, благосе́рдий наш помо́щниче і моли́твенниче, твої́ми нело́жними хода́тайстви і благода́тію, от Го́спода оби́льно тебі́ дарова́нною, при́сно спосо́бствуєши на́шему спасе́нію. Прийми́ у́бо, ублажа́ємий уго́дниче Христо́в, і в час сей на́ша недосто́йная моле́нія: свободи́ ни твої́м заступле́нієм от облега́ющаго нас суєсло́вія і суєму́дрія, неправові́рія і злові́рія челові́чеськаго; потщи́ся, ско́рий о нас предста́телю, благоприя́тним твої́м хода́тайством умоли́ти Го́спода, да проба́вить Своя́ вели́кия і бога́тия ми́лости на нас грі́шних і недосто́йних рабі́х Свої́х (імена́), да уврачу́єть Своє́ю благода́тію неісцеленния я́зви і стру́пи растлі́нних душ і тіле́с на́ших, да раствори́ть окамені́лая се́рдця на́ша слеза́ми умиле́нія і сокруше́нія о премно́гих согріше́ніїх на́ших, і да ізба́вить ни от ві́чних мук і огня́ геє́нськаго; всім же ві́рним лю́дем Свої́м да да́руєть в ни́нішнем ві́ці мир і тишину́, здра́віє і спасе́ніє і во всем благо́є поспіше́ніє, да та́ко, ти́хоє і безмо́лвноє житіє́ пожи́вше во вся́ком благоче́стії і чистоті́, сподо́бимся со А́нгели і со всі́ми святи́ми сла́вити і воспіва́ти всесвято́є і́м'я Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в."]},{"h":"Молитви перед іконами Матері Божої «Утоли моя печалі»","ps":["Наде́ждо всім конце́м землі́, Пречи́стая Ді́во, Госпоже́ Богоро́дице, утіше́ніє на́ше! Не гнуша́йся нас грі́шних, на Твою́ бо ми́лость упова́єм: угаси́ горя́щий в нас пла́мень гріхо́вний і покая́нієм ороси́ ізсо́хшая се́рдця на́ша; очи́сти ум наш от гріхо́вних помисло́в, прийми́ мольби́, от душі́ і се́рдця со воздиха́нієм Тебі́ приноси́мия. Бу́ди о нас хода́тайця к Си́ну Твоєму́ і Бо́гу і отврати́ гнів Єго́ Ма́терніми Твої́ми моли́твами. Душе́вния і тіле́сния я́зви ісціли́, Госпоже́ Влади́чице, утоли́ болі́зні душ і тіле́с, утиши́ бу́рю злих нападе́ній вра́жеських, отими́ бре́м'я гріхо́в на́ших, і не оста́ви нас до конця́ поги́бнути, і печа́лію сокруше́нная се́рдця на́ша уті́ши, да сла́вим Тя до послі́дняго іздиха́нія на́шего."]},{"h":"Молитви перед іконами Матері Божої «Нечаянная Радість»","ps":["О, Пресвята́я Ді́во, Всеблага́го Си́на Ма́ти Всеблага́я, гра́да і свята́го хра́ма сего́ Покрови́тельнице, всіх су́щих во грісі́х, ско́рбіх, біда́х і болі́зніх ві́рная Предста́тельнице і Засту́пнице! Прийми́ моле́бноє пі́ніє сіє́ от нас, недосто́йних рабо́в Твої́х, Тебі́ возноси́моє, і я́коже дре́вле грі́шника, на всяк день мно́гажди пред честно́ю іко́ною Твоє́ю моли́вшагося, не презрі́ла єси́, но дарова́ла єси́ єму́ неча́янную ра́дость покая́нія і приклонила єси́ Си́на Твоєго́ мно́гим і усе́рдним к Нему́ хода́тайством ко проще́нію сего́ грі́шнаго і заблу́ждшагося, та́ко і ни́ні не пре́зри моле́нія нас, недосто́йних рабо́в Твої́х, і умоли́ Си́на Твоєго́ і Бо́га на́шего, да і всім нам с ві́рою і умиле́нієм покланяющимся пред цільбоно́сним о́бразом Твої́м, да́руєть неча́янную по коєго́ждо потре́бі ра́дость: па́стирем церко́вним – святу́ю ре́вность о спасе́нії пасо́мих; грі́шником, погрязшим во глубині́ зол і страсте́й – вседі́йственноє вразумле́ніє, покая́ніє і спасе́ніє; су́щим в ско́рбіх і печа́ліх – утіше́ніє; обріта́ющихся в біда́х і озлобленіях – соверше́нноє їх ізбитіє́; малоду́шним і ненаде́жним – наде́жду і терпі́ніє; в ра́дості і дово́льстві живу́щим – непреста́нноє Благоді́телю Бо́гу благодаре́ніє; бедствующим – милосе́рдіє; су́щим в болі́зні і долгонеду́жії і оста́вленним врача́ми – неча́янноє ісціле́ніє і укріпле́ніє; іждившим от неду́га ум – ума́ возвраще́ніє і обновле́ніє; отходящим во ві́чную і несконча́ємую жизнь – па́м'ять сме́ртную, умиле́ніє і сокруше́ніє о грісі́х, дух бодр і тве́рдую на милосе́рдіє Бо́жиє наде́жду. О, Госпожі́ Пресвята́я! Умилосе́рдися ко всім, чту́щим всечестно́є і́м'я Твоє́, і всім яви́ всемо́щний покро́в Твой і заступле́ніє; во благоче́стії, чистоті́ і честні́м жи́тельстві пребива́ющия до послі́дняго їх сконча́нія во бла́гости соблюди́; зли́я бла́гі сотвори́; заблужде́нія на путь пра́вий наста́ви; вся́кому ді́лу благо́му і Си́ну Твоєму́ уго́дному споспі́шествуй; вся́коє ді́ло зло́є і богопроти́вноє разруши́; в недоумі́нії і тру́дних і опа́сних обстоя́ніїх обріта́ющимся незри́мую по́мощ і вразумле́ніє с небе́с низпосли́; от іскуше́ній, собла́знов і поги́белі спаси́; от всіх злих челові́к і от враго́во ви́димих і неви́димих защити́ і сохрани́; пла́вающим спла́вай; путешествующим спутеше́ствуй; су́щим в ну́жді і гла́ді бу́ди Пита́тельниця, неімущим кро́ва і приста́нища бу́ди Покро́в і Прибі́жище; наги́м пода́ждь одія́ніє; оби́димим і от непра́вд стра́ждущим – заступле́ніє; клевету́, поноше́ніє і хуле́ніє терп'ящия незри́мо оправда́й; клеветники́ і хули́телі пред всі́ми обличи́; ожесточе́нно враждующим нечаємо пода́ждь примире́ніє, і всім нам друг ко дру́гу любо́в, мир і благоче́стіє і здра́віє с долгоде́нствієм. Супру́жества в любві́ і єдиноми́слії сохрани́; супру́ги, во вражді́ і разділе́нії су́щия, умири́, соєдини́ друг ко дру́гу і положи́ їм сою́з любве́ неразруши́мий; ма́терем, ді́ти родящим, ско́роє пода́ждь разріше́ніє; младе́нці воспита́й, ю́ния уцілому́дри, отве́рзи ум к восприя́тію вся́каго поле́знаго уче́нія, стра́ху Бо́жию, воздержа́нію і трудолю́бію наста́ви; от дома́шнія бра́ні і вражди́ єдинокро́вних ми́ром і любо́вію огради́. Безма́терніх сиро́т бу́ди Ма́тер, от вся́каго поро́ка і скве́рни отврати́ я і всему́ благо́му і богоуго́дному научи́; прельще́нния же і во гріх і нечистоту́ впадшия, скве́рну гріха́ от'явши, із бе́здни поги́белі ізведи́. Вдов бу́ди Уті́шительниця і Помо́щниця, ста́рости бу́ди жезл. От внеза́пния сме́рті без покая́нія всіх нас ізба́ви, і всім нам христия́нськую кончи́ну живота́ на́шего, безболі́зненну, непости́дну, ми́рну і до́брий отві́т на стра́шном суди́щі Христо́ві да́руй, преста́вльшіяся во ві́рі і покая́нії от житія́ сего́ со а́нгели і всі́ми святи́ми жи́ти сотвори́; сконча́вшимся внеза́пною сме́ртію ми́лостива би́ти Си́на Твоєго́ умоли́; о всіх усо́пших, і́же не і́муть сро́дников, о упокоє́нії їх Си́на Твоєго́ умоля́ющих, Сама́ бу́ди непреста́нная і те́плая Моли́твенниця і Хода́тайця; да всі на небесі́ і на землі́ ві́дять Тя, я́ко тве́рдую і непости́дную Предста́тельницю ро́да христия́нськаго, сла́в'ять Тя і Тобо́ю Си́на Твоєго́ со Безнача́льним Єго́ Отце́м і Єдиносу́щним Єго́ Ду́хом, ни́ні і при́сно і во ві́ки Віко́в. Амі́нь."]},{"h":"Молитви перед іконами Матері Божої «Всіх скорботних Радість»","ps":["О, Пресвята́я Влади́чице Богоро́дице, преблагослове́нная Ма́ти Христа́ Бо́га, Спаси́теля на́шего, всіх скорб'я́щих ра́досте, больни́х посіще́ніє, немощни́х покро́ве і засту́пнице, вдови́ць і си́рих покрови́тельнице, ма́терей печа́льних всенаде́жная уті́шительнице, младе́нцев немощни́х крі́посте, і всім безпомо́щним всегда́ гото́вая по́моще і ві́рноє прибі́жище! Тебі́, о Всеми́лостивая, даде́ся от Всеви́шняго благода́ть во є́же всіх заступа́ти і ізбавля́ти от скорбе́й і болі́зней, зане́ Сама́ лю́тия ско́рби і болі́зні претерпі́ла єси́, взира́ющи на во́льноє страда́ніє Си́на Твоєго́ возлю́бленнаго і Того́ на кресті́ распина́єма зря́щи, єгда́ ору́жіє, Симео́ном предрече́нноє, се́рдце Твоє́ про́йде: ті́мже У́бо, о Ма́ти чадолюби́вая, воньми́ гла́су моле́нія на́шего, уті́ши нас в ско́рбі су́щих, я́ко ві́рная ра́дости хода́тайця. Предстоя́щи престо́лу Пресвяти́я Тро́йці, одесну́ю Си́на Твоєго́, Христа́ Бо́га на́шего, мо́жеши, а́ще восхо́щеши, вся нам поле́зная іспроси́ти: ра́ди с ві́рою серде́чною і любо́вію припа́даєм к Тебі́, я́ко Цари́це і Влади́чице: сли́ши дщи, і виждь, і приклони́ у́хо Твоє́, усли́ши моле́ніє на́ше і ізба́ви нас от обстоя́щих бід і скорбе́й: Ти бо Ра́досте всіх ві́рних, я́ко мир і утіше́ніє подає́ши. Се зри́ши біду́ на́шу і скорб: яви́ нам ми́лость Твою́, посли́ утіше́ніє уя́звленному печа́лію се́рдцю на́шему, покажи́ і удиви́ на нас грі́шних бога́тство милосе́рдія Твоєго́, пода́ждь нам сле́зи покая́нія ко очище́нію гріхо́в на́ших і утоле́нію гні́ва Бо́жия, да с чи́стим се́рдцем, со́вістію благо́ю і наде́ждою несумні́нною прибіга́єм ко Твоєму́ хода́тайству і заступле́нію. Прийми́, Всеми́лостивая на́ша Влади́чице Богоро́дице, усе́рдноє моле́ніє на́ше Тебі́ приноси́моє, і не отри́ни нас недосто́йних от Твоєго́ благосердія, но пода́ждь нам ізбавле́ніє от ско́рби і болі́зні, защити́ нас от вся́каго наві́та вра́жия і клевети́ челові́чеськія, бу́ди нам помо́щниця неотсту́пная во вся дні жи́зні на́шея, я́ко да под Твої́м ма́терним покро́вом всегда́ пребу́дем ці́ли і сохране́ні Твої́м заступле́нієм і моли́твами к Си́ну Твоєму́ і Бо́гу Спаси́телю на́шему, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє, со безнача́льним Єго́ Отце́м і Святи́м Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитви перед іконами Матері Божої «Покров Пресвятої Богородиці»","ps":["О Пресвята́я Ді́во, Ма́ти Го́спода Ви́шніх Сил, Небесе́ і землі́ Цари́це, гра́да і страни́ на́шея всемо́щная Засту́пнице! Прийми́ хвале́бно-благода́рственноє пі́ніє сіє́ от нас, недосто́йних раб Твої́х, і вознеси́ моли́тви на́ша ко Престо́лу Бо́га Си́на Твоєго́, да ми́лостив бу́деть непра́вдам на́шим і проба́вить благода́ть Свою́ чту́щим всечестно́є і́м'я Твоє́ і с ві́рою і любо́вію покланяющимся чудотво́рному о́бразу Твоєму́. Ні́сми бо досто́йні от Него́ поми́ловані би́ти, а́ще не Ти уми́лостивиши Єго́ о нас, Влади́чице, я́ко вся Тебі́ от Него́ возмо́жна суть. Сего́ ра́ди к Тебі́ прибіга́єм, я́ко к несомні́нній і ско́рій Засту́пниці на́шей: усли́ши нас, моля́щихся Тебі́, осіни́ нас вседержа́вним покро́вом Твої́м і іспроси́ у Бо́га Си́на Твоєго́ па́стирем на́шим ре́вность і бді́ніє о душа́х, градоправи́телем му́дрость і си́лу, судія́м пра́вду і нелицеприя́тіє, наста́вником ра́зум і смиренному́дріє, супру́гом любо́в і согла́сіє, ча́дом послуша́ніє, оби́димим терпі́ніє, обидящим страх Бо́жий, скорб'я́щим благоду́шіє, ра́дующимся воздержа́ніє: всім же нам дух ра́зума і благоче́стія, дух милосе́рдія і кро́тости, дух чистоти́ і пра́вди. Єй, Госпоже́ Пресвята́я, умилосе́рдися на немощни́я лю́ди Твоя́; разсі́янния собери́, заблу́ждшия на путь пра́вий наста́ви, ста́рость поддержи́, ю́ния уцілому́дри, младе́нці воспита́й і при́зри на всіх нас призрі́нієм ми́лостиваго Твоєго́ заступле́нія; воздви́гни нас із глубини́ гріхо́вния і просвіти́ серде́чния о́чі на́ша ко зрі́нію спасе́нія; ми́лостива нам бу́ди зді і та́мо, в страні́ земна́го прише́льствія і на Стра́шнім суді́ Си́на Твоєго́; преста́вльшіяся же во ві́рі і покая́нії от житія́ сего́ отці́ і бра́тію на́шу во ві́чній жи́зні со А́нгели і со всі́ми святи́ми жи́ти сотвори́. Ти бо єси́, Госпоже́, Сла́ва небе́сних і Упова́ніє земни́х, Ти по Бо́зі на́ша Наде́ждо і Засту́пнице всіх притека́ющих к Тебі́ с ві́рою. К Тебі́ у́бо мо́лимся і Тебі́, я́ко Всемогу́щей Помо́щнице, са́мі себе́ і друг дру́га і весь живо́т наш предає́м, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитви у відчаї","e":"Prayers in Despair","secs":[{"h":"Молитва","ps":["О Ди́вний Созда́телю, Человіколюби́вий Влади́ко, Многоми́лостивий Го́споди! С се́рдцем сокруше́нним і смире́нним си́це молю́ Тя: не возгнуша́йся грі́шнаго моле́нія моєго́, не отри́ни слез мої́х і воздиха́нія, усли́ши мене́, я́коже ханане́ю, не пре́зри мене́, я́коже блудни́цю, яви́ і на мні, грі́шнім, вели́кую ми́лость человіколю́бія Твоєго́: ри́зою Твоє́ю честно́ю защити́, поми́луй і подкріпи́ м'я, да вся посила́ємия от Тебе́ біди́ і напа́сти со благодаре́нієм в наде́жді ві́чних благ претерплю́; ізря́дніє же печа́ль мою́ на ра́дость претвори́, да не в отча́яніє впаду́ і поги́бну аз, окая́нний. Ти бо єси́ істо́чник ми́лости і непости́дная спасе́нія на́шего наде́жда, Христе́ Бо́же наш, і Тебі́ сла́ву возсила́єм со Безнача́льним Твої́м Отце́м, і Пресвяти́м і Благи́м і Животворя́щим Твої́м Ду́хом, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва","ps":["Владико Господи неба і землі, Царю віків! Благоволи відчинити мені двері покаяння, бо я в болі серця мого благаю Тебе, істинного Бога, Отця Господа нашого Ісуса Христа, Світла світові: поглянь Своїм многим милосердям і прийми моління моє; не відверни його, але прости мені, що впав у численні прогрішення. Бо шукаю спокою і не знаходжу, тому що совість моя не прощає мене. Чекаю миру, а в мені немає миру через глибоку безліч беззаконь моїх. Почуй, Господи, мене, що в розпачі перебуваю. Бо я, позбавлений усякої готовності й усякого прагнення виправити себе, припадаю до щедрот Твоїх: помилуй мене, повергнутого на землю й засудженого за гріхи мої. Оберни, Господи, плач мій на радість мені, розірви веретище й підпережи мене веселістю. І благоволи, щоб я отримав заспокоєння, як обрані Твої, Господи, від яких відбігли хвороби, печаль і зідхання, і нехай відчиняться мені двері Царства Твого, щоб, увійшовши з тими, що насолоджуються світлом лиця Твого, Господи, отримати мені життя вічне у Христі Ісусі Господі нашому. Амінь."]},{"h":"Псалом 39","ps":["Терп'я́, потерпі́х Го́спода, і внят мі, і усли́ша моли́тву мою́. І возведе́ м'я от ро́ва страсте́й, і от бре́нія ти́ни, і поста́ви на ка́мені но́зі мої́, і іспра́ви стопи́ моя́, і вложи́ во уста́ моя́ піснь но́ву, пі́ніє Бо́гу на́шему. У́зрять мно́зі і убоя́ться, і упова́ють на Го́спода. Блаже́н муж, єму́же єсть і́м'я Госпо́днє упова́ніє єго́, і не призрі́ в суєти́ і неістовле́нія ло́жная. Мно́га сотвори́л єси́ Ти, Го́споди, Бо́же мой, чудеса́ Твоя́ і помишле́нієм Твої́м ність кто уподо́биться Тебі́: возвісти́х і глаго́лах, умно́жишася па́че числа́. Же́ртви і приноше́нія не восхоті́л єси́, ті́ло же сверши́л мі єси́, всесожже́ній і о грісі́ не взиска́л єси́. Тогда́ ріх: се прийду́, в глави́зні кни́жні пи́сано єсть о мні: є́же сотвори́ти во́лю Твою́, Бо́же мой, восхоті́х, і зако́н Твой посреді́ чре́ва моєго́. Благовестах пра́вду в це́ркві вели́цій, се устна́м мої́м не возбраню́: Го́споди, Ти разумі́л єси́. Пра́вду Твою́ не скрих в се́рдці моє́м, і́стину Твою́ і спасе́ніє Твоє́ ріх, не скрих ми́лость Твою́ і і́стину Твою́ от со́нма мно́га. Ти же, Го́споди, не удали́ щедро́т Твої́х от мене́: ми́лость Твоя́ і і́стина Твоя́ ви́ну да засту́питі м'я. Я́ко одержа́ша м'я зла́я, і́мже ність числа́, постиго́ша м'я беззако́нія моя́, і не возмого́х зрі́ти, умно́жишася па́че влас глави́ моєя́, і се́рдце моє́ оста́ви м'я. Благоволи́, Го́споди, ізба́вити м'я: Го́споди, во є́же по́мощі мі воньми́. Да постидя́ться і посра́м'яться вку́пі і́щущії ду́шу мою́ із'яти ю, да возвратя́ться всп'ять і постидя́ться хотя́щії мі зла́я. Да при́ймуть а́біє студ свой глаго́лющії мі: бла́гоже, бла́гоже. Да возра́дуються і возвеселя́ться о Тебі́ всі і́щущії Тебі́, Го́споди, і да реку́ть ви́ну: да возвели́читься Госпо́дь, лю́б'ящий спасе́ніє Твоє́. Аз же нищ єсьм і убо́г, Госпо́дь попече́ться о мні. Помо́щник мой і Защи́титель мой єси́ Ти, Бо́же мой, не закосни́."]},{"h":"Святителю Іоанну Золотоустому","ps":["О, святи́телю вели́кий Іоа́нне Златоу́сте! Ти мно́гая і разли́чная дарова́нія от Го́спода прия́л єси́, і я́ко раб благи́й і ві́рний, вся да́нния тебі́ тала́нти до́брі умно́жил єси́: сего́ ра́ди воі́стину вселе́нський учи́тель бил єси́, я́ко всяк во́зраст і вся́ко зва́ніє от тебе́ поуча́ється. Се бо отроко́м послуша́нія о́браз яви́лся єси́, ю́ним – цілому́дрія світи́ло, муже́м – трудолю́бія наста́вник, ста́рим – незло́бія учи́тель, і́ноком – воздержа́нія пра́вило, молящимся – вождь от Бо́га вдохнове́нний, му́дрости іщущим – ума́ просвіти́тель, виті́ям доброглаго́ливим – сло́ва жива́го істо́чник неісчерпа́ємий, благотворящим – милосе́рдія звіздо́, нача́льствующим – правле́нія му́драго о́браз, пра́вди ревни́телем – дерзнове́нія вдохнови́тель, пра́вди ра́ди гони́мим – терпі́нія наста́вник: всім вся бил єси́, да вся́ко ні́кия спасе́ши. Над всі́ми же си́ми стяжа́л єси́ любо́в, я́же єсть сою́з соверше́нства, і то́ю, я́ко си́лою Боже́ственною, вся дарова́нія в душі́ твоє́й во єди́но совокупи́л єси́, і ту́южде любо́в разділе́нная примиря́ющую, в толкова́нії слове́с апо́стольських всім ві́рним пропові́дал єси́. Ми же грі́шнії, по єди́ному ки́йждо своє́ дарова́ніє іму́ще, єдине́нія ду́ха в сою́зі ми́ра не і́мами, но бива́єм тщесла́вії, друг дру́га раздража́юще, друг дру́гу зави́дяще: сего́ ра́ди дарова́нія на́ша разділе́нная не в мир і спасе́ніє, но во вражду́ і осужде́ніє нам преложи́шася. Ті́мже к тебі́, святи́телю Бо́жий, припа́даєм, раби́ Бо́жії (імена́), раздо́ром обурева́ємі, і в сокруше́нії се́рдця про́сим: моли́твами твої́ми отжени́ от серде́ць на́ших вся́ку го́рдость і за́висть, нас разделяющії, да во мно́зіх у́діх єди́но ті́ло церко́вноє невозбра́нно пребу́дем, да по словесі́ твоєму́ моли́твенному возлю́бим друг дру́га і єдиноми́слієм іспові́ми Отця́ і Си́на і Свята́го Ду́ха, Тро́йцю Єдиносу́щную і Неразді́льную, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Преподобному Силуану Афонському","ps":["О преди́вний уго́дниче Бо́жий, о́тче Силуа́не! По благода́ті, тебі́ от Бо́га да́нной, сле́зно моли́тися о всей вселе́нній – ме́ртвих, живи́х і гряду́щих – не премолчи́ за нас ко Го́споду, к тебі́ усе́рдно припа́дающих і твоєго́ предста́тельства уми́льно прося́щих (імена́). Подви́гни, о всеблаже́нне, на моли́тву Усе́рдную Засту́пницю ро́да християнського, Преблагослове́нную Богоро́дицю і Присноді́ву Марі́ю, чу́дно призвавшую тя би́ти ві́рним ді́лателем в Єя́ земно́м вертогра́ді, іді́же ізбра́нници Бо́жії о грісі́х на́ших ми́лостива і долготерпіли́ва би́ти Бо́га умоля́ють, во є́же не пом'янута непра́вд і беззако́ній на́ших, но по неізрече́нной бла́гости Го́спода на́шего Ісу́са Христа́ уще́дрити і спасти́ нас по вели́цій Єго́ ми́лості. Єй, уго́дниче Бо́жий, с Преблагослове́нною Влади́чицею ми́ра – Святейшею Ігуменією Афо́на і святи́ми подвижниками Єя́ земна́го жре́бія іспроси́ у святи́х святейшего Сло́ва святі́й горі́ Афо́нськой і боголюби́вим пустинножителем єя́ от всіх бід і наві́тов вра́жиїх в ми́рі сохрани́тися. Да А́нгели святи́ми от зол ізбавля́ємі і Ду́хом Святи́м во ві́рі і братолю́бії укріпля́ємі, до сконча́нія ві́ка о Єди́ній, Святі́й, Собо́рній і Апо́стольстій Це́ркві моли́тви творя́ть і всім спаси́тельний путь указу́ють, да Це́рков Земна́я і Небе́сная непреста́нно славосло́вить Творця́ і Отця́ Сві́тов, просвіща́ющи і освіща́ющи мир во ві́чной пра́вді і бла́гости Бо́жієй. Наро́дом землі́ всей іспроси́ благоде́нственноє і ми́рноє житіє́, дух смиренному́дрія і братолю́бія, добронра́вія і спасе́нія, дух стра́ха Бо́жия. Да не зло́ба і беззако́ніє ожесточають се́рдця людські́я, могу́щиє істреби́ти любо́в Бо́жию в челові́ціх і низвергнуть їх в богопротивную вражду́ і братоубийство, но в си́лі Боже́ственния любве́ і пра́вди, я́коже на небесі́ і на землі́ да святи́ться і́м'я Бо́жиє, да бу́деть во́ля Єго́ свята́я в челові́ціх, і да воцари́ться мир і Ца́рствіє Бо́жиє на землі́. Та́кожде і земно́му Оте́честву твоєму́ – землі́ Українській іспроси́, уго́дниче Бо́жий, вожделі́нний мир і небе́сноє благослове́ніє, во є́же всемо́щним омофо́ром Ма́тере Бо́жия покрива́єму, ізба́витися єму́ от гла́да, губи́тельства, тру́са, огня́, меча́, наше́ствія іноплеме́нников і междоусо́бния бра́ні і от всіх враг ви́димих і неви́димих, і та́ко святі́йшим домо́м Преблагослове́нния Богоро́диці до сконча́нія ві́ка єму́ преби́ти, Креста́ Животворя́щаго си́лою, і в любві́ Бо́жієй неоскудіва́єму утверди́тися. Нам же всім, во тьму гріхо́в погружа́ємим і покая́нія тепла́, ніже́ стра́ха Бо́жия не іму́щим і си́це безмі́рно лю́б'ящаго нас Го́спода непреста́нно оскорбляющим, іспроси́, о всеблаже́нне, у Всеще́драго Бо́га на́шего, да Своє́ю Всеси́льною благода́тію боже́ственне посіти́ть і оживотвори́ть душі́ на́ша, і вся́ку зло́бу і го́рдость жите́йськую, уни́ніє і нераді́ніє в сердця́х на́ших да упраздни́ть. Єще́ мо́лимся, о є́же і нам, благода́тію Всесвята́го Ду́ха укріпля́ємим і любо́вію Бо́жию согреваємим, в человіколю́бії і братолю́бії, смиренномудренном сраспинанії друг за дру́га і за всіх, в пра́вді Бо́жієй утверди́тися і в благодатной любві́ Бо́жієй благонра́вно укріпи́тися, і синолюбне Тому́ прибли́житися. Да та́ко, творя́ще Єго́ всясвятую во́лю, во вся́ком благоче́стії і чистоті́ вре́меннаго житія́ путь непости́дно пре́йдем і со всі́ми святи́ми Небе́снаго Ца́рствія і Єго́ Агнчаго бра́ка сподо́бимся. Єму́ же от всіх земни́х і небе́сних да бу́деть сла́ва, честь і поклоне́ніє, со Безнача́льним Єго́ Отце́м, Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитви перед іконами Матері Божої «Взискання погибших»","ps":["Засту́пнице усе́рдная, благоутро́бная Го́спода Ма́ти, к Тебі́ прибіга́ю аз окая́нний і па́че всіх челові́ко грішні́йший; воньми́ гла́су моле́нія моєго́, і вопль мой і стена́ніє усли́ши. Я́ко беззако́нія моя́ превзидо́ша главу́ мою́, і аз, я́коже кора́бль в пучи́ні, погружа́юся в мо́ре гріхо́в мої́х. Но Ти, всеблага́я і милосе́рдая Влади́чице, не пре́зри мене́ отча́яннаго і во грісі́х погиба́ющаго; поми́луй м'я, ка́ющагося во злих ді́ліх мої́х, і обрати́ на путь пра́вий заблудшую, окая́нную ду́шу мою́. На Тебі́, Влади́чице моя́ Богоро́дице, возлага́ю все упова́ніє моє́. Ти, Ма́ти Бо́жия, сохрани́ і соблюди́ м'я под кро́вом Твої́м, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитви перед іконами Матері Божої «Поручителька грішних»","ps":["О Влади́чице Преблагослове́нная, защи́тнице ро́да христия́нськаго, прибі́жище і спасе́ніє притека́ющих к Тебі́! Вім, воі́стину вім, я́ко зіло́ согріши́х і прогні́вах, Преми́лостивая Госпоже́, рожде́ннаго пло́тію от Тебе́ Си́на Бо́жия. Но і́мам мно́гая о́брази пре́жде мене́ прогні́вавших Єго́ милосе́рдіє: митарі́, блудни́ці і про́чія грі́шники, і́мже даде́ся проще́ніє гріхо́в їх, покая́нія ра́ди і іспові́данія. Ти́я у́бо о́брази поми́лованних очесе́м грі́шния душі́ моєя́ представля́я і на толи́коє Бо́жиє милосе́рдіє, о́ния приі́мшеє, взира́я, дерзну́х і аз грі́шний прибі́гнути с покая́нієм ко Твоєму́ благосе́рдію. О Всеми́лостивая Влади́чице! Пода́ждь мі ру́ку по́мощі і іспроси́ у Си́на Твоєго́ і Бо́га, Ма́терніми і святі́йшими Твої́ми моли́твами, тя́жким мої́м гріхо́м проще́ніє. Ві́рую і іспові́дую, я́ко Той, Єго́же родила́ єси́, Син Твой єсть воі́стину Христо́с, Син Бо́га Жива́го, Судія́ живи́х і ме́ртвих, воздая́й коєму́ждо по ді́лом Єго́. Ві́рую же па́ки і іспові́дую Тебі́ би́ти і́стинную Богоро́дицю, милосе́рдія істо́чник, утіше́ніє пла́чущих, взиска́ніє поги́бших, си́льную і непрестаю́щую к Бо́гу хода́таїцю, зіло́ лю́б'ящую род христия́нський і спору́чницю покая́нія. Воі́стину бо ність нам іни́я по́мощі і покро́ва, ра́зві Тебе́, Госпоже́ Преми́лостивая, і нікто́же, упова́я на Тя, постиді́ся когда́, і Тобо́ю умоля́я Бо́га, нікто́же оста́влен бисть. Того́ ра́ди і аз Твою́ неісче́тную бла́гость молю́: отве́рзи две́рі милосе́рдія Твоєго́ мні заблу́ждшему і па́дшему в тимі́ніє глубини́, не возгнуша́йся мене́ скве́рнаго, не пре́зри грі́шнаго моле́нія моєго́, не оста́ви мене́ окая́ннаго, я́ко в поги́бель зло́бний враг похи́тити м'я і́щеть, но умоли́ о мні рожде́ннаго от Тебе́ милосе́рдаго Си́на Твоєго́ і Бо́га, да прости́ть вели́кия моя́ гріхи́ і ізба́вить м'я от па́губи моєя́, я́ко да і аз, со всі́ми получи́вшими проще́ніє, воспою́ і просла́влю безмі́рноє милосе́рдіє Бо́жиє і Твоє́ непости́дноє о мні заступле́ніє в жи́зні сей і несконча́ємім ві́ці."]},{"h":"Молитви перед іконами Матері Божої «Утоли моя печалі»","ps":["Наде́ждо всім конце́м землі́, Пречи́стая Ді́во, Госпоже́ Богоро́дице, утіше́ніє на́ше! Не гнуша́йся нас грі́шних, на Твою́ бо ми́лость упова́єм: угаси́ горя́щий в нас пла́мень гріхо́вний і покая́нієм ороси́ ізсо́хшая се́рдця на́ша; очи́сти ум наш от гріхо́вних помисло́в, прийми́ мольби́, от душі́ і се́рдця со воздиха́нієм Тебі́ приноси́мия. Бу́ди о нас хода́тайця к Си́ну Твоєму́ і Бо́гу і отврати́ гнів Єго́ Ма́терніми Твої́ми моли́твами. Душе́вния і тіле́сния я́зви ісціли́, Госпоже́ Влади́чице, утоли́ болі́зні душ і тіле́с, утиши́ бу́рю злих нападе́ній вра́жеських, отими́ бре́м'я гріхо́в на́ших, і не оста́ви нас до конця́ поги́бнути, і печа́лію сокруше́нная се́рдця на́ша уті́ши, да сла́вим Тя до послі́дняго іздиха́нія на́шего."]},{"h":"Молитви перед іконами Матері Божої «Нечаянная Радість»","ps":["О, Пресвята́я Ді́во, Всеблага́го Си́на Ма́ти Всеблага́я, гра́да і свята́го хра́ма сего́ Покрови́тельнице, всіх су́щих во грісі́х, ско́рбіх, біда́х і болі́зніх ві́рная Предста́тельнице і Засту́пнице! Прийми́ моле́бноє пі́ніє сіє́ от нас, недосто́йних рабо́в Твої́х, Тебі́ возноси́моє, і я́коже дре́вле грі́шника, на всяк день мно́гажди пред честно́ю іко́ною Твоє́ю моли́вшагося, не презрі́ла єси́, но дарова́ла єси́ єму́ неча́янную ра́дость покая́нія і приклонила єси́ Си́на Твоєго́ мно́гим і усе́рдним к Нему́ хода́тайством ко проще́нію сего́ грі́шнаго і заблу́ждшагося, та́ко і ни́ні не пре́зри моле́нія нас, недосто́йних рабо́в Твої́х, і умоли́ Си́на Твоєго́ і Бо́га на́шего, да і всім нам с ві́рою і умиле́нієм покланяющимся пред цільбоно́сним о́бразом Твої́м, да́руєть неча́янную по коєго́ждо потре́бі ра́дость: па́стирем цер-ковним – святу́ю ре́вность о спасе́нії пасо́мих; грі́шником, погрязшим во глубині́ зол і страсте́й – вседі́йственноє вразумле́ніє, покая́ніє і спасе́ніє; су́щим в ско́рбіх і печа́ліх – утіше́ніє; обріта́ющихся в біда́х і озлобленіях – соверше́нноє їх ізбитіє́; малоду́шним і ненаде́жним – наде́жду і терпі́ніє; в ра́дості і дово́льстві живу́щим – непреста́нноє Благоді́телю Бо́гу благодаре́ніє; бедствующим – милосе́рдіє; су́щим в болі́зні і долгонеду́жії і оста́вленним врача́ми – неча́янноє ісціле́ніє і укріпле́ніє; іждившим от неду́га ум – ума́ возвраще́ніє і обновле́ніє; отходящим во ві́чную і несконча́ємую жизнь – па́м'ять сме́ртную, умиле́ніє і сокруше́ніє о грісі́х, дух бодр і тве́рдую на милосе́рдіє Бо́жиє наде́жду. О, Госпожі́ Пресвята́я! Умилосе́рдися ко всім, чту́щим всечестно́є і́м'я Твоє́, і всім яви́ всемо́щний покро́в Твой і заступле́ніє; во благоче́стії, чистоті́ і честні́м жи́тельстві пребива́ющия до послі́дняго їх сконча́нія во бла́гости соблюди́; зли́я бла́гі сотвори́; заблу́ждшия на путь пра́вий наста́ви; вся́кому ді́лу благо́му і Си́ну Твоєму́ уго́дному споспі́шествуй; вся́коє ді́ло зло́є і богопроти́вноє разруши́; в недоумі́нії і тру́дних і опа́сних обстоя́ніїх обріта́ющимся незри́мую по́мощ і вразумле́ніє с небе́с низпосли́; от іскуше́ній, собла́знов і поги́белі спаси́; от всіх злих челові́к і от враго́во ви́димих і неви́димих защити́ і сохрани́; пла́вающим спла́вай; путешествующим спутеше́ствуй; су́щим в ну́жді і гла́ді бу́ди Пита́тельниця, неімущим кро́ва і приста́нища бу́ди Покро́в і Прибі́жище; наги́м пода́ждь одія́ніє; оби́димим і от непра́вд стра́ждущим – заступле́ніє; клевету́, поноше́ніє і хуле́ніє терп'ящия незри́мо оправда́й; клеветники́ і хули́телі пред всі́ми обличи́; ожесточе́нно враждующим нечаємо пода́ждь примире́ніє, і всім нам друг ко дру́гу любо́в, мир і благоче́стіє і здра́віє с долгоде́нствієм. Супру́жества в любві́ і єдиноми́слії сохрани́; супру́ги, во вражді́ і разділе́нії су́щия, умири́, соєдини́ друг ко дру́гу і положи́ їм сою́з любве́ неразруши́мий; ма́терем, ді́ти родящим, ско́роє пода́ждь разріше́ніє; младе́нці воспита́й, ю́ния уцілому́дри, отве́рзи ум к восприя́тію вся́каго поле́знаго уче́нія, стра́ху Бо́жию, воздержа́нію і трудолю́бію наста́ви; от дома́шнія бра́ні і вражди́ єдинокро́вних ми́ром і любо́вію огради́. Безма́терніх сиро́т бу́ди Ма́тер, от вся́каго поро́ка і скве́рни отврати́ я і всему́ благо́му і богоуго́дному научи́; прельще́нния же і во гріх і нечистоту́ впадшия, скве́рну гріха́ от'явши, із бе́здни поги́белі ізведи́. Вдов бу́ди Уті́шительниця і Помо́щниця, ста́рости бу́ди жезл. От внеза́пния сме́рті без покая́нія всіх нас ізба́ви, і всім нам христия́нськую кончи́ну живота́ на́шего, безболі́зненну, непости́дну, ми́рну і до́брий отві́т на стра́шном суди́щі Христо́ві да́руй, Преста́вльшіяся во ві́рі і покая́нії от житія́ сего́ со а́нгели і всі́ми святи́ми жи́ти сотвори́; сконча́вшимся внеза́пною сме́ртію ми́лостива би́ти Си́на Твоєго́ умоли́; о всіх усо́пших, і́же не і́муть сро́дников, о упокоє́нії їх Си́на Твоєго́ умоля́ющих, Сама́ бу́ди непреста́нная і те́плая Моли́твенниця і Хода́тайця; да всі на небесі́ і на землі́ ві́дять Тя, я́ко тве́рдую і непости́дную Предста́тельницю ро́да христия́нськаго, сла́в'ять Тя і Тобо́ю Си́на Твоєго́ со Безнача́льним Єго́ Отце́м і Єдиносу́щним Єго́ Ду́хом, ни́ні і при́сно і во ві́ки Віко́в. Амі́нь."]},{"h":"Молитви перед іконами Матері Божої «Покров Пресвятої Богородиці»","ps":["О Пресвята́я Ді́во, Ма́ти Го́спода Ви́шніх Сил, Небесе́ і землі́ Цари́це, гра́да і страни́ на́шея всемо́щная Засту́пнице! Прийми́ хвале́бно-благода́рственноє пі́ніє сіє́ от нас, недосто́йних раб Твої́х, і вознеси́ моли́тви на́ша ко Престо́лу Бо́га Си́на Твоєго́, да ми́лостив бу́деть непра́вдам на́шим і проба́вить благода́ть Свою́ чту́щим всечестно́є і́м'я Твоє́ і с ві́рою і любо́вію покланяющимся чудотво́рному о́бразу Твоєму́. Ні́сми бо досто́йні от Него́ поми́ловані би́ти, а́ще не Ти уми́лостивиши Єго́ о нас, Влади́чице, я́ко вся Тебі́ от Него́ возмо́жна суть. Сего́ ра́ди к Тебі́ прибіга́єм, я́ко к несомні́нній і ско́рій Засту́пниці на́шей: усли́ши нас, моля́щихся Тебі́, осіни́ нас вседержа́вним покро́вом Твої́м і іспроси́ у Бо́га Си́на Твоєго́ па́стирем на́шим ре́вность і бді́ніє о душа́х, градоправи́телем му́дрость і си́лу, судія́м пра́вду і нелицеприя́тіє, наста́вником ра́зум і смиренному́дріє, супру́гом любо́в і согла́сіє, ча́дом послуша́ніє, оби́димим терпі́ніє, обидящим страх Бо́жий, скорб'я́щим благоду́шіє, ра́дующимся воздержа́ніє: всім же нам дух ра́зума і благоче́стія, дух милосе́рдія і кро́тости, дух чистоти́ і пра́вди. Єй, Госпоже́ Пресвята́я, умилосе́рдися на немощни́я лю́ди Твоя́; разсі́янния собери́, заблу́ждшия на путь пра́вий наста́ви, ста́рость поддержи́, ю́ния уцілому́дри, младе́нці воспита́й і при́зри на всіх нас призрі́нієм ми́лостиваго Твоєго́ заступле́нія; воздви́гни нас із глубини́ гріхо́вния і просвіти́ серде́чния о́чі на́ша ко зрі́нію спасе́нія; ми́лостива нам бу́ди зді і та́мо, в страні́ земна́го прише́льствія і на Стра́шнім суді́ Си́на Твоєго́; преста́вльшіяся же во ві́рі і покая́нії от житія́ сего́ отці́ і бра́тію на́шу во ві́чній жи́зні со А́нгели і со всі́ми святи́ми жи́ти сотвори́. Ти бо єси́, Госпоже́, Сла́ва небе́сних і Упова́ніє земни́х, Ти по Бо́зі на́ша Наде́ждо і Засту́пнице всіх притека́ющих к Тебі́ с ві́рою. К Тебі́ у́бо мо́лимся і Тебі́, я́ко Всемогу́щей Помо́щнице, са́мі себе́ і друг дру́га і весь живо́т наш предає́м, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]},{"h":"Псалом 101","ps":["Го́споди, усли́ши моли́тву мою́, і вопль мой к Тебі́ да при́йдеть. Не отврати́ лиця́ Твоєго́ от мене́: во́ньже а́ще день скорблю́, приклони́ ко мні у́хо Твоє́: во́ньже а́ще день призову́ Тя, ско́ро усли́ши м'я. Я́ко ісчезо́ша я́ко дим дні́є мої́, і ко́сті моя́ я́ко суши́ло сосхо́шася. Уя́звен бих я́ко трава́, і і́зсше се́рдце моє́, я́ко заби́х сні́сти хліб мой. От гла́са воздиха́нія моєго́ прильпе́ кость моя́ пло́ті моє́й. Уподо́бихся нея́сити пусти́нній, бих я́ко нощни́й вран на ни́рищі. Бдіх і бих я́ко пти́ця осо́б'ящаяся на зді. Весь день поноша́ху мі вразі́ мої́, і хва́лящії м'я мно́ю кленя́хуся. Зане́ пе́пел я́ко хліб ядя́х, і питіє́ моє́ с пла́чем растворя́х. От лиця́ гні́ва Твоєго́ і я́рости Твоєя́: я́ко возне́с низве́ргл м'я єси́. Дні́є мої́ я́ко сінь уклони́шася, і аз я́ко сі́но ізсхо́х. Ти же, Го́споди, во вік пребива́єши, і па́м'ять Твоя́ в род і род. Ти воскре́с уще́дриши Сіо́на, я́ко вре́м'я уще́дрити єго́, я́ко при́йде вре́м'я. Я́ко благоволи́ша раби́ Твої́ ка́меніє єго́, і персть єго́ уще́дрять. І убоя́ться язи́ци і́мене Госпо́дня, і всі ца́ріє зе́мстії сла́ви Твоєя́. Я́ко сози́ждеть Госпо́дь Сіо́на, і яви́ться во сла́ві Своє́й. Призрі́ на моли́тву смире́нних, і не уничижи́ моле́нія їх. Да напи́шеться сіє́ в род ін, і лю́діє зи́ждемії восхва́лять Го́спода. Я́ко прини́че с висоти́ святи́я Своєя́, Госпо́дь с Небесе́ на зе́млю призрі́, усли́шати воздиха́ніє окова́нних, разріши́ти си́ни умерщвле́нних, возвісти́ти в Сіо́ні і́м'я Госпо́днє, і хвалу́ Єго́ во Ієрусали́мі. Внегда́ собра́тися лю́дем вку́пі і царе́м, є́же рабо́тати Го́сподеві. Отвіща́ єму́ на путі́ крі́пости єго́, умале́ніє дній мої́х возвісти́ мі. Не возведи́ мене́ во преполове́ніє дній мої́х: в ро́ді родо́в лі́та Твоя́. В нача́ліх Ти, Го́споди, зе́млю основа́л єси́, і діла́ ру́ку Твоє́ю суть небеса́. Та поги́бнуть, Ти же пребива́єши, і вся я́ко ри́за обетша́ють, і я́ко оде́жду свіє́ши я, і ізміня́ться. Ти же то́йжде єси́, і лі́та Твоя́ не оскуді́ють. Си́нове раб Твої́х вселя́ться, і сі́м'я їх во вік іспра́виться."]}],"notes":[]},{"u":"Молитва до улюбленого святого","e":"Prayer to a Favourite Saint","secs":[{"ps":["Угоднику Божий (ім’я). Спом’яни нас у твоїх благоприємних молитвах перед Христом Богом, щоб зберіг Він нас від спокус, хвороб і скорбот, щоб дарував нам смирення, любов, розсудливість і лагідність, і щоб удостоїв Він нас, недостойних, Царства Свого. Амінь."]}],"notes":[]},{"u":"Молитва преподобного Нектарія Оптинського","e":"Prayer of St Nectarius of Optina","secs":[{"ps":["§Моліться просто:","«Го́споди, да́руй мні благода́ть Твою́!»","§На вас насувається хмара скорбот, а ви моліться: «Господи, даруй мені благодать Твою!» І Господь пронесе повз вас грозу."]}],"notes":[]},{"u":"Молитва про зміцнення й дарування мудрості святителя Миколая Сербського (Велимировича)","e":"Prayer for Strength and the Gift of Wisdom by St Nikolaj Velimirović","secs":[{"ps":["Боже Милостивий, невичерпне, єдине джерело сили, зміцни мене, немічного, обдаруй силою більшою, щоб я міг краще служити Тобі. Боже, дай мені мудрості, щоб отриману від Тебе силу я не вжив на зло, а лише на добро собі та ближнім моїм для звеличання слави Твоєї. Амінь."]}],"notes":[]},{"u":"Щоденне сповідання гріхів","e":"Daily Confession of Sins","secs":[{"ps":["Іспові́даю Тебі́ Го́споду Бо́гу моєму́ і Творцю́, во Святі́й Тро́йці Єди́ному, сла́вимому і покланя́ємому, Отцю́ і Си́ну і Свято́му Ду́ху, вся моя́ гріхи́, я́же соді́ях во вся дні живота́ моєго́, і на вся́кий час, і в настоя́щеє вре́м'я, і в преше́дшия дні і но́щі, ді́лом, сло́вом, помишле́нієм, об'яде́нієм, пія́нством, тайнояде́нієм, праздносло́вієм, уни́нієм, лі́ностію, прекосло́вієм, непослуша́нієм, оклевета́нієм, осужде́нієм, небреже́нієм, самолю́бієм, многостяжа́нієм, хище́нієм, неправдоглаго́ланієм, скверноприби́тчеством, мшелої́мством, ревнова́нієм, за́вистію, гні́вом, пам'ятозло́бієм, не́навистію, лихої́мством і всі́ми мої́ми чу́встви: зрі́нієм, слу́хом, обоня́нієм, вку́сом, осяза́нієм і про́чими мої́ми гріхи́, душе́вними вку́пі і тіле́сними, ї́миже Тебе́ Бо́га моєго́ і Творця́ прогні́вах, і бли́жняго моєго́ онепра́вдовах: о сих жалі́я, ви́нна себе́ Тебі́ Бо́гу моєму́ представля́ю, і імі́ю во́лю ка́ятися: то́чію, Го́споди Бо́же мой, помози́ мі, со слеза́ми смире́нно молю́ Тя: преше́дшая же согріше́нія моя́ милосе́рдієм Твої́м прости́ мі, і разріши́ от всіх сих, я́же ізглаго́лах пред Тобо́ю, я́ко Благ і Человіколю́бець."]}],"notes":[]},{"u":"Молитва тих, хто йде до лісу","e":"Prayer of Those Going into the Forest","secs":[{"ps":["Бо́же святи́й і во святи́х почива́яй, трисвяти́м гла́сом на небесі́ от А́нгел воспіва́ємий, на землі́ от челові́к во святи́х Свої́х хвали́мий: да́вий Святи́м Твої́м Ду́хом кому́ждо благода́ть по мі́рі дарова́нія Христо́ва, і то́ю поста́вивий Це́ркві Твоє́й святі́й о́ви Апо́столи, о́ви проро́ки, о́ви же благові́стники, о́ви па́стирі і учи́тели, їх же сло́вом про́повіді. Тебі́ Самому́ ді́йствующему вся во всіх, мно́зі соверши́шася святі́ї в ко́ємждо ро́ді і ро́ді, разли́чними доброді́тельми благоугоди́вшії Тебі́, і к Тебі́ нам о́браз до́брих по́двигов свої́х оста́вивше, в ра́дості преше́дшії, гото́ві, в нем же са́мі іскуше́ни би́ша, і нам напа́ствуємим помога́ти. Сих святи́х всіх воспомина́я і їх богоуго́дноє похваля́я житіє́, Тебі́ Самаго́, в них ді́йствовавшаго, восхваля́ю, і о́ніх благотворе́нія Твоя́ дарова́нія би́ти ві́руя, прилі́жно молю́ Тя, Свя́те святи́х, даждь мі грі́шному послі́довати їх уче́нію, па́че те Твоє́ю вседі́йствующею благода́тію, небе́сния с ни́ми сподо́битися сла́ви, хва́ляще пресвято́є і́м'я Твоє́, Отця́ і Си́на і Свята́го Ду́ха во ві́ки. Амі́нь."]}],"notes":[]},{"u":"Молитва після сну","e":"Prayer on Waking","secs":[{"ps":["Слава Тобі, Христе Боже мій, що Ти не погубив мене з беззаконнями моїми, але досі ще терпиш гріхи мої. Дай мені, Господи, покласти добрий початок, щоб у цей день, що настав, ні ділом, ні думкою не розгнівати мені Тебе, Створителя мого, але щоб усі мої діла, бажання, поради й думки були на славу Пречистого Твого Імені."]}],"notes":[]},{"u":"Молитовне правило преподобного Амвросія Оптинського, що читається під час спокус","e":"Prayer Rule of St Ambrose of Optina, Read in Times of Temptation","secs":[{"ps":["§Преподобний старець Амвросій Оптинський пропонував тим, хто звертався до нього в найрізноманітніших скорботах і напастях, особливі короткі молитовні правила, посильні для кожного християнина. Старець зі свого досвіду знав, як діють ці молитви, як зміцнюють ослаблий дух людини, як руйнуються підступи ворожі, якщо читати ці молитви з вірою і надією на всемогутню допомогу Божу. Ми наводимо тут ці правила, складені з псалмів Давидових, разом з уривками з листів преподобного Амвросія. З ЛИСТІВ ПРЕПОДОБНОГО АМВРОСІЯ ОПТИНСЬКОГО. Надійся на милість і допомогу Божу й вір, що Господь силен визволити тебе від усіх підступів людських і ворожих. Сказано в псалмах: «Господь руйнує поради народів і відкидає думки людей; рада ж Господня пребуває повік». Виписую тобі псалми, якими молився святий Давид, коли був гнаний ворогами: 3-й, 53-й, 58-й, 142-й. Добери з цих псалмів слова, які тобі пасують, і часто перечитуй їх, звертаючись до Бога з вірою і смиренням. А коли тебе долатиме зневіра чи томитиме душу безпричинна скорбота — перечитуй 101-й псалом."]},{"h":"Псалом 3","ps":["Го́споди, что ся умно́жиша стужа́ющії мі? Мно́зі востаю́ть на м'я, мно́зі глаго́лють душі́ моє́й: ність спасе́нія єму́ в Бо́зі єго́. Ти же, Го́споди, Засту́пник мой єси́, сла́ва моя́ і вознося́й главу́ мою́. Гла́сом мої́м ко Го́споду воззва́х, і усли́ша м'я от гори́ святи́я Своєя́. Аз усну́х, і спах, воста́х, я́ко Госпо́дь засту́пить м'я. Не убою́ся от тім люде́й, о́крест напа́дающих на м'я. Воскресни́, Го́споди, спаси́ м'я, Бо́же мой, я́ко Ти порази́л єси́ вся вражду́ющия мі всу́є: зу́би грі́шников сокруши́л єси́. Госпо́днє єсть спасе́ніє, і на лю́діх Твої́х благослове́ніє Твоє́."]},{"h":"Псалом 53","ps":["Бо́же, во і́м'я Твоє́ спаси́ м'я і в си́лі Твоє́й суди́ мі. Бо́же, усли́ши моли́тву мою́, внуши́ глаго́ли уст мої́х. Я́ко чу́ждії воста́ша на м'я, і крі́пції взиска́ша ду́шу мою́, і не предложи́ша Бо́га пред собо́ю. Се бо Бог помога́єть мі, і Госпо́дь Засту́пник душі́ моє́й. Отврати́ть зла́я враго́м мої́м, і́стиною Твоє́ю потреби́ їх. Во́лею пожру́ Тебі́, іспові́мся і́мені Твоєму́, Го́споди, я́ко бла́го, я́ко от вся́кия печа́лі ізба́вил м'я єси́, і на враги́ моя́ воззрі́ о́ко моє́."]},{"h":"Псалом 58","ps":["Ізми́ м'я от враг мої́х, Бо́же, і от востаю́щих на м'я ізба́ви м'я. Ізба́ви м'я от ді́лающих беззако́ніє і от муж крове́й спаси́ м'я. Я́ко се улови́ша ду́шу мою́, нападо́ша на м'я крі́пції, ніже́ беззако́ніє моє́, ніже́ гріх мой, Го́споди. Без беззако́нія теко́х і іспра́вих, воста́ни в срі́теніє моє́ і виждь. І Ти, Го́споди Бо́же сил, Бо́же Ізра́їлев, воньми́ посіти́ти вся язи́ки, да не уще́дриши вся ді́лающия беззако́ніє. Возвратя́ться на ве́чер і вза́лчуть, я́ко пес, і оби́дуть град. Се ті́ї отвіща́ють усти́ свої́ми, і меч во устна́х їх, я́ко кто сли́ша? І Ти, Го́споди, посміє́шися їм, уничижи́ши вся язи́ки. Держа́ву мою́ к Тебі́ сохраню́, я́ко Ти, Бо́же, Засту́пник мой єси́. Бог мой, ми́лость Єго́ предвари́ть м'я, Бог мой, яви́ть мні на вразі́х мої́х. Не уби́й їх, да не когда́ забу́дуть зако́н Твой, расточи́ я си́лою Твоє́ю, і низведи́ я, Защи́тниче мой, Го́споди. Гріх уст їх, сло́во усте́н їх, і я́ти да бу́дуть в горди́ні своє́й, і от кля́тви і лжі возвістя́ться в кончи́ні. Во гні́ві кончи́ни, і не бу́дуть: і уві́дять, я́ко Бог влади́чествуєть Іа́ковом і конці́ землі́. Возвратя́ться на ве́чер, і вза́лчуть, я́ко пес, і оби́дуть град. Ті́ї рази́дуться я́сти. А́ще ли же не наси́тяться, і поро́пщуть. Аз же воспою́ си́лу Твою́ і возра́дуюся зау́тра о ми́лості Твоє́й, я́ко бил єси́ Засту́пник мой і Прибі́жище моє́ в день ско́рби моєя́. Помо́щник мой єси́, Тебі́ пою́: я́ко Бог Засту́пник мой єси́, Бо́же мой, ми́лость моя́."]},{"h":"Псалом 142","ps":["Го́споди, усли́ши моли́тву мою́, внуши́ моле́ніє моє́ во і́стині Твоє́й, усли́ши м'я в пра́вді Твоє́й: і не вни́ди в суд с рабо́м Твої́м, я́ко не оправди́ться пред Тобо́ю всяк живи́й. Я́ко погна́ враг ду́шу мою́, смири́л єсть в зе́млю живо́т мой, посади́л м'я єсть в те́мних, я́ко ме́ртвия ві́ка. І уни́ во мні дух мой, во мні см'яте́ся се́рдце моє́. Пом'яну́х дні дре́внія, поучи́хся во всіх ді́ліх Твої́х, в творе́ніїх руку́ Твоє́ю поуча́хся. Возді́х к Тебі́ ру́ці мої́, душа́ моя́, я́ко земля́ безво́дная Тебі́. Ско́ро усли́ши м'я, Го́споди, ісчезе́ дух мой, не отврати́ лиця́ Твоєго́ от мене́, і уподо́блюся низходя́щим в ров. Сли́шану сотвори́ мні зау́тра ми́лость Твою́, я́ко на Тя упова́х. Скажи́ мні, Го́споди, путь, во́ньже пойду́, я́ко к Тебі́ взях ду́шу мою́. Ізми́ м'я от враг мої́х, Го́споди, к Тебі́ прибіго́х. Научи́ м'я твори́ти во́лю Твою́, я́ко Ти єси́ Бог мой. Дух Твой Благи́й наста́вить м'я на зе́млю пра́ву. І́мене Твоєго́ ра́ди, Го́споди, живи́ши м'я, пра́вдою Твоє́ю ізведе́ши от печа́лі ду́шу мою́. І ми́лостію Твоє́ю потреби́ши враги́ моя́ і погуби́ши вся стужа́ющия душі́ моє́й, я́ко аз раб Твой єсьм."]},{"h":"Псалом 101","ps":["Го́споди, усли́ши моли́тву мою́, і вопль мой к Тебі́ да при́йдеть. Не отврати́ лиця́ Твоєго́ от мене́: во́ньже а́ще день скорблю́, приклони́ ко мні у́хо Твоє́: во́ньже а́ще день призову́ Тя, ско́ро усли́ши м'я. Я́ко ісчезо́ша я́ко дим дні́є мої́, і ко́сті моя́ я́ко суши́ло сосхо́шася. Уя́звен бих я́ко трава́, і і́зсше се́рдце моє́, я́ко заби́х сні́сти хліб мой. От гла́са воздиха́нія моєго́ прильне́ кость моя́ пло́ті моє́й. Уподо́бихся нея́сити пусти́нній, бих я́ко нощни́й вран на ни́рищі. Бдіх і бих я́ко пти́ця осо́б'ящаяся на зді. Весь день поноша́ху мі вразі́ мої́, і хва́лящії м'я мно́ю кленя́хуся. Зане́ пе́пел я́ко хліб ядя́х, і питіє́ моє́ с пла́чем растворя́х. От лиця́ гні́ва Твоєго́ і я́рости Твоєя́: я́ко возне́с низве́ргл м'я єси́. Дні́є мої́ я́ко сінь уклони́шася, і аз я́ко сі́но ізсхо́х. Ти же, Го́споди, во вік пребива́єши, і па́м'ять Твоя́ в род і род. Ти воскре́с уще́дриши Сіо́на, я́ко вре́м'я уще́дрити єго́, я́ко приї́де вре́м'я. Я́ко благоволи́ша раби́ Твої́ ка́меніє єго́, і персть єго́ уще́дрять. І убоя́ться язи́ци і́мене Госпо́дня, і всі ца́ріє зе́мстії сла́ви Твоєя́. Я́ко сози́ждеть Госпо́дь Сіо́на, і яви́ться во сла́ві Своє́й. Призрі́ на моли́тву смире́нних, і не уничижи́ моле́нія їх. Да напи́шеться сіє́ в род ін, і лю́діє зи́ждемії восхва́лять Го́спода. Я́ко прини́че с висоти́ святи́я Своєя́, Госпо́дь с Небесе́ на зе́млю призрі́, усли́шати воздиха́ніє окова́нних, разріши́ти си́ни умерщвле́нних, возвісти́ти в Сіо́ні і́м'я Госпо́днє, і хвалу́ Єго́ во Ієрусали́мі. Внегда́ собра́тися лю́дем вку́пі і царе́м, є́же рабо́тати Го́сподеві. Отвіща́ Єму́ на путі́ крі́пости Єго́: умале́ніє дній мої́х возвісти́ мі. Не возведи́ мене́ во преполове́ніє дній мої́х: в ро́ді родо́в лі́та Твоя́. В нача́ліх Ти, Го́споди, зе́млю основа́л єси́, і діла́ руку́ Твоє́ю суть небеса́. Та поги́бнуть, Ти же пребива́єши, і вся я́ко ри́за обетша́ють, і я́ко оде́жду свіє́ши я, і ізміня́ться. Ти же то́йжде єси́, і лі́та Твоя́ не оскуді́ють. Си́нове раб Твої́х вселя́ться, і сі́м'я їх во вік іспра́виться.","§З ЛИСТІВ ПРЕПОДОБНОГО АМВРОСІЯ ОПТИНСЬКОГО. Листа твого отримав, але на другому тижні посту не встиг відписати, ось і третій тиждень уже добігає кінця. Знову скажу тобі, що, на мою думку, треба ще зачекати й потерпіти, доки подіє промислительна сила Божа, що руйнує неправильні поради й відкидає думки недобродійних людей; бо одна лише рада Божа пребуває повіки. Щоб у твоєму становищі отримати милість і допомогу Божу, читай щодня псалом 36: «Не ревнуй лукавим і не заздри тим, що чинять беззаконня» І добре було б читати цей псалом за словом святого Давида — ввечері, вранці й опівдні. І ще два псалми — «Госпо́дь просвіще́ніє моє́» та «Живи́й в по́мощі Ви́шняго». Якщо в ім’я Святої Тройці будеш старанно читати ці псалми щодня по три рази зі смиренням і ревністю, віддаючи себе всеблагому Промислу Божому, тоді Він виведе; тільки покорися Господеві й благай Його. Корисно також читати псалом «Терп'я́, потерпі́х Го́спода, і внят мі». Недарма сказано в Святому Письмі, що багатьма скорботами належить нам увійти в Царство Небесне, заради здобуття якого ми й вступили до монастиря."]},{"h":"Псалом 36","ps":["Не ревну́й лука́внующим, ніже́ зави́ди творя́щим беззако́ніє. Зане́ я́ко трава́ ско́ро і́зсшуть, і я́ко зе́ліє зла́ка ско́ро отпаду́ть. Упова́й на Го́спода, і твори́ благости́ню, і насели́ зе́млю, і упасе́шися в бога́тстві єя́. Наслади́ся Го́сподеві, і дасть ті проше́нія се́рдця твоєго́. Откри́й ко Го́споду путь твой, і упова́й на Него́, і Той сотвори́ть: і ізведе́ть я́ко світ пра́вду твою́ і судьбу́ твою́ я́ко полу́дне. Повини́ся Го́сподеві і умоли́ Єго́. Не ревну́й спі́ющему в путі́ своє́м челові́ку, творя́щему законопреступле́ніє. Преста́ни от гні́ва і оста́ви я́рость: не ревну́й, є́же лука́вновати. Зане́ лука́внующії потреб'я́ться, терп'я́щії же Го́спода, ті́ї наслі́дять зе́млю. І єще́ ма́ло, і не бу́деть грі́шника: і взи́щеши мі́сто єго́, і не обря́щеши. Кро́тції же наслі́дять зе́млю і насладя́ться о мно́жестві ми́ра. Назира́єть грі́шний пра́веднаго і поскреже́щеть нань зуби́ свої́ми. Госпо́дь же посміє́ться єму́, зане́ презира́єть, я́ко при́йдеть день єго́. Меч ізвлеко́ша грі́шници, напряго́ша лук свой, низложи́ти убо́га і ни́ща, закла́ти пра́вия се́рдцем. Меч їх да вни́деть в сердця́ їх, і лу́ци їх да сокруша́ться. Лу́чше ма́лоє пра́веднику, па́че бога́тства грі́шних мно́га. Зане́ ми́шці грі́шних сокруша́ться, утвержда́єть же пра́ведния Госпо́дь. Вість Госпо́дь путі́ непоро́чних, і достоя́ніє їх во вік бу́деть. Не постидя́ться во вре́м'я лю́тоє, і во днех гла́да наси́тяться, я́ко грі́шници поги́бнуть. Вразі́ же Госпо́дні, ку́пно просла́витися їм і вознести́ся, ісчеза́юще я́ко дим ісчезо́ша. Зає́млеть грі́шний і не возврати́ть, пра́ведний же ще́дрить і дає́ть. Я́ко благослов'я́щії Єго́ наслі́дять зе́млю, клену́щії же Єго́ потреб'я́ться. От Го́спода стопи́ челові́ку ісправля́ються, і путі́ єго́ восхо́щеть зіло́. Єгда́ паде́ть, не разбіє́ться, я́ко Госпо́дь подкріпля́єть ру́ку єго́. Юні́йший бих, і́бо состарі́хся, і не ви́діх пра́ведника оста́влена, ніже́ сі́мені єго́ прося́ща хлі́би. Весь день ми́луєть і взаї́м дає́ть пра́ведний, і сі́м'я єго́ во благослове́ніє бу́деть. Уклони́ся от зла, і сотвори́ бла́го, і всели́ся во вік ві́ка. Я́ко Госпо́дь лю́бить суд і не оста́вить преподо́бних Свої́х, во вік сохраня́ться. Беззако́нници же ізжену́ться, і сі́м'я нечести́вих потреби́ться. Пра́ведници же наслі́дять зе́млю і вселя́ться во вік ві́ка на ней. Уста́ пра́веднаго поуча́ться прему́дрості, і язи́к єго́ возглаго́леть суд. Зако́н Бо́га єго́ в се́рдці єго́, і не за́пнуться стопи́ єго́. Сматря́єть грі́шний пра́веднаго і і́щеть є́же умертви́ти єго́. Госпо́дь же не оста́вить єго́ в руку́ єго́, ніже́ осу́дить єго́, єгда́ су́дить єму́. Потерпи́ Го́спода, і сохрани́ путь Єго́, і вознесе́ть тя, є́же наслі́дити зе́млю, внегда́ потребля́тися грі́шником, у́зриши. Ви́діх нечести́ваго превознося́щася і ви́сящася, я́ко ке́дри Лива́нськия. І ми́мо ідо́х, і се не бі, і взиска́х єго́, і не обрі́теся мі́сто єго́. Храни́ незло́біє і виждь правоту́, я́ко єсть оста́нок челові́ку ми́рну. Беззако́нници же потреб'я́ться вку́пі: оста́нці же нечести́вих потреб'я́ться. Спасе́ніє же пра́ведних от Го́спода, і Защи́титель їх єсть во вре́м'я ско́рби. І помо́жеть їм Госпо́дь, і ізба́вить їх, і і́зметь їх от грі́шник, і спасе́ть їх, я́ко упова́ша на Него́."]},{"h":"Псалом 26","ps":["Госпо́дь просвіще́ніє моє́ і Спаси́тель мой, кого́ убою́ся? Госпо́дь Защи́титель живота́ моєго́, от кого́ устрашу́ся? Внегда́ приближа́тися на м'я зло́бующим, є́же сні́сти пло́ті моя́, оскорбля́ющії м'я, і вразі́ мої́, ті́ї ізнемого́ша і падо́ша. А́ще ополчи́ться на м'я полк, не убої́ться се́рдце моє́, а́ще воста́неть на м'я брань, на Него́ аз упова́ю. Єди́но проси́х от Го́спода, то взищу́: є́же жи́ти мі в дому́ Госпо́дні вся дні живота́ моєго́, зрі́ти мі красоту́ Госпо́дню і посіща́ти храм святи́й Єго́. Я́ко скри м'я в селе́нії Своє́м в день зол мої́х, покри́ м'я в та́йні селе́нія Своєго́, на ка́мень вознесе́ м'я. І ни́ні, се вознесе́ главу́ мою́ на враги́ моя́: обидо́х і пожро́х в селе́нії Єго́ же́ртву хвале́нія і воскликнове́нія, пою́ і воспою́ Го́сподеві. Усли́ши, Го́споди, глас мой, і́мже воззва́х: поми́луй м'я і усли́ши м'я. Тебі́ рече́ се́рдце моє́: Го́спода взищу́. Взиська́ Тебі́ лице́ моє́, лиця́ Твоєго́, Го́споди, взищу́. Не отврати́ лиця́ Твоєго́ от мене́ і не уклони́ся гні́вом от раба́ Твоєго́: помо́щник мой бу́ди, не отри́ни мене́, і не оста́ви мене́, Бо́же Спаси́телю мой. Я́ко оте́ць мой і ма́ти моя́ оста́виста м'я, Госпо́дь же восприя́т м'я. Законоположи́ мі, Го́споди, в путі́ Твоє́м і наста́ви м'я на стезю́ пра́вую враг мої́х ра́ди. Не преда́ждь мене́ в ду́ші стужа́ющих мі, я́ко воста́ша на м'я свиді́теле непра́веднії і солга́ непра́вда себі́. Ві́рую ви́діти блага́я Госпо́дня на землі́ живи́х. Потерпи́ Го́спода, мужа́йся і да кріпи́ться се́рдце твоє́, і потерпи́ Го́спода."]},{"h":"Псалом 90","ps":["Живи́й в по́мощі Ви́шняго, в кро́ві Бо́га Небе́снаго водвори́ться. Рече́ть Го́сподеві: Засту́пник мой єси́ і Прибі́жище моє́, Бог мой, і упова́ю на Него́. Я́ко Той ізба́вить тя от сі́ті ло́вчі, і от словесе́ м'яте́жна, плещма́ Свої́ма осіни́ть тя, і под крилі́ Єго́ наді́єшися: ору́жієм оби́деть тя і́стина Єго́. Не убої́шися от стра́ха нощна́го, от стріли́ летя́щия во дні, от ве́щі во тьмі преходя́щия, от сря́ща і бі́са полу́деннаго. Паде́ть от страни́ твоєя́ ти́сяща, і тьма одесну́ю тебе́, к тебі́ же не прибли́житься, оба́че очи́ма твої́ма смо́триши, і воздая́ніє грі́шников у́зриши. Я́ко Ти, Го́споди, упова́ніє моє́, Ви́шняго положи́л єси́ прибі́жище твоє́. Не при́йдеть к тебі́ зло, і ра́на не прибли́житься тілесі́ твоєму́, я́ко А́нгелом Свої́м запові́сть о тебі́, сохрани́ти тя во всіх путеіх твої́х. На рука́х во́зьмуть тя, да не когда́ преткне́ши о ка́мень но́гу твою́, на а́спида і васили́ска насту́пиши, і попере́ши льва і змі́я. Я́ко на М'я упова́, і ізба́влю ї: покри́ю ї, я́ко позна́ і́м'я Моє́. Воззове́ть ко Мні, і усли́шу єго́: с ним єсьм в ско́рбі, ізму́ єго́, і просла́влю єго́, долгото́ю дній іспо́лню єго́, і явлю́ єму́ спасе́ніє Моє́."]},{"h":"Псалом 39","ps":["Терп'я́, потерпі́х Го́спода, і внят мі, і усли́ша моли́тву мою́. І возведе́ м'я от ро́ва страсте́й, і от бре́нія ти́ни, і поста́ви на ка́мені но́зі мої́, і іспра́ви стопи́ моя́, і вложи́ во уста́ моя́ піснь но́ву, пі́ніє Бо́гу на́шему. У́зрять мно́зі і убоя́ться, і упова́ють на Го́спода. Блаже́н муж, єму́же єсть і́м'я Госпо́днє упова́ніє єго́, і не призрі́ в суєти́ і неістовле́нія ло́жная. Мно́га сотвори́л єси́ Ти, Го́споди, Бо́же мой, чудеса́ Твоя́ і помишле́нієм Твої́м ність кто уподо́биться Тебі́: возвісти́х і глаго́лах, умно́жишася па́че числа́. Же́ртви і приноше́нія не восхоті́л єси́, ті́ло же сверши́л мі єси́, всесожже́ній і о грісі́ не взиска́л єси́. Тогда́ ріх: се прийду́, в глави́зні кни́жні пи́сано єсть о мні: є́же сотвори́ти во́лю Твою́, Бо́же мой, восхоті́х, і зако́н Твой посреді́ чре́ва моєго́. Благовісти́х пра́вду в це́ркві вели́цій, се устна́м мої́м не возбраню́: Го́споди, Ти разумі́л єси́. Пра́вду Твою́ не скрих в се́рдці моє́м, і́стину Твою́ і спасе́ніє Твоє́ ріх, не скрих ми́лость Твою́ і і́стину Твою́ от со́нма мно́га. Ти же, Го́споди, не удали́ щедро́т Твої́х от мене́: ми́лость Твоя́ і і́стина Твоя́ ви́ну да засту́питі м'я. Я́ко одержа́ша м'я зла́я, і́мже ність числа́, постиго́ша м'я беззако́нія моя́, і не возмого́х зрі́ти, умно́жишася па́че влас глави́ моєя́, і се́рдце моє́ оста́ви м'я. Благоволи́, Го́споди, ізба́вити м'я: Го́споди, во є́же помощі́ мі воньми́. Да постидя́ться і посра́м'яться вку́пі і́щущії ду́шу мою́ із'я́ти ю, да возвратя́ться всп'ять і постидя́ться хотя́щії мі зла́я. Да при́ймуть а́біє студ свой глаго́лющії мі: бла́гоже, бла́гоже. Да возра́дуються і возвеселя́ться о Тебі́ всі і́щущії Тебі́, Го́споди, і да реку́ть ви́ну: да возвели́читься Госпо́дь, лю́б'ящії спасе́ніє Твоє́. Аз же нищ єсьм і убо́г, Госпо́дь попече́ться о мні. Помо́щник мой і Защи́титель мой єси́ Ти, Бо́же мой, не закосни́."]}],"notes":[]},{"u":"Молитва св. Івана Кронштадтського при марнославних помислах","e":"Prayer of St John of Kronstadt against Vainglorious Thoughts","secs":[{"ps":["Господи, не дай мені уявити себе кращим за когось із людей, але вважати себе гіршим за всіх і нікого не осуджувати, а себе судити суворо. Амінь."]}],"notes":[]},{"u":"Молитва, що читається під час поширення шкідливого поморку","e":"Prayer Read When a Harmful Plague Spreads","secs":[{"ps":["Го́споди Бо́же наш, не вни́ди в суд с раби́ Твої́ми, і огради́ нас от губи́тельнаго пове́трія на ни дви́жимаго. Пощади́ нас смире́нних і недосто́йних рабо́в Твої́х, в покая́нії с те́плою ві́рою і сокруше́нієм серде́чним к Тебі́ милосе́рдному і благопремени́тельному Бо́гу на́шему припа́дающих і на ми́лость Твою́ упова́ющих. Твоє́ бо єсть, є́же ми́ловати і спаса́ти ни, Бо́же наш, і Тебі́ сла́ву возсила́єм, Отцю́, і Си́ну, і Свято́му Ду́ху, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва під час згубного поморку і смертоносної пошесті","e":"Prayer in a Time of Deadly Plague and Pestilence","secs":[{"ps":["Бо́же Вели́кий і Ви́шній, Благоутро́бний і Человіколюби́вий Влади́ко, усли́ши нас недосто́йних рабо́в Твої́х, во мно́жестві ми́лости Твоєя́ і низпосли́ нам по́мощ Твою́ во вре́м'я наше́ствія болі́зні губи́тельния на род челові́чеський, Твоє́ю Кро́вію іску́пленний.","Ві́ми Го́споди, я́ко согріши́хом пред Лице́м Твої́м і гріхо́м на́шим ність числа́. Но умилосе́рдися і отврати́ от нас гнів Твой пра́ведний на ни дви́жимий. Не прогні́вайся на ни зіло́, Ти бо рекл єси́, я́ко ра́дость бива́єть на небесі́ о єди́ном грі́шниці ка́ющемся. Прийми́ ни́ні і на́ше покая́ніє, сле́зи і смире́нния моли́тви возноси́мия із глубини́ серде́ць на́ших пред святи́м олтаре́м Твої́м.","О́тче щедро́т, Бо́же вся́кого утіше́нія, укріпи́ ни моли́твами Преблагослове́нния Влади́чиці на́шея Богоро́диці, си́лою Честна́го і Животворя́щего Креста́, свята́го великому́ченика і ціли́теля Пантелеї́мона, святи́теля Лу́ки, іспові́дника Кри́мськаго, святи́х враче́й і ціли́телей на́ших: Ага́пита, Дамія́на, Іпа́тія Пече́рських і Всіх святи́х землі́ на́шея і прекрати́ болі́зненноє пове́тріє і отжени́ от нас вся́кую болі́знь і не́мощ, да ізба́вльшеся от вся́кия напа́сти Руко́ю Твоє́ю крі́пкою, порабо́таєм Ті со вся́ким благодаре́нієм. Да я́ко і ни́ні причаща́ющеся Твоєго́ неізглаго́ланнаго Человіколю́бія, поє́м і сла́вим Тя, Творя́щаго вели́кая і чу́дная, сла́вная же і ізря́дная.","Я́ко Ти єси́ Істо́чник ісціле́ній, Бо́же наш, і Тебі́ сла́ву возсила́єм, Отцю́ і Си́ну, і Свято́му Ду́ху, ни́ні і при́сно, і во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва перед виходом в інтернет","e":"Prayer before Going Online","secs":[{"ps":["Го́споди Бо́же наш, Тво́рче не́ба і землі́, созда́вий челові́ка і дарова́вий єму́ ві́дініє сокрове́нной прему́дрости, во є́же прославля́ти і́м'я Твоє́, горе́ і до́лу Ти єси́, Твоє́ єсть ноч і Твоє́ єсть день, не утая́ться пред Тобо́ю да́же мимолетниє движе́нія ми́слі.","І ни́ні молю́ Тя, от вся́каго гріха́ сохрани́ м'я, приступа́ющаго к рабо́ті с хитроумним творе́нієм рук челові́чеських, проникающим во вся конці́ землі́.","Огради́ о́чі мої́ і ум мой от вся́ких нечи́стих і блу́дних образо́в, от пусти́х і негодних слове́с.","Укріпи́ во́лю, се́рдце очи́сти, не даждь мі вотще́ расточа́ти вре́м'я жи́зні моєя́, і от вся́каго расслабленія і уни́нія ізба́ви.","Да бу́дуть діла́ на́ші во сла́ву Твою́!","Амі́нь."]}],"notes":[]},{"u":"Молитва про християнську кончину з келійної книжиці о. Івана (Крестьянкіна)","e":"Prayer for a Christian End from the Cell Book of Fr John (Krestyankin)","secs":[{"ps":["Го́споди, Ісу́се Христе́, вре́м'я житія́ моєго́ сокраща́ється, приближа́ється ко врата́м сме́рті; бою́ся і трепе́щу сме́ртнаго часа́, сего́ о́гненнаго креще́нія, і́бо грі́шен всім; се́рдце моє́ страши́ться виді́нія лука́вих духо́в, і́щущих моє́й поги́белі; ужаса́єть м'я прохожде́ніє возду́шних мита́рств – сей пра́ведний суд Твой, на нем же і́мам сло́во возда́ти о всіх, я́же согріши́х в житії́: страши́ть м'я о́ная неві́домая страна́, в ню же вселиши м'я по моє́м преставле́нії.","Го́споди, Человіколю́бче, не хотя́й сме́рти грі́шника, но є́же обрати́тися і живу́ би́ти єму́, поми́луй м'я, к тебі́ обращающегося, сопричти́ м'я ста́ду твоєму́ і сподо́би м'я улучи́ти христия́нськую кончи́ну живота́ моєго́ – безболі́зненну, непости́дну, ми́рну. Се аз, многогрі́шний, пре́жде о́наго сме́ртнаго часа́ припа́даю к Тебі́ і с наде́ждою на Твоя́ спаси́тельния страда́нія і кре́стную смерть приношу́ сле́зноє покая́ніє о всіх грісі́х і беззако́ніях мої́х во́льних і нево́льних, ведо́мих і неві́домих, прости́ вся гріхи́ і беззако́нія і огне́м Свята́го Ду́ха Твоєго́ ми́лостиво іспепели́ я, да не пом'яну́ться они́ при кончи́ні живота́ моєго́.","Прости́, Го́споди, всякіє оби́ди і огорче́нія, нанесенниє мні бли́жніми мої́ми, і поми́луй всіх ненави́дящих і оби́дящих м'я, да отиду́ от житія́ сего́ в ми́рі со всі́ми людьми́. Да́руй мі про́чеє вре́м'я живота́ моєго́ пребива́ти в чистоті́ і честно́м жи́тельстві і окончить о́ноє в ми́рі і покая́нії.","Перед кончиной моє́й, о ми́лостивий Го́споди, сподо́би м'я прия́ти Пречи́стия і Животворя́щия Та́йни – Святі́йшеє Ті́ло і Кров Твої́; да очище́нний і освяще́нний прича́стієм сих небе́сних Тайн, возмогу́ срі́сти послі́дній сме́ртний час бестрепетно Тобо́ю – Всеблаги́м Господом – сохраня́ємий і огражда́ємий от всіх напа́стей і іскуше́ній. Всемогу́щею си́лою Твоє́ю ізба́ви м'я в о́ний сме́ртний час от нападе́ній і наси́льства лука́вих де́монов, огради́ м'я от них святи́ми А́нгели Твої́ми, подкріпи́ і умири́ тогда́ немощну́ю ду́шу мою́ предста́тельством Пресвяти́я Богоро́диці і Святи́х Твої́х. Сподо́би м'я ми́рно пройти́ возду́шния мита́рства с тве́рдой надеждой на Тя – Спаси́теля моєго́.","Єй, Влади́ко, Го́споди! Не лиши́ м'я Твоєя́ бога́тия ми́лости і заступле́нія в стра́шний час сме́рти моєя́, прийми́ тогда́ ду́шу мою́, я́ко да і аз, многогрі́шний і недосто́йний по ми́лості Твоє́й сподоблюсь в жи́зні бу́дущей би́ти с Тобо́ю – Істо́чником всякого бла́га і возноси́ти Тебі́ моли́тви і славосло́вія во ві́ки віко́в. Амі́нь."]}],"notes":[]},{"u":"Молитва дзвонаря","e":"Prayer of a Bell-Ringer","secs":[{"h":"Молитва 1","ps":["Господи, благослови мене вдарити в ці дзвони! Нехай прославиться Ім’я Твоє Святе!"]},{"h":"Молитва 2","ps":["Вся́чеськая єди́ною в нача́лі Собо́ю непосре́дственні созда́вий, Го́споди, ни́ні же вся посре́дственні ді́йствуяй, гла́сом зво́на сего́ освяще́ннаго вся́коє уни́ніє с ліни́вством от серде́ць ві́рних Твої́х отжени́, страх же Твой в них с благоче́стієм вкорени́ і спі́шних на моли́тву, ско́рих же ко вся́кому благо́му ді́лу Твоє́ю си́лою сотвори́, избавля́я нас от всіх наві́тов вра́жиїх, і невре́дних от злорастворе́нних возду́хов заві́тренія соблюда́я, моли́твами Богоро́диці і всіх святи́х Твої́х, я́ко Єди́н Милосе́рд."]}],"notes":[]},{"u":"Молитва покаянна преподобного Антіоха","e":"Penitential Prayer of St Antiochus","secs":[{"ps":["§(цю молитву заповів читати преподобний Серафим Саровський)","Дерза́я, Влади́ко, на бе́здну благоутро́бія Твоєго́, приношу́ Тебі́ от скве́рних уст і нечи́стих усте́н моли́тву сію́: пом'яни́, я́ко призва́ся на мні і́м'я свято́є Твоє́, і іскупи́л м'я єси́ ціно́ю Кро́ве Твоєя́, я́ко запечатлі́л м'я єси́ обруче́нієм Свята́го Ду́ха Твоєго́, і возве́л м'я єси́ от глубини́ беззако́ній мої́х; да не похи́тить м'я враг. Ісу́се Христе́, заступи́ м'я і бу́ди мі Помо́щник крі́пкий в бра́ні, я́ко раб єсьм по́хоті і воюєм от нея́. Но Ти, Го́споди, не оста́ви м'я на землі́ пове́ржена во осужде́нії діл мої́х: свободи́ м'я, Влади́ко, лука́ваго ра́бства миродержи́теля і усво́ї м'я в за́повідях Твої́х. Путь живота́ моєго́, Христе́ (Бо́же) мой, і світ оче́й мої́х - лице́ Твоє́. Бо́же, Влади́ко і Го́споди, возноше́нія оче́й мої́х не даждь мі і по́хоть злу́ю отста́ви от мене́; заступи́ м'я руко́ю Твоє́ю свято́ю. Пожела́нія і похотствованія да не обимуть м'я, і душе́ бесстидней не преда́ждь мене́. Просвіти́ во мні світ лиця́ Твоєго́, Го́споди, да не обиметь мене́ тьма, і ходя́щії в ней да не похи́тять м'я. Не преда́ждь, Го́споди, звіре́м неви́димим ду́шу, іспові́дающуюся Тебі́. Не попусти́, Го́споди, уязви́тися рабу́ Твоєму́ от псов чужди́х. Прия́телище Свята́го Ду́ха Твоєго́ би́ти м'я сподо́би і дом Христа́ Твоєго́, О́тче Святи́й, сози́жди м'я. Путеводи́телю заблу́ждших, путеводствуй м'я, да не уклоню́ся в шу́яя. Лице́ Твоє́, Го́споди, ви́діти вожделіх. Бо́же, сві́том лиця́ Твоєго́ путеводи́ м'я. Істо́чник слез да́руй мі, рабу́ Твоєму́, і ро́су Свята́го Ду́ха даждь созда́нію Твоєму́, да не іссохну, я́ко смоко́вниця, ю́же Ти прокля́л єси́: і да бу́дуть сле́зи питіє́м мої́м і моли́тва пи́щею моє́ю. Обрати́, Го́споди, плач мой в ра́дость мні, і прийми́ м'я во ві́чния Твої́ ски́нії. Да пости́гнеть м'я ми́лость Твоя́, Го́споди, і щедро́ти Твої́ да обимуть м'я, і отпусти́ вся гріхи́ моя́. Ти бо єси́ Бог і́стинний, отпуща́яй беззако́нія. І не попусти́, Го́споди, посрами́тися ді́лу рук Твої́х по мно́жеству беззако́ній мої́х, но воззови́ м'я, Влади́ко, Єдиноро́дним Твої́м Сино́м, Спаси́телем на́шим. І воздви́гни м'я лежа́щаго, я́ко Леві́ю митаря́, і оживотвори́ м'я, гріхми́ умерщвле́ннаго, я́ко си́на вдови́ці. Ти бо єди́н єси́ воскресе́ніє ме́ртвих, і Тебі́ сла́ва подоба́єть во ві́ки. Амі́нь."]}],"notes":[]},{"u":"Молитва тих, хто в зневірі й відчаї","e":"Prayer of Those in Despondency and Despair","secs":[{"ps":["§(цю молитву заповів читати преподобний Серафим Саровський)","Владико, Господи неба і землі, Царю віків! Благоволи відчинити мені двері покаяння, бо я в болі серця благаю Тебе, істинного Бога, Отця Господа нашого Ісуса Христа, Світла світові, поглянь Своїм многим милосердям і прийми моління моє, не відверни його, але прости мені, що впав у численні прогрішення. Прихили вухо Твоє до моління мого і прости мені все зле, що вчинив я, переможений моєю волею. Бо шукаю спокою і не знаходжу, тому що совість моя не прощає мене. Чекаю миру, а в мені немає миру через глибоку безліч беззаконь моїх. Почуй, Господи, серце, що волає до Тебе, не зважай на злі діла мої, але поглянь на біль душі моєї і поспіши зцілити мене, жорстоко пораненого. Дай мені час покаяння заради благодаті чоловіколюбства Твого і визволи мене від безчесних діл, і не відміряй мені за правдою Твоєю і не віддай мені гідне за ділами моїми, щоб не загинути мені цілковито.","Почуй мене, Господи, що в розпачі перебуваю. Бо я, позбавлений усякого прагнення виправити себе, припадаю до щедрот Твоїх: помилуй мене, повергнутого на землю й засудженого за гріхи мої. Поклич мене, Владико, полоненого й утримуваного моїми злими вчинками, мов ланцюгами скутого. Бо Ти Один умієш розв’язувати в’язнів, лікувати рани, нікому не відомі, які знаєш лише Ти, що відаєш потаємне. І тому в усіх моїх злих недугах кличу лише Тебе — Лікаря всіх страждущих, Двері тих, що ридають зовні, Путь заблудлих, Світло затьмарених, Викупителя ув’язнених, що завжди стримуєш десницю Свою і втримуєш гнів Свій, приготований на грішників, але задля великого чоловіколюбства даєш час на покаяння. Засяй мені світло Лиця Твого, Владико, тяжко падшому, швидкий у милості й повільний у карі. І Твоїм милосердям простягни мені руку й підніми мене з рова беззаконь моїх. Бо Ти Один Бог наш, що не радієш про погибель грішників і не відвертаєш лиця Свого від того, хто молиться Тобі зі сльозами. Почуй, Господи, голос раба Твого, що волає до Тебе, і яви світло Твоє на мені, позбавленому світла, і даруй мені благодать, щоб я, не маючи жодної надії, завжди надіявся на допомогу й силу Твою. Оберни, Господи, плач мій на радість мені, розірви веретище й підпережи мене веселістю. І благоволи, щоб я заспокоївся від вечірніх діл моїх, і щоб отримав заспокоєння ранішнє, як обрані Твої, Господи, від яких відбігли хвороба, печаль і зідхання, і нехай відчиняться мені двері Царства Твого, щоб, увійшовши з тими, що насолоджуються світлом Лиця Твого, Господи, отримати мені життя вічне у Христі Ісусі Господі нашому. Амінь."]}],"notes":[]},{"u":"Молитва батьків про дітей, які перебувають на службі в армії","e":"Prayer of Parents for Children Serving in the Army","secs":[{"ps":["Го́споди Ісу́се Христе́, Си́не Бо́жий, моли́тв ра́ди Пречи́стия Твоєя́ Ма́тері усли́ши м'я, недосто́йную рабу́ [іли́ раба́] (і́м'я). Го́споди, в милостивой вла́сті Твоє́й ча́да моя́ [іли́ ча́до моє́], раби́ Твоя́ (імена́), поми́луй і спаси́ їх, І́мені Твоєго́ ра́ди. Го́споди, прости́ їм все согріше́нія во́льниє і нево́льниє, соверше́нниє і́ми пред Тобо́ю. Го́споди, наста́ви їх на і́стинний путь Твої́х за́повідей, і ра́зум просвіти́ сві́том Христо́вим во спасе́ніє душі́ і ісціле́ніє ті́ла. Го́споди, благослови́ їх слу́жбу в армії, на су́ші, возду́хі і в мо́ре, в путі́, летанії і пла́ванії і на ка́ждом мі́сті Твоєго́ влади́чества. Го́споди, сохрани́ їх си́лою Честного і Животворящего Креста́ Твоєго́ под кро́вом Твої́м святи́м от летящей пули, стрі́ли, меча́, огня́, от смертоносной ра́ни, водного потопле́нія і напрасной сме́рті. Го́споди, огради́ їх от вся́ких ви́димих і неви́димих враго́в, от вся́кой біди́, зол, несча́стій, преда́тель ства і плі́на. Го́споди, ісціли́ їх от вся́кой болі́зні і ра́ни, от вся́кия скве́рни і облегчи́ їх душевниє страда́нія. Го́споди, да́руй їм благода́ть Ду́ха Твоєго́ Свята́го на мно́гіє годи жи́зні, здра́вія і цілому́дрія во вся́ком благоче́стії і любві́ в ми́рі і єдиноду́шії с окружающими їх начальствующими, бли́жніми і дальними людьми́. Го́споди, умнож і укріпи́ їм умственниє способнос ті і тіле́сниє си́ли, здра́ви і благополучни возврати́ їх в роди́тельський дом.","Всеблагий Господи, даруй мені, недостойній і грішній рабі Твоїй (ім’я), батьківське благословення на дітей моїх (імена) нині, вранці, вдень, уночі, бо Царство Твоє вічне, всесильне й всемогутнє. Амінь."]}],"notes":[]},{"u":"Молитва православного лікаря перед початком робочого дня","e":"Prayer of an Orthodox Doctor before the Working Day","secs":[{"ps":["Господи, благослови мій прийдешній день. Благослови мене з любов’ю й терпінням приймати всіх хворих, які прийдуть до мене. Не дай забути, що всі вони послані Тобою. Вразуми й просвіти мене, допоможи правильно ставити діагнози й лікувати хворих моїх, усіх, кого Ти вручаєш у руки мої. У всьому наставляй і вразумляй мене. Дай мені духа безкорисливості, незлобивості, милосердя й співчуття до хворих моїх. Спом’яни їх у тілесній і душевній скорботі й подай терпіння в хворобі, зцілення душі й тіла, каяття в гріхах своїх. Хрест хвороби нехай послужить їм на спасіння. Мирний дух подай мені з колегами й співробітниками моїми. Через служіння моє нехай прославиться Святе ім’я Твоє, Отця, і Сина, і Святого Духа. Дякую Тобі за все. Амінь."]}],"notes":[]},{"u":"Молитва про дарування мудрості","e":"Prayer for the Gift of Wisdom","secs":[{"ps":["§З Молитвослова митрополита Мануїла (Лемешевського)","Владико Господи! Ісусе Христе, Премудросте Отчая! Не відкидай моїх молитовних зідхань і заступництвом наймудрішого з-поміж усіх людей роду людського царя Соломона та праведного Ісуса, сина Сирахового, відвідай мене, наділи мене бодай найменшою часткою цієї Божественної мудрості, такої потрібної [святителям] у керуванні серцями і справами людськими.","Сердцеві́дче Ісу́се! Ти видиш всю наготу́ і скве́рну душі́ моєя́. Умилосердствуй мні і па́ки не отверга́й проше́нія моєго́ к Тебі́, но посіти́ Своє́ю бла́гостію се́рдце і ум мой!","Знаю, що не в багатослівній молитві пізнається людина, а в безкорисливому служінні Господу Богу своєму. Амінь."]}],"notes":[]},{"u":"Молитва про дарування смирення","e":"Prayer for the Gift of Humility","secs":[{"ps":["Господи, дай мені смиренного духа Твого, щоб не втратив я Твоєї благодаті й не став ридати за нею, як ридав Адам за раєм і Богом. Господи, Ти Милостивий; скажи мені, що я маю робити, щоб упокорилася душа моя? Господи, удостой нас дару Твого святого смирення. Господи, даруй нам безкоштовно смиренного Духа Твого Святого, як безкоштовно прийшов Ти спасти людей і піднести їх на небо, щоб бачили славу Твою. Пресвята Матір Господа, випроси, Милостива, нам смиренного духа. Усі Святі, ви живете на небесах і бачите славу Господню, і радіє дух ваш, — моліться, щоб і нам бути з вами."]}],"notes":[]},{"u":"Передсмертна молитва ієросхимонаха Парфенія Київського","e":"Deathbed Prayer of Hieroschemamonk Parthenius of Kyiv","secs":[{"ps":["1. Коли я, пригнічений хворобою, відчую наближення кончини земного буття мого: Господи, помилуй мене.","2. Коли бідне серце моє при останніх ударах своїх занемагатиме й томитиметься смертними муками: Господи, помилуй мене.","3. Коли очі мої востаннє зрошаться сльозами при думці, що впродовж мого життя ображав я Тебе, Боже, гріхами моїми: Господи, помилуй мене.","4. Коли часте биття серця почне прискорювати відхід душі моєї: Господи, помилуй мене.","5. Коли смертна блідість обличчя мого й холонуче тіло моє вразить страхом близьких моїх: Господи, помилуй мене.","6. Коли зір мій затьмариться, обірветься голос, скам’яніє язик мій: Господи, помилуй мене.","7. Коли страшні привиди й видіння почнуть доводити мене до розпачу в Твоєму милосерді: Господи, помилуй мене.","8. Коли душа моя, вражена спогадами про мої провини й страхом суду Твого, знеможе в боротьбі з ворогами мого спасіння, що силкуються затягти мене в область мороку мук: Господи, помилуй мене.","9. Коли смертний піт зросить мене і душа з болісними стражданнями віддалятиметься від тіла: Господи, помилуй мене.","10. Коли смертна пітьма закриє від помутнілого погляду мого всі предмети світу цього: Господи, помилуй мене.","11. Коли в тілі моєму припиниться все відчуття, заціпенітимуть жили й скам’яніють м’язи мої: Господи, помилуй мене.","12. Коли до слуху мого вже не доходитимуть людські мови й земні звуки: Господи, помилуй мене.","13. Коли душа постане перед лицем Твоїм, Боже, в очікуванні Твого призначення: Господи, помилуй мене.","14. Коли почну слухати праведний вирок суду Твого, що визначає вічну долю мою: Господи, помилуй мене.","15. Коли тіло, залишене душею, стане здобиччю червів і тління і, нарешті, весь склад мій перетвориться на жменю праху: Господи, помилуй мене.","16. Коли сурмний голос збудить усіх при другому Твоєму пришесті й розкриється книга діянь моїх: Господи Ісусе Христе, Сину Божий, помилуй мене, грішного раба Твого (ім’я). У руки Твої, Господи, віддаю дух мій. Амінь."]}],"notes":[]},{"u":"Молитва про припинення воєн і мир усього світу","e":"Prayer for an End to Wars and for Peace in the Whole World","secs":[{"ps":["§Молитву про мир склав святитель Афанасій (Сахаров) під час війни.","Влади́ко Вседержи́телю, Святи́й Царю́! При́зри с небе́с і виждь, ка́ко вражду́ють наро́ди і замишляють друг на дру́га су́єтноє і зло́бноє, ка́ко содрагаються все от воспомина́нія о би́вших ужасах воє́нних і трепе́щуть от ожиданія уготовля́ємих но́вих, єще́ бо́ліє стра́шних.","О Многоми́лостиве! Умилосердись о созда́ніях Твої́х. Прости́ гріхи́ і беззако́нія на́ші, їх же ра́ди мно́гія ско́рби, біди́ і устраше́нія прийдо́ша на нас. Благода́тію Пресвятого Ду́ха ороси́ ізсо́хшия любо́вію се́рдця людські́я, те́рніями самолю́бія, не́нависті і за́висти, зло́би, вражди́ і лука́вства і іни́х беззако́ній поросшия, да возрастять они́ горя́щую к тебі́ і к бра́тіям любо́в, і є́ю да бу́дуть істреблени́ все ра́спри, раздо́ри, разділе́нія, междоусо́бія і во́йни, да все наро́ди не уста́ми єди́ними глаго́лють о ми́рі, но всім се́рдцем возлюби́вше єго́ непритворно раскую́ть мечі́ свої́ і копя на ору́дія ми́рнаго ді́ланія і к ми́рному то́кмо ді́лу обратя́ться.","Человіколюби́вий і Ми́лостивий! Усе́рдно мо́лим Тя: мир ми́ру Твоєму́ да́руй, Це́рквам Твої́м, людям правосла́вним і всім твореніям Твої́м. Ти бо єси́ Цар ми́ра і ми́ра Твоєго́ ність преді́ла, і Тебі́ сла́ва і благодаре́ніє і поклоне́ніє от всіх да возсилається, і ни́ні і при́сно і до сконча́нія ві́ка віко́в. Амі́нь"]}],"notes":[]},{"u":"Молитва ранішня Івана Кронштадтського","e":"Morning Prayer of John of Kronstadt","secs":[{"ps":["Боже! Творче й Владико світу! Поглянь милостиво на створіння Твоє, прикрашене Твоїм божественним образом, у ці ранішні години: нехай оживить, нехай просвітить Твоє Око, у незліченну кількість разів світліше за промені сонячні, мою душу темну й умертвлену гріхом. Відніми від мене зневіру й лінощі, даруй же мені радість і бадьорість душевну, щоб у радості серця мого славив я Твою благість, святість, Твоє безмежну велич, безконечні Твої досконалості в кожну годину й на кожному місці. Бо Ти Творець мій і Владика життя мого, Господи, і Тобі належить слава від розумних створінь Твоїх у кожну годину, нині і повсякчас, і на віки віків. Амінь.","Пра́ведний Іоа́нн Кроншта́дтський. Моя́ жизнь во Христі́. Том 1. 71."]}],"notes":[]}];
export default D;
